    const piv=P.an,rot=(deg)=>{const c=Math.cos(rad(deg)),s=Math.sin(rad(deg));const R={};for(const k in P){const x=P[k][0]-piv[0],y=P[k][1]-piv[1];R[k]=[piv[0]+x*c-y*s,piv[1]+x*s+y*c]}return R};
    let lo=-40,hi=40,best=P;
