window.FEST={"3_4_Sit-Up":[["اتمدد على ضهرك وركبك مثنية والدراعين على صدرك","اطلع بجذعك لحد تلات أرباع الطريق وابطنك مشدودة","انزل ببطء من غير ما تشد رقبتك"],["Lie on your back, knees bent, arms crossed on chest.","Curl up about three quarters of the way, abs tight.","Lower slowly without pulling on your neck."]],"90_90_Hamstring":[["اتمدد على ضهرك وارفع رجل لحد ما الركبة والورك ٩٠ درجة","افرد الركبة ببطء لحد ما تحس بشد في ورا الفخذ","ثبّت 20-30 ثانية وبدّل الرجل"],["Lie on your back, raise one leg with hip and knee at 90 degrees.","Slowly straighten the knee until you feel a hamstring stretch.","Hold 20-30 seconds, then switch legs."]],"Ab_Crunch_Machine":[["اقعد على الجهاز واظبط الوسادة وامسك المقابض","اضغط بجذعك لقدام وقوّس بطنك وطلّع النفس","ارجع ببطء من غير ما تسيب الوزن يخبط"],["Sit on the machine, adjust the pad and grip the handles.","Crunch forward, curling your abs and exhaling.","Return slowly without letting the weight slam."]],"Adductor_Groin":[["اقعد وكعوب رجليك مضمومة ووشوش الرجل لبعض","اسند كوعك على فخذك وادفع الركب لتحت بلطف","ثبّت 20-30 ثانية وضهرك مفرود"],["Sit with the soles of your feet together.","Gently press your knees toward the floor with your elbows.","Hold 20-30 seconds, keeping your back straight."]],"Adductor":[["اقعد على الجهاز وحط رجليك على الوسائد وهي مفتوحة","ضم رجليك لبعض ببطء لحد ما الوسايد تتقابل","افتح ببطء وانت متحكم في الوزن"],["Sit on the machine with legs on the pads, set apart.","Squeeze your thighs together slowly until the pads meet.","Open back up slowly, controlling the weight."]],"Advanced_Kettlebell_Windmill":[["ارفع الكيتل بيل فوق راسك بدراع مفرودة وبص عليها","ادفع الورك للجنب وانزل بجذعك وإيدك التانية على رجلك","اطلع ببطء وركبك شبه مفرودة وضهرك مفرود"],["Press the kettlebell overhead with a locked-straight arm, eyes on it.","Push your hip out and lower your torso, free hand sliding down your leg.","Return slowly, keeping your back flat and the bell stable."]],"All_Fours_Quad_Stretch":[["ابدأ على أربع وإيديك تحت كتفك","امسك كاحل رجل وشدها ناحية المؤخرة بلطف","ثبّت 20-30 ثانية وبدّل الرجل"],["Start on all fours, hands under shoulders.","Grab one ankle and gently pull your heel toward your glutes.","Hold 20-30 seconds, then switch legs."]],"Alternate_Hammer_Curl":[["قف ماسك دامبل في كل إيد وكفوفك ناحية بعض","اثني دراع واحد لفوق من غير ما تحرك الكوع","انزل ببطء وبدّل الدراع التاني"],["Stand holding dumbbells with palms facing each other.","Curl one arm up without moving your elbow.","Lower slowly, then alternate arms."]],"Alternate_Incline_Dumbbell_Curl":[["اقعد على بنش مائل وضهرك مسنود والدراعين نازلين","اثني دراع لفوق مع لف الكف لقدام","انزل ببطء لحد ما تفرد الدراع وبدّل"],["Sit back on an incline bench, arms hanging down.","Curl one dumbbell up, turning your palm forward.","Lower slowly to full stretch, then alternate."]],"Alternate_Leg_Diagonal_Bound":[["ابدأ واقف وخد خطوة صغيرة وانت مرن الركب","اقفز بقوة بشكل قطري من رجل للرجل التانية","اهبط بخفة على ركبة مثنية وكرر بالتبادل"],["Start standing with a short run-up and soft knees.","Bound diagonally, driving off one leg to land on the other.","Land softly with a bent knee, then repeat alternating."]],"Alternating_Cable_Shoulder_Press":[["اقف قدام الكابل وامسك مقبض في مستوى الكتف","اضغط دراع واحد فوق راسك من غير ما تقوّس ضهرك","انزل ببطء وبدّل الدراع"],["Stand facing the cable, handle at shoulder height.","Press one arm overhead without arching your back.","Lower slowly, then alternate arms."]],"Alternating_Deltoid_Raise":[["قف ماسك دامبل قدام فخذك وكفوفك لتحت","ارفع دراع لقدام لحد مستوى الكتف وكوعك مفرود شوية","انزل ببطء وبدّل الدراع"],["Stand holding dumbbells in front of thighs, palms down.","Raise one arm forward to shoulder height, elbow slightly soft.","Lower slowly, then alternate arms."]],"Alternating_Floor_Press":[["اتمدد على الأرض وامسك كيتل بيل وركبك مثنية","اضغط الكيتل بيل لفوق لحد ما الدراع تتفرد","انزل ببطء لحد ما الكوع يلمس الأرض وبدّل"],["Lie on the floor, knees bent, holding a kettlebell at your chest.","Press the kettlebell up until your arm is straight.","Lower slowly until your elbow touches the floor, then switch."]],"Alternating_Hang_Clean":[["قف وامسك كيتل بيل بين رجليك وضهرك مفرود","اسحب الكيتل لفوق بدفع الورك وخليه يستقر عند الكتف","نزّله بتحكم لوضع البداية وبدّل الإيد"],["Stand holding a kettlebell between your legs, back flat.","Drive your hips forward and pull the bell up to the rack position.","Lower it under control to the start, then switch hands."]],"Alternating_Kettlebell_Press":[["امسك كيتل بيل عند الكتف في كل إيد وبطنك مشدودة","اضغط كيتل بيل لفوق لحد ما الدراع تتفرد","نزّله ببطء لكتفك وبدّل الدراع"],["Hold a kettlebell at each shoulder, core braced.","Press one kettlebell overhead until your arm is straight.","Lower it slowly to the shoulder, then alternate."]],"Alternating_Kettlebell_Row":[["انحنى من الورك وضهرك مفرود وكيتل بيل في كل إيد","اسحب كيتل بيل ناحية خصرك وشد لوح الكتف","نزّله ببطء وبدّل الدراع"],["Hinge at the hips, back flat, a kettlebell in each hand.","Row one kettlebell toward your waist, squeezing your shoulder blade.","Lower slowly, then alternate arms."]],"Alternating_Renegade_Row":[["خد وضع بلانك بإيديك على دامبل أو كيتل بيل ورجلك واسعة","اسحب وزن واحد ناحية خصرك وجسمك ثابت","نزّله ببطء وبدّل الدراع من غير ما تلف الورك"],["Get in a plank with hands on weights, feet wide.","Row one weight to your waist while keeping your body steady.","Lower slowly, then switch without rotating your hips."]],"Ankle_Circles":[["اقعد أو اتمدد وارفع رجل عن الأرض","لف كاحلك في دوائر كبيرة وبطيئة","اعمل 10 دوائر في كل اتجاه وبدّل الرجل"],["Sit or lie down and lift one foot off the floor.","Rotate your ankle in slow, large circles.","Do 10 circles each direction, then switch feet."]],"Ankle_On_The_Knee":[["اتمدد على ضهرك وركبك مثنية وحط كاحل رجل على ركبة التانية","امسك فخذ الرجل السفلية وشدها ناحيتك","ثبّت 20-30 ثانية وبدّل الرجل"],["Lie on your back with knees bent, one ankle crossed over the opposite knee.","Hold the lower thigh and pull it toward your chest.","Hold 20-30 seconds, then switch legs."]],"Anterior_Tibialis-SMR":[["اركع وحط الفوم رولر تحت الساق من قدام","ادحرج الرول ببطء من الركبة لحد الكاحل","وقّف على أي نقطة مشدودة ثواني قبل ما تكمل"],["Kneel with the foam roller under the front of your shin.","Roll slowly from just below the knee toward the ankle.","Pause on tight spots for a few seconds before continuing."]],"Anti-Gravity_Press":[["اتمدد على بنش على وشك وامسك البار بإيديك","ارفع البار فوق راسك وانت بتفرد دراعك","نزّله ببطء ولا تقفل مفاصلك بقوة"],["Lie face down on an incline bench holding a barbell.","Raise the bar up and overhead, extending your arms.","Lower slowly and avoid locking your joints hard."]],"Arm_Circles":[["قف وافتح دراعك للجنب بمستوى الكتف","لف دراعك في دوائر صغيرة ثم كبيرة","اعمل 10-15 دايرة وغيّر الاتجاه"],["Stand and extend your arms out to your sides at shoulder height.","Rotate them in small circles, then larger ones.","Do 10-15 circles, then reverse direction."]],"Around_The_Worlds":[["اتمدد على بنش ماسك دامبل فوق صدرك وكفوفك لفوق","نزّل الدراعين في قوس واسع لحد ما يوصلوا جنب جسمك","ارجع بنفس القوس ودراعك مفرودة شوية"],["Lie on a bench holding dumbbells above your chest, palms up.","Lower your arms in a wide arc out to your sides.","Return along the same arc with elbows slightly bent."]],"Atlas_Stone_Trainer":[["قف جنب الحجر وانحني وفرد ضهرك ولف دراعك حواليه","شد الحجر لحجرك واقف بدفع الورك لقدام","حطه بتحكم على منصة أو الأرض وضهرك مفرود"],["Stand over the stone, hinge down, and wrap your arms around it.","Lift it to your lap and stand by driving your hips forward.","Place it under control on a platform or floor, back flat."]],"Atlas_Stones":[["انحني ولف دراعك حوالين الحجر وضهرك مفرود","ارفع الحجر لحجرك واقف بدفع الورك","حطه على منصة أو الكتف وانزل بتحكم"],["Hinge down and wrap your arms around the stone, back flat.","Lift it to your lap, then stand up driving with your hips.","Load it onto a platform or shoulder, then lower under control."]],"Axle_Deadlift":[["قف قدام البار السميك وامسكه بقبضة قوية وضهرك مفرود","ارفع البار بدفع الأرض بالرجل وفرد الورك","انزل بالبار بتحكم وضهرك مفرود"],["Stand over the thick bar and grip it firmly, back flat.","Lift by pushing the floor away and extending your hips.","Lower the bar under control, keeping your back flat."]],"Back_Flyes_-_With_Bands":[["ثبّت الباند ومسكه بإيديك وانحني للأمام شوية","افتح دراعك للجنب وشد لوح الكتف","ارجع ببطء وضهرك مفرود"],["Anchor the band, hold the ends, and hinge slightly forward.","Pull your arms out to the sides, squeezing your shoulder blades.","Return slowly, keeping your back flat."]],"Backward_Drag":[["اربط الزحافة وامسك الحبال وامشي بضهرك","اسحب الزحافة بخطوات للخلف وركبك مثنية","خليك مشدود الجسم ومتخبطش ركبك"],["Attach the sled, hold the strap, and face the sled.","Walk backward pulling the sled with bent knees.","Stay braced and keep your steps controlled."]],"Backward_Medicine_Ball_Throw":[["قف وامسك الميديسن بول بين رجليك وركبك مثنية","ارمي الكورة لورا فوق راسك بسرعة وانت بتفرد جسمك","اهبط بخفة وكرر بتحكم"],["Stand with the medicine ball between your legs, knees bent.","Explosively extend and throw the ball backward overhead.","Land softly and reset under control."]],"Balance_Board":[["اطلع بحذر على لوح التوازن وقدميك واسعة ومتوازنة","اضغط بلطف وحافظ على اللوح من غير ما يلمس الأرض","انزل بحذر وحافظ على ركبك مرنة"],["Step carefully onto the balance board, feet shoulder-width apart.","Shift gently and keep the board from touching the floor.","Step off carefully, keeping your knees soft."]],"Ball_Leg_Curl":[["اتمدد على ضهرك وحط كعوب رجليك على الكورة وارفع الحوض","اثني رجليك لتسحب الكورة ناحية مؤخرتك","افرد ببطء وحافظ على الحوض مرتفع"],["Lie on your back with heels on the ball and hips lifted.","Curl the ball toward your glutes by bending your knees.","Extend slowly, keeping your hips raised."]],"Band_Good_Morning_(Pull_Through)":[["قف على الباند وامسكه عند ورك وضهرك مفرود","اثني الورك لقدام مع دفع المؤخرة لورا","ارجع بدفع الورك لقدام وشد المؤخرة"],["Stand on the band and hold it at hip height, back flat.","Hinge at the hips, pushing your glutes back.","Drive your hips forward and squeeze your glutes to stand."]],"Band_Good_Morning":[["حط الباند على كتفك وقف عليه وضهرك مفرود","اثني الورك لقدام مع دفع المؤخرة لورا","ارجع بدفع الورك لقدام من غير ما تقوّس ضهرك"],["Place the band across your shoulders and stand on it, back flat.","Hinge at the hips, pushing your glutes back.","Return by driving your hips forward without rounding your back."]],"Band_Hip_Adductions":[["اربط الباند حوالين الكاحل وثبّته في نقطة جنب","ضم رجلك ناحية الرجل التانية ضد مقاومة الباند","ارجع ببطء وحافظ على جسمك ثابت"],["Loop the band around your ankle and anchor it to the side.","Pull your leg across toward the other leg against the band.","Return slowly, keeping your body steady."]],"Band_Pull_Apart":[["امسك الباند بكفوف لتحت قدام صدرك ودراعك مفرودة","افتح الباند للجنب وشد لوح الكتف","ارجع ببطء وحافظ على التوتر"],["Hold the band at chest height with arms straight, palms down.","Pull it apart sideways, squeezing your shoulder blades.","Return slowly, keeping tension on the band."]],"Band_Skull_Crusher":[["اتمدد على بنش وامسك الباند بإيديك ودراعك لفوق","اثني كوعك لحد ما الإيد تقرب من جبهتك","افرد دراعك وكوعك ثابت"],["Lie on a bench holding the band with arms extended up.","Bend your elbows to lower your hands toward your forehead.","Extend your arms back up, elbows staying fixed."]],"Barbell_Ab_Rollout_-_On_Knees":[["اركع على سجادة وامسك البار تحت كتفك","ادحرج البار لقدام لحد ما جسمك يتمدد وبطنك مشدودة","اسحب البار ناحيتك ولا تقوّس ضهرك"],["Kneel on a mat holding the barbell under your shoulders.","Roll forward until your body is extended, abs tight.","Pull back to the start without arching your back."]],"Barbell_Ab_Rollout":[["اقف وامسك البار وانحنى لحد ما يلمس الأرض","ادحرج البار لقدام وبطنك مشدودة وضهرك مفرود","اسحب البار ناحيتك ببطء ولا تقوّس ضهرك"],["Stand holding the bar, bent forward with the bar on the floor.","Roll forward, abs tight and back flat.","Pull back slowly without arching your lower back."]],"Barbell_Curls_Lying_Against_An_Incline":[["اتمدد على وشك على بنش مائل وامسك البار","اثني كوعك لرفع البار ناحية صدرك","انزل ببطء لحد ما الدراع تتفرد"],["Lie face down on an incline bench holding a barbell.","Curl the bar up toward your chest.","Lower slowly until your arms are straight."]],"Barbell_Full_Squat":[["حط البار على كتفك وقف بوسع الكتف وصدرك مرفوع","انزل بالورك لورا والركبة ناحية صوابع رجلك لحد ما تنزل تحت الركبة","اطلع بدفع الأرض وضهرك مفرود"],["Rest the bar on your upper back, feet shoulder-width, chest up.","Sit down and back until your hips are below your knees.","Drive up through your feet, keeping your back flat."]],"Barbell_Guillotine_Bench_Press":[["اتمدد على البنش وامسك البار بقبضة واسعة","نزل البار ببطء لحد أعلى الصدر قرب الرقبة","ادفع لفوق وكوعك مفتوح وانتبه لحمل الوزن"],["Lie on a bench and grip the bar wide.","Lower it slowly toward your upper chest near the neck.","Press back up with elbows flared, using a light weight."]],"Barbell_Hack_Squat":[["امسك البار ورا رجلك وقف بوسع الكتف","انزل بالركبة مع ضهرك مفرود وصدرك مرفوع","اطلع بدفع الأرض وانت ماسك البار قريب من جسمك"],["Hold the bar behind your legs, feet shoulder-width.","Squat down with a flat back and chest up.","Drive up through your feet, keeping the bar close."]],"Barbell_Incline_Shoulder_Raise":[["اتمدد على بنش مائل وامسك البار بإيديك","ارفع البار فوق راسك بدراع مفرودة","نزّله ببطء من غير ما تقفل الكوع بقوة"],["Lie on an incline bench holding the bar.","Raise the bar upward with straight arms.","Lower slowly without locking your elbows hard."]],"Barbell_Lunge":[["حط البار على كتفك وقف وصدرك مرفوع","خد خطوة لقدام وانزل لحد ما الركبتين ٩٠ درجة","ادفع بالرجل الأمامية للرجوع وبدّل الرجل"],["Rest the bar on your upper back and stand tall.","Step forward and lower until both knees reach 90 degrees.","Push off the front foot to return, then switch legs."]],"Barbell_Rear_Delt_Row":[["انحني من الورك وضهرك مفرود وامسك البار بقبضة واسعة","اسحب البار ناحية صدرك وكوعك مفتوح للجنب","نزّله ببطء وحافظ على ضهرك مفرود"],["Hinge at the hips, back flat, holding the bar with a wide grip.","Row the bar toward your upper chest, elbows flared out.","Lower slowly, keeping your back flat."]],"Barbell_Rollout_from_Bench":[["اركع قدام البنش وامسك البار أو حطه على البنش","ادحرج البار لقدام وبطنك مشدودة","ارجع ببطء وحافظ على ضهرك مفرود"],["Kneel by the bench and hold the bar on the bench.","Roll forward with abs tight.","Return slowly, keeping your back flat."]],"Barbell_Seated_Calf_Raise":[["اقعد على بنش وحط البار على فخذك مع تثبيت أصابع الرجل","ارفع كعبك لفوق وشد السمانة","انزل ببطء لحد ما تحس بشد"],["Sit on a bench with the bar across your thighs, balls of feet on a block.","Raise your heels as high as possible, squeezing your calves.","Lower slowly until you feel a stretch."]],"Barbell_Shrug_Behind_The_Back":[["قف وامسك البار ورا ضهرك وكفوفك لورا","ارفع كتفك لفوق ناحية ودنك","نزّل كتفك ببطء وضهرك مفرود"],["Stand holding the bar behind your back, palms facing back.","Shrug your shoulders straight up toward your ears.","Lower slowly, keeping your torso upright."]],"Barbell_Side_Bend":[["قف وامسك البار على كتفك وضهرك مفرود","اثني جذعك للجنب لحد ما تحس بشد","ارجع للوضع المستقيم ببطء وبدّل"],["Stand with the bar on your upper back, torso upright.","Bend sideways until you feel a stretch in your obliques.","Return upright slowly, then switch sides."]],"Barbell_Side_Split_Squat":[["حط البار على كتفك وقف بوسع كبير وضهرك مفرود","انزل على رجل واحدة والتانية مفرودة","ادفع الأرض للرجوع وبدّل الرجل"],["Rest the bar on your upper back, feet wide, back flat.","Squat onto one leg while the other stays straight.","Push through the floor to return, then switch sides."]],"Barbell_Squat_To_A_Bench":[["حط البار على كتفك وقف قدام بنش مقدار سكوات","انزل ببطء لحد ما تلمس البنش بحوضك","اطلع بدفع الأرض وضهرك مفرود"],["Rest the bar on your upper back and stand in front of a bench.","Sit back until you lightly touch the bench.","Drive up through your feet, keeping your back flat."]],"Barbell_Step_Ups":[["حط البار على كتفك وقف قدام بنش أو صندوق","اطلع برجل على البنش وارفع جسمك","نزّل ببطء وبدّل الرجل"],["Rest the bar on your upper back and stand facing a bench.","Step up with one leg, driving through the heel.","Step down slowly, then alternate legs."]],"Bear_Crawl_Sled_Drags":[["خد وضع الدب على إيديك وركبك مع ربط الزحافة","اتحرك لقدام بإيد ورجل متبادلين وسحب الزحافة","اتحرك بتحكم وحافظ على ضهرك مفرود"],["Get on hands and knees in a bear position with the sled attached.","Crawl forward, alternating opposite hand and foot, dragging the sled.","Move under control, keeping your back flat."]],"Behind_Head_Chest_Stretch":[["قف وإيدك ورا راسك وكوعك مفتوح","اسحب كوعك لورا بلطف لحد ما تحس بشد في الصدر","ثبّت 20-30 ثانية"],["Stand with hands behind your head, elbows out.","Gently pull your elbows back until you feel a chest stretch.","Hold 20-30 seconds."]],"Bench_Jump":[["قف قدام بنش وركبك مثنية شوية","اقفز لفوق على البنش بقوة وانت بتفرد جسمك","اهبط بخفة ونزّل بنزول مؤمّن"],["Stand facing a bench with knees slightly bent.","Jump onto the bench, extending your hips explosively.","Land softly, then step down under control."]],"Bench_Press_-_Powerlifting":[["اتمدد على البنش وكتفك لورا والقوس طبيعي","نزل البار لحد صدرك مع كوع قريب من الجسم","ادفع البار لفوق من غير ما ترفع حوضك"],["Lie on the bench with shoulder blades pinched back.","Lower the bar to your chest with elbows tucked.","Press up without lifting your hips off the bench."]],"Bench_Press_-_With_Bands":[["اتمدد على البنش وامسك البار المربوط بالباند","نزل البار ببطء لحد صدرك","ادفع لفوق ضد مقاومة الباند"],["Lie on the bench holding the band-resisted bar.","Lower the bar slowly to your chest.","Press up against the band's resistance."]],"Bench_Press_with_Chains":[["اتمدد على البنش وامسك البار المعلق بالسلاسل","نزل البار ببطء لحد صدرك","ادفع لفوق وسلاسل بتزيد وزن"],["Lie on the bench holding the chain-loaded bar.","Lower the bar slowly to your chest.","Press up as the chains add load near the top."]],"Bench_Sprint":[["اقعد على البنش وإيدك جنب جسمك","اجرى بسرعة في المكان وشغل دراعك","خلي إيقاعك سريع ومتوازن"],["Sit at the edge of a bench, hands at your sides.","Sprint in place quickly, pumping your arms.","Keep a fast, balanced rhythm."]],"Bent-Arm_Barbell_Pullover":[["اتمدد على بنش وامسك البار فوق صدرك","نزل البار لورا راسك وكوعك مثني شوية","ارجعه فوق صدرك بقوة"],["Lie on a bench holding the bar above your chest.","Lower it behind your head with elbows slightly bent.","Pull it back over your chest."]],"Bent-Knee_Hip_Raise":[["اتمدد على ضهرك وإيديك جنبك وركبك مثنية","ارفع حوضك لفوق بشد البطن","نزّل ببطء وبدون رمي"],["Lie on your back, hands at your sides, knees bent.","Lift your hips up by contracting your abs.","Lower slowly without swinging."]],"Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench":[["اسند راسك على بنش وانحني وامسك دامبل","ارفع الدراعين للجنب لحد مستوى الظهر","نزّل ببطء بدون هز"],["Rest your forehead on a bench, hinged forward, holding dumbbells.","Raise your arms out to the sides to back level.","Lower slowly without swinging."]],"Bent_Over_Low-Pulley_Side_Lateral":[["انحني قدام الكابل السفلي وامسك المقبض بالإيد المعاكسة","ارفع دراعك للجنب لحد ما يوصل لمستوى الكتف","ارجع ببطء مع حفاظ على ضهرك مفرود"],["Bend over beside the low pulley, holding the handle across your body.","Raise your arm out to the side to shoulder level.","Return slowly, keeping your back flat."]],"Bent_Over_One-Arm_Long_Bar_Row":[["اقف على جنب البار وانحني وامسك طرف البار","اسحب البار ناحية خصرك بإيد واحدة","نزّله ببطء وضهرك مفرود"],["Stand over the bar, hinge forward, and grip one end.","Row the bar toward your waist with one arm.","Lower it slowly, keeping your back flat."]],"Bent_Over_Two-Arm_Long_Bar_Row":[["امسك البار الطويل بإيديك وانحني وضهرك مفرود","اسحب البار ناحية بطنك وشد لوح الكتف","نزّله ببطء بدون تقوس"],["Grip the long bar with both hands, hinged forward, back flat.","Row the bar toward your belly, squeezing shoulder blades.","Lower slowly without rounding your back."]],"Bent_Over_Two-Dumbbell_Row_With_Palms_In":[["انحني من الورك وامسك دامبل وكفوفك ناحية بعض","اسحب الدامبل ناحية خصرك وكوعك قريب","نزّله ببطء وضهرك مفرود"],["Hinge at the hips holding dumbbells, palms facing each other.","Row the dumbbells toward your waist, elbows close.","Lower slowly, keeping your back flat."]],"Bent_Over_Two-Dumbbell_Row":[["انحني من الورك وامسك دامبل في كل إيد","اسحب الدامبل ناحية خصرك وشد لوح الكتف","نزّله ببطء وضهرك مفرود"],["Hinge at the hips holding a dumbbell in each hand.","Row the dumbbells toward your waist, squeezing shoulder blades.","Lower slowly, keeping your back flat."]],"Bent_Press":[["امسك الكيتل بيل عند كتفك واقف بوسع","ادفع الورك للجنب وانزل بجذعك والكيتل بيل لفوق","اطلع واقف ببطء وبطنك مشدودة"],["Hold the kettlebell at your shoulder, feet wide.","Push your hip out and lower your torso with the bell overhead.","Stand back up slowly with abs braced."]],"Bicycling":[["اقعد على الدراجة واظبط الكرسي","ادعس بانتظام وحافظ على ضهر مفرود","حافظ على إيقاع ثابت وتنفس منتظم"],["Sit on the bike and adjust the seat height.","Pedal smoothly with a straight back.","Keep a steady pace and regular breathing."]],"Board_Press":[["اتمدد على البنش وحط ألواح فوق صدرك","نزل البار لحد اللوح ببطء","ادفع لفوق بقوة وضهرك على البنش"],["Lie on the bench with boards stacked on your chest.","Lower the bar slowly until it touches the board.","Press up powerfully, back on the bench."]],"Body-Up":[["خد وضع بلانك وإيدك على بار أو حاجة ثابتة","اثني كوعك وانزل بجسمك لحد ما تقرب","افرد دراعك لفوق وجسمك مفرود"],["Get in a plank with hands on a stable bar.","Bend your elbows and lower your body down.","Extend your arms up, keeping your body straight."]],"Body_Tricep_Press":[["ضع إيديك على بنش أو بار ثابت وجسمك مفرود","اثني كوعك لتنزل جسمك","ادفع لفوق وافرد الدراعين"],["Place your hands on a stable bar or bench, body straight.","Bend your elbows to lower your body.","Press back up and extend your arms."]],"Bodyweight_Flyes":[["خد وضع بلانك على بار مرتفع ودراعك مفرودة","افتح دراعك للجنب بتحكم","اضغط لفوق بصدرك لتجمع الدراعين"],["Get in a plank on a raised bar with arms straight.","Open your arms to the sides under control.","Squeeze your chest to bring your arms back."]],"Bodyweight_Mid_Row":[["اتدلى تحت بار منخفض وجسمك مفرود","اسحب صدرك ناحية البار وشد لوح الكتف","نزّل ببطء وجسمك مفرود"],["Hang under a low bar with your body straight.","Pull your chest toward the bar, squeezing shoulder blades.","Lower slowly, keeping your body straight."]],"Bodyweight_Walking_Lunge":[["قف وصدرك مرفوع وإيدك على وسطك","خد خطوة كبيرة لقدام وانزل لحد ما الركبتين ٩٠ درجة","ادفع بالرجل الأمامية وخد الخطوة التالية"],["Stand tall with hands on hips.","Step forward and lower until both knees are at 90 degrees.","Push off the front foot and step into the next lunge."]],"Bosu_Ball_Cable_Crunch_With_Side_Bends":[["اركع قدام الكابل على بوسو وامسك الحبل عند راسك","اعمل كرانش لتحت وثني جانبي بلطف","ارجع ببطء وحافظ على بطنك مشدودة"],["Kneel on the Bosu ball facing the cable, rope by your head.","Crunch down with a slight side bend.","Return slowly, keeping your abs tight."]],"Bottoms-Up_Clean_From_The_Hang_Position":[["امسك الكيتل بيل مقلوب بين رجليك وضهرك مفرود","اسحبه لفوق وقلبه عند الكتف بدفع الورك","نزّله ببطء بتحكم وكفك ثابت"],["Hold the kettlebell upside-down between your legs, back flat.","Pull it up to shoulder level, flipping it by driving your hips.","Lower it slowly under control, wrist stable."]],"Bottoms_Up":[["اتمدد على ضهرك وركبك مثنية","ارفع حوضك لفوق بقوة وشد المؤخرة","نزّل ببطء بدون ما تقفل ضهرك"],["Lie on your back with knees bent.","Lift your hips up, squeezing your glutes.","Lower slowly without arching your back."]],"Box_Jump_Multiple_Response":[["قف قدام الصندوق وركبك مثنية شوية","اقفز على الصندوق واهبط بخفة وانزل فورا واقفز تاني","كرر بسرعة وحافظ على هبوط ناعم"],["Stand facing the box, knees slightly bent.","Jump onto the box, land softly, step down and jump again right away.","Repeat quickly, keeping every landing soft."]],"Box_Skip":[["قف جنب الصندوق وإحدى رجليك عليه","اقفز بسرعة وبدّل الرجل في الهوا","اهبط بخفة وكرر بإيقاع ثابت"],["Stand beside the box with one foot on top.","Hop quickly, switching feet in the air.","Land softly and repeat at a steady rhythm."]],"Box_Squat_with_Bands":[["حط البار على كتفك والباند عليه وقف قدام الصندوق","اقعد لورا لحد ما تلمس الصندوق بحوضك","اطلع بقوة ضد الباند وضهرك مفرود"],["Set the bar on your back with bands attached, standing in front of a box.","Sit back until you lightly touch the box.","Drive up against the bands, keeping your back flat."]],"Box_Squat_with_Chains":[["حط البار المعلق بسلاسل على كتفك وقف قدام الصندوق","اقعد لورا لحد ما تلمس الصندوق بحوضك","اطلع بقوة وضهرك مفرود"],["Set the chain-loaded bar on your back, standing in front of a box.","Sit back until you lightly touch the box.","Drive up powerfully, keeping your back flat."]],"Brachialis-SMR":[["اتمدد على جنبك وحط الفوم رولر تحت العضد","ادحرج ببطء على الدراع من الكوع للكتف","وقف على أي نقطة مشدودة ثواني"],["Lie on your side with the foam roller under your upper arm.","Roll slowly along your arm from elbow toward shoulder.","Pause on tight spots for a few seconds."]],"Bradford_Rocky_Presses":[["اقعد وامسك البار عند الكتف","اضغط البار لفوق قدام راسك وبعدين ورا راسك بالتبادل","ارجع بتحكم وحافظ على ضهرك مفرود"],["Sit holding the bar at shoulder height.","Press the bar overhead, alternating front and behind the head.","Lower under control, keeping your back straight."]],"Butt-Ups":[["خد وضع بلانك وإيدك تحت كتفك","ارفع المؤخرة لفوق بشد البطن","نزّل ببطء وجسمك مفرود"],["Get in a plank with hands under shoulders.","Lift your hips up by contracting your abs.","Lower slowly, keeping your body straight."]],"Cable_Chest_Press":[["قف بين الكابلين وامسك المقابض قدام صدرك","اضغط الكابل لقدام لحد ما تفرد دراعك","ارجع ببطء وحافظ على صدرك مرفوع"],["Stand between the cables, handles at chest level.","Press the handles forward until your arms are straight.","Return slowly, keeping your chest up."]],"Cable_Deadlifts":[["قف قدام الكابل السفلي وامسك البار بإيديك","ارفع الوزن بفرد الورك وضهرك مفرود","نزّل ببطء وضهرك مفرود"],["Stand over the low cable and grip the attachment.","Lift by extending your hips, back flat.","Lower slowly, keeping your back flat."]],"Cable_Hammer_Curls_-_Rope_Attachment":[["قف قدام الكابل وامسك الحبل بكفوف ناحية بعض","اثني كوعك لفوق مع بقاء الكوع ثابت","انزل ببطء وحافظ على ضهرك مفرود"],["Stand at the low cable holding the rope, palms facing in.","Curl up, keeping your elbows fixed at your sides.","Lower slowly, keeping your back straight."]],"Cable_Hip_Adduction":[["اربط الكابل حوالين الكاحل وقف على جنب","ضم رجلك ناحية الرجل التانية ضد الكابل","ارجع ببطء وحافظ على جسمك ثابت"],["Attach the cable to your ankle and stand sideways to it.","Pull your leg across toward the other leg.","Return slowly, keeping your body steady."]],"Cable_Incline_Pushdown":[["اقعد على بنش مائل قدام الكابل وامسك البار","اضغط الكابل لتحت لحد ما تفرد الدراعين","ارجع ببطء وحافظ على كوعك ثابت"],["Sit on an incline bench facing the cable, holding the bar.","Push down until your arms are straight.","Return slowly, keeping your elbows fixed."]],"Cable_Incline_Triceps_Extension":[["اتمدد على بنش مائل وامسك الكابل فوق راسك","افرد دراعك لفوق وكوعك ثابت","ارجع ببطء وحافظ على كوعك مثبت"],["Lie on an incline bench holding the cable behind your head.","Extend your arms upward, keeping elbows fixed.","Return slowly while holding your elbows still."]],"Cable_Internal_Rotation":[["قف جنب الكابل وكوعك مثني ٩٠ درجة وملاصق لجسمك","لف دراعك ناحية بطنك ببطء","ارجع ببطء وكوعك ثابت"],["Stand beside the cable, elbow bent 90 degrees and tucked at your side.","Rotate your forearm across toward your belly.","Return slowly, keeping your elbow fixed."]],"Cable_Iron_Cross":[["قف بين الكابلين وامسك المقابض من فوق","اسحب الكابلين لتحت وجنب جسمك بشد الصدر","ارجع ببطء وحافظ على صدرك مفرود"],["Stand between high cables holding the handles above.","Pull the handles down and out toward your sides, squeezing your chest.","Return slowly, keeping your chest open."]],"Cable_Judo_Flip":[["قف جنب الكابل وامسك المقبض بإيدين","لف جذعك وارفع الكابل بشكل قطري","ارجع ببطء وحافظ على بطنك مشدودة"],["Stand beside the cable and grip the handle with both hands.","Rotate your torso and pull the cable diagonally.","Return slowly, keeping your abs braced."]],"Cable_Lying_Triceps_Extension":[["اتمدد على بنش وامسك الكابل فوق راسك","اثني كوعك ونزل الكابل ناحية جبهتك","افرد دراعك لفوق وكوعك ثابت"],["Lie on a bench and hold the cable above your head.","Bend your elbows, lowering the cable toward your forehead.","Extend back up, keeping elbows fixed."]],"Cable_One_Arm_Tricep_Extension":[["قف وامسك الكابل بإيد واحدة فوق راسك","افرد دراعك لفوق وكوعك ثابت","ارجع ببطء من غير ما تحرك كوعك"],["Stand and hold the cable overhead with one hand.","Extend your arm upward, elbow fixed.","Return slowly without moving your elbow."]],"Cable_Preacher_Curl":[["اقعد على بنش بريتشر وامسك الكابل","اثني كوعك لفوق مع بقاء الذراع ملاصق للوسادة","انزل ببطء لحد ما تفرد دراعك"],["Sit at a preacher bench holding the cable.","Curl up while keeping your upper arm on the pad.","Lower slowly until your arms are straight."]],"Cable_Rear_Delt_Fly":[["قف بين الكابلين وامسك الأطراف بإيدين متقاطعتين","افتح دراعك للجنب بشد لوح الكتف","ارجع ببطء وحافظ على ضهرك مفرود"],["Stand between the cables and cross the handles in front of you.","Pull your arms out to the sides, squeezing shoulder blades.","Return slowly, keeping your back flat."]],"Cable_Reverse_Crunch":[["اتمدد على ضهرك ورجلك متصلة بالكابل","اسحب ركبك ناحية صدرك بشد البطن","نزّل ببطء من غير ما تقوس ضهرك"],["Lie on your back with the cable attached to your ankles.","Pull your knees toward your chest using your abs.","Lower slowly without arching your back."]],"Cable_Rope_Rear-Delt_Rows":[["اقعد قدام الكابل وامسك الحبل بكفوف لتحت","اسحب الحبل ناحية وجهك وكوعك مفتوح للجنب","ارجع ببطء وضهرك مفرود"],["Sit facing the cable, holding the rope.","Pull the rope toward your face with elbows flared out.","Return slowly, keeping your back straight."]],"Cable_Russian_Twists":[["قف جنب الكابل وامسك المقبض عند صدرك","لف جذعك بعيد عن الكابل وبطنك مشدودة","ارجع ببطء وبدّل الجانب"],["Stand beside the cable, holding the handle at chest height.","Rotate your torso away from the cable, abs tight.","Return slowly, then switch sides."]],"Cable_Seated_Crunch":[["اقعد قدام الكابل وامسك الحبل عند راسك","اعمل كرانش لتحت بشد البطن","ارجع ببطء وجسمك متحكم"],["Sit facing the cable with the rope by your head.","Crunch down, contracting your abs.","Return slowly under control."]],"Cable_Shoulder_Press":[["اقعد قدام الكابل وامسك المقابض عند الكتف","اضغط لفوق لحد ما تفرد الدراعين","نزّل ببطء من غير ما تقوس ضهرك"],["Sit facing the cable, handles at shoulder level.","Press overhead until your arms are straight.","Lower slowly without arching your back."]],"Cable_Shrugs":[["قف قدام الكابل وامسك المقبض بإيدين","ارفع كتفك لفوق ناحية ودنك","نزّل ببطء بدون تدوير الكتف"],["Stand at the low cable holding the bar.","Shrug your shoulders straight up toward your ears.","Lower slowly without rolling your shoulders."]],"Cable_Wrist_Curl":[["اقعد وإيدك على فخذك وامسك الكابل بكفوف لفوق","اثني معصمك لفوق ببطء","نزّل ببطء لحد ما تفرد المعصم"],["Sit with forearms on your thighs, holding the cable, palms up.","Curl your wrists upward slowly.","Lower slowly to full stretch."]],"Calf-Machine_Shoulder_Shrug":[["قف في جهاز السمانة واسند الوسادة على كتفك","ارفع كتفك لفوق ناحية ودنك","نزّل ببطء وضهرك مفرود"],["Stand in the calf machine with the pads on your shoulders.","Shrug your shoulders straight up toward your ears.","Lower slowly, keeping your back straight."]],"Calf_Press":[["اقعد على جهاز الضغط وحط أصابع رجلك على الحافة","ادفع بأصابعك لفوق وارفع الكعب","ارجع ببطء لحد ما تحس بشد"],["Sit in the press machine with the balls of your feet on the plate.","Push up through your toes to raise your heels.","Lower slowly until you feel a stretch."]],"Calf_Raise_On_A_Dumbbell":[["قف على دامبل بأصابع رجلك وامسك حاجة تتسند عليها","ارفع كعبك لفوق وشد السمانة","نزّل ببطء لحد ما تحس بشد"],["Stand with the balls of your feet on a dumbbell, holding support.","Raise your heels as high as possible, squeezing your calves.","Lower slowly until you feel a stretch."]],"Calf_Raises_-_With_Bands":[["اقعد وحط الباند على أصابع رجلك","ارفع كعبك ضد مقاومة الباند","نزّل ببطء بتحكم"],["Sit with the band around the balls of your feet.","Raise your heels against the band's resistance.","Lower slowly under control."]],"Calf_Stretch_Elbows_Against_Wall":[["قف قدام حيط وكوعك عليه ورجل لورا","اضغط الكعب الخلفي على الأرض وانحني للأمام","ثبّت 20-30 ثانية وبدّل الرجل"],["Stand facing a wall, elbows against it, one leg back.","Press the back heel down and lean forward.","Hold 20-30 seconds, then switch legs."]],"Calf_Stretch_Hands_Against_Wall":[["قف قدام حيط وإيدك عليه ورجل لورا","اضغط الكعب الخلفي على الأرض وانحني للأمام","ثبّت 20-30 ثانية وبدّل الرجل"],["Stand facing a wall, hands on it, one leg back.","Press the back heel down and lean forward.","Hold 20-30 seconds, then switch legs."]],"Calves-SMR":[["اقعد وحط الفوم رولر تحت السمانة","ادحرج ببطء من الكاحل للركبة","وقف على أي نقطة مشدودة ثواني"],["Sit with the foam roller under your calf.","Roll slowly from ankle toward knee.","Pause on tight spots for a few seconds."]],"Car_Deadlift":[["قف جنب السيارة وامسك المقبض بإيدين وضهرك مفرود","ارفع بدفع الأرض وفرد الورك","نزّل بتحكم وضهرك مفرود"],["Stand at the car lift handles, back flat.","Lift by pushing the floor away and extending your hips.","Lower under control, keeping your back flat."]],"Car_Drivers":[["قف وامسك البار قدامك كأنه عجلة قيادة","لف البار يمين وشمال بذراع مفرودة","ارجع للمنتصف وحافظ على كتفك للأسفل"],["Stand holding a plate or bar in front like a steering wheel.","Rotate it left and right with straight arms.","Return to center, keeping your shoulders down."]],"Carioca_Quick_Step":[["قف وركبك مثنية شوية وجسمك مائل","اتحرك للجنب بتبادل الرجل أمام وخلف","كرر بسرعة وحافظ على توازنك"],["Stand with knees slightly bent in an athletic stance.","Move sideways, crossing one foot in front then behind.","Repeat quickly while keeping your balance."]],"Cat_Stretch":[["ابدأ على أربع وإيديك تحت كتفك","قوّس ضهرك لفوق وشد راسك لتحت","ثبّت 20-30 ثانية وارجع ببطء"],["Start on all fours, hands under shoulders.","Round your back upward and tuck your chin.","Hold 20-30 seconds, then release slowly."]],"Catch_and_Overhead_Throw":[["قف ووجهك للحيط ومعاك ميديسن بول","التقط الكورة وارمها فوق راسك بسرعة","التقط ثانية واعمل رمية جديدة"],["Stand facing a partner or wall holding a medicine ball.","Catch the ball and throw it overhead quickly.","Catch again and repeat the throw."]],"Chain_Handle_Extension":[["قف وامسك المقبض المربوط بالسلسلة فوق راسك","افرد دراعك لفوق وكوعك ثابت","ارجع ببطء بتحكم"],["Stand holding the chain handle overhead.","Extend your arms upward, elbows fixed.","Return slowly under control."]],"Chain_Press":[["اتمدد على البنش وامسك البار المعلق بسلسلة","نزل البار ببطء لحد صدرك","ادفع لفوق ضد وزن السلسلة"],["Lie on the bench holding the chain-loaded bar.","Lower the bar slowly to your chest.","Press up against the chains' increasing load."]],"Chair_Leg_Extended_Stretch":[["اقعد على حافة كرسي ورجل مفرودة قدامك","انحني للأمام بضهر مفرود لحد ما تحس بشد","ثبّت 20-30 ثانية وبدّل الرجل"],["Sit on the edge of a chair, one leg extended.","Lean forward with a straight back until you feel a stretch.","Hold 20-30 seconds, then switch legs."]],"Chair_Lower_Back_Stretch":[["اقعد على كرسي ورجلك مفتوحة","انحني للأمام وإيدك على الأرض بلطف","ثبّت 20-30 ثانية وارجع ببطء"],["Sit on a chair with feet apart.","Fold forward, hands toward the floor, gently.","Hold 20-30 seconds, then return slowly."]],"Chair_Squat":[["قف قدام كرسي ورجلك بوسع الكتف","انزل ببطء لحد ما تلمس الكرسي بحوضك","اطلع بدفع الأرض وضهرك مفرود"],["Stand in front of a chair, feet shoulder-width.","Sit back slowly until you lightly touch the chair.","Drive up through your feet, keeping your back straight."]],"Chair_Upper_Body_Stretch":[["اقعد على كرسي وشبّك إيديك قدامك","اشد دراعك لفوق وللخلف بلطف","ثبّت 20-30 ثانية"],["Sit on a chair and clasp your hands in front.","Stretch your arms upward and back gently.","Hold 20-30 seconds."]],"Chest_And_Front_Of_Shoulder_Stretch":[["قف وشبّك إيديك ورا ضهرك","ارفع دراعك لفوق ولورا بلطف","ثبّت 20-30 ثانية"],["Stand and clasp your hands behind your back.","Lift your arms up and back gently.","Hold 20-30 seconds."]],"Chest_Push_from_3_point_stance":[["خد وضع ٣ نقاط ومعاك ميديسن بول","ادفع الكورة بقوة من صدرك","التقط الكورة وكرر"],["Get in a 3-point stance with a medicine ball.","Explosively push the ball forward from your chest.","Catch it and repeat."]],"Chest_Push_multiple_response":[["قف وامسك الميديسن بول عند صدرك","ادفع الكورة بقوة والتقطها بسرعة","كرر الدفعات بدون توقف"],["Stand holding a medicine ball at chest height.","Push it forcefully and catch it quickly.","Repeat the pushes without pausing."]],"Chest_Push_single_response":[["قف وامسك الميديسن بول عند صدرك","ادفع الكورة بقوة لقدام","التقطها وارجع للوضع الأول"],["Stand holding a medicine ball at chest height.","Explosively push it forward.","Catch it and reset."]],"Chest_Push_with_Run_Release":[["قف وامسك الميديسن بول عند صدرك","ادفع الكورة بقوة لقدام واجري بعدها","التقط الكورة وارجع للوضع الأول"],["Stand holding a medicine ball at chest height.","Push it forward powerfully, then sprint after it.","Pick it up and reset."]],"Chest_Stretch_on_Stability_Ball":[["اتمدد على الكورة السويسرية على ضهرك","افتح دراعك للجنب وسيب صدرك يتمدد","ثبّت 20-30 ثانية"],["Lie back on a stability ball.","Open your arms to the sides and let your chest stretch.","Hold 20-30 seconds."]],"Childs_Pose":[["اركع وحط ركبك واسعة وكعبك على المؤخرة","انحني للأمام ودراعك مفرودة قدامك","ثبّت 20-30 ثانية وتنفس بهدوء"],["Kneel with knees wide and sit back on your heels.","Fold forward with your arms extended in front.","Hold 20-30 seconds, breathing slowly."]],"Chin_To_Chest_Stretch":[["اقعد أو قف وضهرك مفرود","اثني راسك لقدام بلطف وذقنك ناحية صدرك","ثبّت 20-30 ثانية بدون جذب قوي"],["Sit or stand tall.","Gently bring your chin toward your chest.","Hold 20-30 seconds without pulling hard."]],"Circus_Bell":[["قف قدام الجرس وامسكه بإيدين وضهرك مفرود","ارفع الجرس لفوق راسك بدفع الورك","نزّله بتحكم وضهرك مفرود"],["Stand over the bell and grip it, back flat.","Lift it overhead by driving your hips.","Lower it under control, keeping your back flat."]],"Clean_Deadlift":[["قف قدام البار وامسكه وضهرك مفرود","ارفع البار بدفع الأرض وفرد الورك","نزّله بتحكم وضهرك مفرود"],["Stand over the bar, grip it, back flat.","Lift by pushing the floor away and extending your hips.","Lower under control, keeping your back flat."]],"Clean_Pull":[["قف قدام البار وامسكه وضهرك مفرود","اسحب البار بسرعة بدفع الورك","نزّله بتحكم لوضع البداية"],["Stand over the bar, grip it, back flat.","Pull the bar explosively by driving your hips.","Lower it under control to the start."]],"Clean_Shrug":[["قف وامسك البار قدام فخذك","ارفع كتفك لفوق بقوة مع فرد الورك","نزّله ببطء وضهرك مفرود"],["Stand holding the bar in front of your thighs.","Shrug your shoulders up forcefully while extending your hips.","Lower slowly, keeping your back straight."]],"Clean_and_Jerk":[["قف قدام البار وامسكه وضهرك مفرود","اسحب البار لكتفك ثم ادفعه فوق راسك بقوة","نزّله بتحكم لحد الكتف ثم للأرض"],["Stand over the bar, grip it, back flat.","Pull it to your shoulders, then drive it overhead.","Lower under control to your shoulders, then the floor."]],"Clean_and_Press":[["قف قدام البار وامسكه وضهرك مفرود","اسحب البار لكتفك ثم اضغطه لفوق","نزّله بتحكم لحد الكتف ثم للأرض"],["Stand over the bar, grip it, back flat.","Clean it to your shoulders, then press overhead.","Lower under control to your shoulders, then the floor."]],"Clean_from_Blocks":[["قف قدام البار على البلوكس وامسكه وضهرك مفرود","اسحب البار بسرعة لكتفك","نزّله بتحكم للبلوكس"],["Stand over the bar on blocks, grip it, back flat.","Pull it explosively to your shoulders.","Lower it under control back to the blocks."]],"Clean":[["قف قدام البار وامسكه وضهرك مفرود","اسحب البار لكتفك بدفع الورك","نزّله بتحكم للأرض"],["Stand over the bar, grip it, back flat.","Pull it to your shoulders by driving your hips.","Lower it under control to the floor."]],"Clock_Push-Up":[["خد وضع الضغط وإيدك تحت كتفك","اعمل ضغطة وبعدها حرك إيدك للجنب في اتجاه الساعة","كرر لحد ما ترجع للوضع الأول"],["Get in a push-up position, hands under shoulders.","Do a push-up, then move your hands one step around like a clock.","Repeat until you return to the start."]],"Close-Grip_Dumbbell_Press":[["اتمدد على البنش وامسك الدامبل قريب من بعض","اضغط الدامبل لفوق وكوعك قريب من جسمك","نزّل ببطء وحافظ على كوعك قريب"],["Lie on the bench holding dumbbells close together.","Press up with your elbows close to your body.","Lower slowly, keeping elbows tucked."]],"Close-Grip_EZ-Bar_Curl_with_Band":[["قف وامسك البار EZ بقبضة ضيقة والباند عليه","اثني كوعك لفوق ضد الباند","نزّل ببطء وكوعك ثابت"],["Stand holding the EZ bar with a narrow grip and a band attached.","Curl up against the band's resistance.","Lower slowly, keeping your elbows fixed."]],"Close-Grip_EZ-Bar_Press":[["اتمدد على البنش وامسك البار EZ بقبضة ضيقة","نزل البار ببطء لحد صدرك","ادفع لفوق وكوعك قريب من جسمك"],["Lie on a bench holding the EZ bar with a narrow grip.","Lower the bar slowly to your chest.","Press up with elbows close to your body."]],"Close-Grip_EZ_Bar_Curl":[["قف وامسك البار EZ بقبضة ضيقة","اثني كوعك لفوق وكوعك ثابت","نزّل ببطء بدون هز"],["Stand holding the EZ bar with a narrow grip.","Curl up, keeping your elbows fixed.","Lower slowly without swinging."]],"Close-Grip_Front_Lat_Pulldown":[["اقعد على الجهاز وامسك المقبض الضيق","اسحب المقبض لتحت ناحية صدرك وشد لوح الكتف","ارجع ببطء وحافظ على ضهرك مفرود"],["Sit at the pulldown and grip the narrow handle.","Pull it down toward your chest, squeezing your shoulder blades.","Return slowly, keeping your back straight."]],"Close-Grip_Push-Up_off_of_a_Dumbbell":[["ادخل وضع الضغط وايدك الاتنين على دامبل واحد ثابت، وجسمك خط مستقيم","انزل بصدرك ناحية الدامبل وكوعك قريب من جسمك","ادفع لفوق لحد ما دراعك تتفرد من غير قفل الكوع، وشد بطنك"],["Get in plank with both hands gripping one stable dumbbell, body straight.","Lower your chest toward the dumbbell, elbows tucked close to your body.","Press up until arms extend without locking elbows; keep core tight."]],"Close-Grip_Standing_Barbell_Curl":[["قف وامسك البار بقبضة كف لفوق أضيق من الكتف","اثنِ كوعك وارفع البار لحد الصدر وكوعك ثابت جنب جسمك","انزل ببطء لحد ما دراعك تتفرد، من غير ما تهز ضهرك"],["Stand holding a barbell with an underhand grip narrower than shoulder width.","Curl the bar up toward your chest, elbows pinned to your sides.","Lower slowly until arms extend; don't swing your back."]],"Cocoons":[["اتمدد على ضهرك ورجلك مرفوعة وركبك مثنية وإيدك ورا راسك","اطوي جسمك وقرّب ركبك من صدرك وارفع كتفك عن الأرض","ارجع ببطء وفرد جسمك من غير ما رجلك تلمس الأرض"],["Lie on your back, knees bent and raised, hands behind your head.","Curl up, bringing knees toward your chest and lifting shoulders off the floor.","Return slowly, extending your body without letting your feet touch the floor."]],"Conans_Wheel":[["احط الجهاز أو الأوزان قدامك وامسكها بثبات ورجلك واسعة شوية","ادفع الوزن بحركة دائرية تحكمها بجسمك وضهرك مستقيم","ارجع للوضع الأول ببطء وتحكم، ولو ضهرك بيقوس وقّف"],["Set up the weight or sled in front of you, firm grip, feet shoulder width.","Drive the weight through a controlled circular path, back straight.","Return to start slowly under control; stop if your back rounds."]],"Cross-Body_Crunch":[["اتمدد على ضهرك وركبك مثنية وإيدك ورا راسك","ارفع كتفك والف بكوعك ناحية الركبة المعاكسة","ارجع ببطء وكرر على الناحية التانية، من غير ما تشد رقبتك"],["Lie on your back, knees bent, hands behind your head.","Lift your shoulders and rotate your elbow toward the opposite knee.","Lower slowly and alternate sides; don't pull on your neck."]],"Cross_Body_Hammer_Curl":[["قف وامسك دامبل في كل إيد بقبضة هامر، الكفوف لجسمك","اثنِ الكوع وارفع الدامبل قدام صدرك ناحية الكتف المعاكس","انزل ببطء لحد ما الدراع تتفرد، وكوعك ثابت"],["Stand holding a dumbbell in each hand, palms facing your body.","Curl one dumbbell across your chest toward the opposite shoulder.","Lower slowly to full extension; keep your elbow still."]],"Cross_Over_-_With_Bands":[["ثبّت الباند عالي على الجانبين وامسك كل طرف وقف بميلة خفيفة لقدام","اسحب الإيدين لقدام ولسه الكوع مثني حتى تتقابل قدام صدرك","ارجع ببطء وافتح صدرك مع التحكم في الباند"],["Anchor bands high on both sides, grip the ends, lean slightly forward.","Pull hands down and forward, elbows slightly bent, until they meet in front.","Return slowly, opening the chest while controlling the band."]],"Crossover_Reverse_Lunge":[["قف معتدل وإيدك على وسطك أو قدام صدرك","ارجع برجل ورا وبصها خلف الرجل التانية بشكل متقاطع وانزل بالركبة","ادفع بالرجل الأمامية وارجع للوقوف، وصدرك مرفوع وركبتك مش بتنهار لجوه"],["Stand tall, hands on hips or in front of your chest.","Step one leg back and across behind the other, then lower into a lunge.","Push through the front foot to stand; keep chest up and knee tracking over toes."]],"Crucifix":[["امسك وزنين خفيفين أو اتعلق بوضع ثابت وإيدك مفرودة للجنبين","ثبّت دراعك مفرودة على الجانبين زي الصليب وشد كتفك لتحت","ثبّت المدة المطلوبة ثم نزّل ببطء، ولا تقفل الكوع بقوة"],["Hold light weights with arms extended out to your sides.","Keep arms straight at shoulder height like a cross, shoulders pulled down.","Hold for the target time, then lower slowly without hard-locking elbows."]],"Crunch_-_Hands_Overhead":[["اتمدد على ضهرك وركبك مثنية ومد إيدك فوق راسك","اطوي جسمك وارفع كتفك عن الأرض وإيدك لقدام","انزل ببطء وإيدك فوق راسك، من غير ما تسحب رقبتك"],["Lie on your back, knees bent, arms extended overhead.","Crunch up, lifting your shoulders off the floor with arms reaching forward.","Lower slowly keeping arms overhead; don't strain your neck."]],"Crunch_-_Legs_On_Exercise_Ball":[["اتمدد على ضهرك وحط رجلك على الكورة وركبك بزاوية 90 درجة","ارفع كتفك عن الأرض وشد بطنك وإيدك جنب راسك","انزل ببطء من غير ما تسحب رقبتك أو ترخي الكورة"],["Lie on your back with calves on the ball, knees at 90 degrees.","Lift your shoulders off the floor, tightening abs, hands by your head.","Lower slowly; don't pull your neck or let the ball roll away."]],"Cuban_Press":[["قف وامسك دامبلين وارفع كوعك لجنب بزاوية 90 درجة قدام الصدر","لف دراعك لفوق بحيث الدامبل يبقى فوق كتفك ثم اضغط لفوق","انزل بنفس الترتيب ببطء، وخلي الوزن خفيف لحماية الكتف"],["Stand holding dumbbells, upright-row them up so elbows are out at shoulder height.","Rotate forearms upward, then press the weights overhead.","Reverse the motion slowly; use light weights to protect your shoulders."]],"Dancers_Stretch":[["اتمدد على ضهرك وارفع رجل مثنية وامسكها بإيد","اسحب الرجل بلطف وعدّيها ناحية الجنب المعاكس مع تثبيت كتفك على الأرض","ثبّت 20-30 ثانية وكرر على الناحية التانية"],["Lie on your back, lift one bent leg and hold it with one hand.","Gently guide that leg across your body while keeping both shoulders down.","Hold 20-30 seconds, then switch sides."]],"Deadlift_with_Bands":[["قف والبار على الأرض والباند مثبت وامسك البار بقبضة بعرض الكتف","اسحب بوركك وصدرك لفوق وضهرك مستقيم لحد ما تقف معتدل","انزل البار ببطء بدفع الورك لورا، ولا تقوّس ضهرك"],["Stand at a bar with bands attached; grip just outside your knees.","Drive through your legs and hips, chest up, until you stand tall.","Lower the bar by hinging at hips; keep your back flat throughout."]],"Deadlift_with_Chains":[["قف قدام البار المثبت عليه السلاسل وامسكه بقبضة بعرض الكتف","ارفع بدفع الأرض برجلك وضهرك مستقيم حتى تقف معتدل","انزل البار بتحكم بدفع الورك لورا وضهرك مفرود"],["Stand over a bar loaded with chains, gripping it shoulder width.","Drive through the floor, back flat, until you stand fully upright.","Lower the bar under control by hinging at the hips; keep your back flat."]],"Decline_Close-Grip_Bench_To_Skull_Crusher":[["اتمدد على بنش منخفض وامسك البار بقبضة ضيقة فوق صدرك","انزل البار لصدرك ثم ارفعه، ثم اثنِ الكوع لتنزل البار ناحية الجبهة","افرد الكوع لترجع البار فوق، وخليه ثابت الكتف، واستعن بمساعد"],["Lie on a decline bench, holding a barbell close-grip above your chest.","Lower to your chest and press up, then bend elbows to lower bar toward forehead.","Extend elbows to return the bar overhead; keep upper arms still and use a spotter."]],"Decline_Crunch":[["اتمدد على بنش منخفض وثبّت رجلك تحت الدعامات وإيدك على صدرك","اطوي جسمك وارفع كتفك ناحية ركبك ببطء","انزل ببطء ومن غير ما ترجع لورا، ولا تسحب رقبتك"],["Lie on a decline bench, feet secured, hands across your chest.","Curl your torso up, lifting your shoulders toward your knees.","Lower slowly with control; don't yank your neck."]],"Decline_Dumbbell_Bench_Press":[["اتمدد على بنش منخفض بدامبلين عند جانب صدرك الاسفل","اضغط الدامبلين لفوق لحد ما دراعك تتفرد فوق صدرك","انزل ببطء لحد ما الدامبلين يوصلوا لمستوى صدرك"],["Lie on a decline bench with dumbbells at lower chest level.","Press the dumbbells up until your arms are extended above your chest.","Lower slowly back to chest level with control."]],"Decline_Dumbbell_Flyes":[["اتمدد على بنش منخفض وامسك دامبلين فوق صدرك والكوع مثني خفيف","افتح دراعك للجنبين في قوس واسع لحد ما تحس بمط الصدر","اضم الدامبلين لفوق بقوس نفس القوس، ولا تنزل أبعد من راحتك"],["Lie on a decline bench, dumbbells above chest, elbows slightly bent.","Open your arms wide in an arc until you feel a chest stretch.","Squeeze back up along the same arc; don't go deeper than comfortable."]],"Decline_Dumbbell_Triceps_Extension":[["اتمدد على بنش منخفض وامسك دامبل أو اتنين فوق صدرك ودراعك مفرودة","اثنِ الكوع وانزل الدامبل ناحية الجبهة وكوعك ثابت","افرد الكوع وارجع لفوق، واستعمل وزن خفيف"],["Lie on a decline bench holding dumbbells above chest, arms extended.","Bend elbows, lowering the weights toward your forehead; keep upper arms still.","Extend your elbows back up; use controlled, moderate weight."]],"Decline_EZ_Bar_Triceps_Extension":[["اتمدد على بنش منخفض وامسك EZ بار بقبضة كف لأسفل فوق صدرك","اثنِ الكوع وانزل البار ناحية الجبهة وكوعك ثابت","افرد الكوع وارجع لفوق، واستعن بمساعد مع الأوزان التقيلة"],["Lie on a decline bench holding an EZ bar overhand above your chest.","Bend your elbows, lowering the bar toward your forehead; upper arms still.","Extend elbows to return up; use a spotter on heavy sets."]],"Decline_Oblique_Crunch":[["اتمدد على بنش منخفض وثبّت رجلك وإيدك ورا راسك","اطوي جسمك وألف كتفك ناحية الركبة المعاكسة","انزل ببطء وكرر على الناحيتين، من غير ما تسحب رقبتك"],["Lie on a decline bench, feet secured, hands behind your head.","Crunch up while rotating your shoulder toward the opposite knee.","Lower slowly and repeat both sides; don't pull on your neck."]],"Decline_Reverse_Crunch":[["اتمدد على بنش منخفض ومسك الدعامة بإيدك ورا راسك وركبك مثنية","ارفع ركبك ناحية صدرك وارفع الحوض عن البنش","انزل الحوض ببطء وبتحكم من غير ما تتمايل"],["Lie on a decline bench, gripping the top handles, knees bent.","Pull your knees toward your chest, lifting your hips off the bench.","Lower your hips slowly under control without swinging."]],"Decline_Smith_Press":[["اتمدد على بنش منخفض تحت سميث وامسك البار بقبضة أوسع من الكتف","فك البار وانزله لصدرك السفلي ببطء","اضغط لفوق لحد ما دراعك تتفرد، وارجع البار للحامل لما تخلص"],["Lie on a decline bench under a Smith bar, grip wider than shoulders.","Unrack the bar and lower it slowly to your lower chest.","Press up until arms extend; re-rack the bar when finished."]],"Deficit_Deadlift":[["قف على منصة صغيرة أو قرص وامسك البار بقبضة بعرض الكتف","اسحب بقوة بالرجل والورك وضهرك مستقيم حتى تقف معتدل","انزل بتحكم ورجع البار للأرض بدفع الورك لورا"],["Stand on a small platform and grip the bar shoulder width.","Drive through your legs and hips, back flat, until standing tall.","Lower the bar under control by hinging at the hips."]],"Depth_Jump_Leap":[["قف على صندوق منخفض وانزل بخطوة (مش قفز) للأرض","اهبط بركبة مثنية وانطلق فورًا لقفزة بعيدة لقدام","اهبط بنعومة على ركبة مثنية وخد وقت راحة بين التكرارات"],["Stand on a low box and step off (don't jump) onto the floor.","Land with bent knees, then immediately leap forward as far as you can.","Land softly with bent knees; rest fully between reps."]],"Dip_Machine":[["اجلس على الجهاز وظهرك مسنود وامسك المقابض بجنب جسمك","ادفع المقابض لتحت لحد ما دراعك تتفرد من غير ما تقفل الكوع","ارجع ببطء لحد ما كوعك يوصل 90 درجة، وكتفك لتحت"],["Sit in the machine with back supported, gripping handles at your sides.","Press the handles down until arms extend without locking your elbows.","Return slowly until elbows reach about 90 degrees; keep shoulders down."]],"Dips_-_Triceps_Version":[["اتسند على المتوازيين ودراعك مفرودة وجسمك قايم وكوعك قريب لجنبك","انزل بكوعك للخلف لحد ما تبقى 90 درجة تقريبًا","ادفع لفوق لحد ما تفرد دراعك من غير قفل الكوع"],["Support yourself on parallel bars, arms straight, torso upright, elbows in.","Lower by bending elbows back to about 90 degrees.","Press up until arms extend without hard-locking the elbows."]],"Double_Kettlebell_Alternating_Hang_Clean":[["قف وامسك كيتل بيل في كل إيد بوضع معلق قدام الفخذ وضهرك مستقيم","ادفع الورك لقدام ولف كيتل بيل لوضع الراك عند كتفك","انزل بتحكم وكرر بالتبادل، وخلي الكوع قريب من جسمك"],["Stand holding a kettlebell in each hand, hanging at thigh level, back flat.","Drive your hips forward and pull one bell up to the rack at your shoulder.","Lower with control and alternate sides; keep elbows close to your body."]],"Double_Kettlebell_Jerk":[["قف والكيتل بيلين في وضع الراك عند الكتف وركبك مفرودة","اثنِ ركبك شوية وانطلق لفوق وادفع الكيتل بيلين فوق راسك","ثبّت فوق راسك ثم انزل للراك ببطء بركبة مثنية"],["Stand with both kettlebells racked at your shoulders.","Dip slightly, drive up with your legs, and punch the bells overhead.","Lock out overhead, then lower back to the rack with soft knees."]],"Double_Kettlebell_Push_Press":[["قف والكيتل بيلين في وضع الراك عند الكتف وإيدك قريبة من الصدر","اثنِ ركبك شوية وادفع بالرجل ثم اضغط الكيتل بيلين فوق راسك","انزل للراك بتحكم، وشد بطنك ولا تقوّس ضهرك"],["Stand with both kettlebells racked at your shoulders.","Dip your knees, drive with your legs, and press the bells overhead.","Lower to the rack with control; brace your core, don't arch your back."]],"Double_Kettlebell_Snatch":[["قف والكيتل بيلين بين رجلك وضهرك مفرود والورك لورا","ادفع الورك لقدام وارفع الكيتل بيلين في خط واحد فوق راسك","ثبّت فوق راسك ثم انزلهم بتحكم للوضع الأول"],["Stand with both kettlebells between your feet, hips back, back flat.","Drive your hips forward and pull both bells overhead in one motion.","Lock out overhead, then lower with control back to start."]],"Double_Kettlebell_Windmill":[["قف وكيتل بيل مرفوع فوق راسك والتاني في إيدك التانية ورجلك مفتوحة","ادفع الورك لجنب وانزل بجذعك ناحية الأرض وعينك على الكيتل فوق","ارجع للوقوف ببطء، وحافظ على الدراع العلوية مفرودة"],["Stand with one kettlebell locked overhead, feet wide, other bell in the other hand.","Push your hip out and hinge sideways, eyes on the overhead bell.","Return to standing slowly; keep the overhead arm locked straight."]],"Double_Leg_Butt_Kick":[["قف بوضع الاستعداد وإيدك جنب جسمك وركبك مثنية شوية","اقفز بالرجلين الاتنين وقرب كعبك من مؤخرتك","اهبط بنعومة على مشط القدم وكرر بسرعة معتدلة"],["Stand ready with arms at your sides, knees slightly bent.","Jump with both feet and kick your heels up toward your glutes.","Land softly on the balls of your feet and repeat at a steady pace."]],"Downward_Facing_Balance":[["انبطح بجسمك على الكورة وإيدك على الأرض","ارفع رجلك وإيدك المعاكسة بحيث توازن جسمك على الكورة","ثبّت ثواني ثم نزل ببطء، وشد بطنك لتحافظ على التوازن"],["Lie face down over a stability ball with hands on the floor.","Lift opposite arm and leg to balance on the ball.","Hold a few seconds, then lower slowly; keep your core tight."]],"Drag_Curl":[["قف وامسك البار بقبضة كف لفوق وإيدك قدام فخذك","اسحب البار لأعلى مع جره على جسمك وارجع الكوع للخلف","انزل ببطء وكوعك لورا، ولا تهز ضهرك"],["Stand holding a barbell underhand in front of your thighs.","Curl by dragging the bar up your torso, elbows traveling back.","Lower slowly; don't swing your back."]],"Drop_Push":[["ابدأ بوضع الضغط وجسمك مستقيم ورجلك مثبتة","انزل بسرعة نحو الأرض ثم افجّر بقوة لفوق ليرتفع كفك عن الأرض","اهبط بنعومة على كفك وكوعك مثني شوية ثم كرر"],["Start in a push-up position, body straight.","Lower quickly, then explode up so your hands leave the floor.","Land softly with slightly bent elbows, then repeat."]],"Dumbbell_Bench_Press_with_Neutral_Grip":[["اتمدد على البنش وامسك دامبلين بكفوف متقابلة فوق صدرك","انزل الدامبلين لجانب صدرك وكوعك قريب من جسمك","اضغط لفوق لحد ما دراعك تتفرد من غير قفل قوي"],["Lie on a flat bench holding dumbbells above your chest, palms facing each other.","Lower the dumbbells to your chest sides, elbows close to your body.","Press up until arms extend, without hard-locking elbows."]],"Dumbbell_Clean":[["قف والدامبل بين رجلك وضهرك مستقيم والورك لورا","ادفع الورك لقدام وارفع الدامبل بسرعة لوضع الكتف","انزل الدامبل بتحكم لوضعه الأول وضهرك مفرود"],["Stand with a dumbbell between your feet, hips back, back flat.","Drive hips forward and pull the dumbbell quickly up to your shoulder.","Lower it under control to the start; keep your back flat."]],"Dumbbell_Floor_Press":[["اتمدد على الأرض وركبك مثنية وامسك دامبلين فوق صدرك","انزل الدامبلين لحد ما كوعك يلمس الأرض","اضغط لفوق لحد ما دراعك تتفرد من غير قفل قوي"],["Lie on the floor, knees bent, holding dumbbells above your chest.","Lower until your upper arms touch the floor.","Press up until arms extend without hard-locking."]],"Dumbbell_Incline_Shoulder_Raise":[["اتمدد على بنش مائل بوجهك لأسفل وامسك دامبلين بإيدك المفرودة","ارفع الدامبلين لقدام لحد ما يوصل لمستوى الكتف","انزل ببطء وبتحكم، من غير ما ترفع كتفك لأذنك"],["Lie chest down on an incline bench, holding dumbbells with arms hanging.","Raise the dumbbells forward to shoulder height.","Lower slowly with control; don't shrug your shoulders."]],"Dumbbell_Lying_One-Arm_Rear_Lateral_Raise":[["اتمدد على جنبك على البنش وامسك دامبل بإيدك العليا قدام جسمك","ارفع الدراع لفوق للجنب لحد ما يوصل لمستوى الكتف وكوعك مثني خفيف","انزل ببطء لحد وضعك الأول وكرر وبدل الناحية"],["Lie on your side on a bench, holding a dumbbell in your top hand.","Raise your arm up and out to shoulder height, elbow slightly bent.","Lower slowly to start; repeat, then switch sides."]],"Dumbbell_Lying_Pronation":[["اتمدد على البنش وحط ساعدك على البنش والإيد خارجه ماسكة دامبل خفيف","لف الساعد بحيث كفك يبقى لأسفل","ارجع ببطء لوضعك الأول، وخلي الكوع ثابت واستعمل وزن خفيف"],["Lie on your side, forearm resting on a bench with a light dumbbell in hand.","Rotate your forearm so your palm turns down.","Return slowly to the start; keep elbow still and use light weight."]],"Dumbbell_Lying_Rear_Lateral_Raise":[["اتمدد على بنش مائل بوجهك لأسفل وامسك دامبلين وإيدك للأرض","ارفع الدراعين للجنب لحد مستوى الكتف وكوعك مثني خفيف","انزل ببطء وبتحكم، وضم لوح الكتف في القمة"],["Lie chest down on a bench holding dumbbells, arms hanging.","Raise both arms out to the sides to shoulder height, elbows slightly bent.","Lower slowly; squeeze your shoulder blades at the top."]],"Dumbbell_Lying_Supination":[["اتمدد على جنبك وحط ساعدك على البنش وامسك دامبل خفيف","لف الساعد بحيث كفك يبقى لأعلى","ارجع ببطء لوضعك الأول، وخلي الكوع ثابت واستعمل وزن خفيف"],["Lie on your side, forearm resting on a bench holding a light dumbbell.","Rotate your forearm so your palm turns up.","Return slowly to the start; keep elbow still and use light weight."]],"Dumbbell_One-Arm_Shoulder_Press":[["اجلس أو قف وامسك دامبل عند كتفك بكف للأمام","اضغط الدامبل لفوق لحد ما دراعك تتفرد فوق راسك","انزل ببطء لحد ما الدامبل يرجع للكتف وضهرك مستقيم"],["Sit or stand with a dumbbell at your shoulder, palm forward.","Press it overhead until your arm extends.","Lower slowly back to your shoulder; keep your back straight."]],"Dumbbell_One-Arm_Triceps_Extension":[["قف أو اجلس وامسك دامبل بإيد واحدة فوق راسك ودراعك مفرودة","اثنِ الكوع وانزل الدامبل خلف راسك وكوعك ثابت","افرد الكوع وارجع لفوق، وخلي الدراع قريب من راسك"],["Sit or stand holding one dumbbell overhead, arm extended.","Bend your elbow, lowering the dumbbell behind your head; upper arm still.","Extend back up; keep your upper arm close to your head."]],"Dumbbell_One-Arm_Upright_Row":[["قف وامسك دامبل بإيد واحدة قدام فخذك بكف لجسمك","اسحب الدامبل لفوق قريب من جسمك لحد مستوى الصدر والكوع أعلى من الإيد","انزل ببطء وبتحكم، ولا ترفع الكتف لأذنك"],["Stand holding a dumbbell in one hand in front of your thigh.","Pull it up close to your body to chest level, elbow higher than hand.","Lower slowly under control; don't shrug excessively."]],"Dumbbell_Prone_Incline_Curl":[["انبطح بصدرك على بنش مائل وامسك دامبلين بدراع مفرودة لتحت","اثنِ الكوع وارفع الدامبلين لحد الكتف وكوعك ثابت","انزل ببطء لحد ما الدراع تتفرد بتحكم"],["Lie chest down on an incline bench holding dumbbells, arms hanging.","Curl the dumbbells up toward your shoulders; keep upper arms still.","Lower slowly until arms are fully extended."]],"Dumbbell_Raise":[["قف وامسك دامبلين جنب فخذك وركبك مرنة","ارفع الدامبلين لقدام أو للجنب لحد مستوى الكتف","انزل ببطء وبتحكم، ولا تهز جسمك"],["Stand holding dumbbells at your sides, knees soft.","Raise the dumbbells to shoulder height.","Lower slowly under control; don't swing your body."]],"Dumbbell_Scaption":[["قف وامسك دامبلين جنب فخذك وإبهامك لفوق","ارفع الدراعين بزاوية 30 درجة لقدام الجسم لحد مستوى الكتف","انزل ببطء وبتحكم، واستعمل وزن خفيف"],["Stand holding dumbbells at your sides, thumbs up.","Raise both arms about 30 degrees forward of your sides to shoulder height.","Lower slowly under control; use light weight."]],"Dumbbell_Seated_Box_Jump":[["اجلس على صندوق وامسك دامبل بقرب صدرك وقدمك ثابتة","اقفز لفوق بقوة وامد جسمك قدام لحد ما تقف على الصندوق","انزل بخطوة وبتحكم ولا تهبط بضهر مقوس"],["Sit on a box holding a dumbbell at your chest, feet planted.","Explode up and forward, landing in a stand on the box.","Step down with control; keep your back flat."]],"Dumbbell_Seated_One-Leg_Calf_Raise":[["اجلس وحط دامبل على ركبتك وقدمك على حافة قرص أو درجة","ارفع كعبك لفوق لأعلى ما تقدر وضغط على مشط القدم","انزل ببطء لحد مط السمانة، وكرر وبدل الرجل"],["Sit with a dumbbell on your knee and the ball of your foot on a step.","Raise your heel as high as you can, pressing through your toes.","Lower slowly to a calf stretch; repeat, then switch legs."]],"Dumbbell_Side_Bend":[["قف ورجلك بعرض الكتف وامسك دامبل بإيد واحدة جنبك","اثنِ جذعك للجنب ناحية الدامبل ببطء","ارجع للوقوف بقوة عضلات الجنب، وتجنب الميل لقدام أو لورا"],["Stand feet shoulder width holding a dumbbell in one hand.","Bend sideways toward the weighted side slowly.","Return upright using your obliques; don't lean forward or back."]],"Dumbbell_Squat_To_A_Bench":[["قف قدام البنش وامسك دامبل عند صدرك أو دامبلين جنبك","انزل بورك لورا لحد ما تلمس البنش من غير ما تنهار عليه","ادفع بكعبك لفوق وارجع للوقوف، وصدرك مرفوع وضهرك مستقيم"],["Stand in front of a bench holding dumbbells at your chest or sides.","Sit back until you lightly touch the bench; don't collapse onto it.","Drive through your heels to stand; chest up, back flat."]],"Dumbbell_Tricep_Extension_-Pronated_Grip":[["اتمدد على بنش وامسك دامبلين بكف لأسفل فوق صدرك","اثنِ الكوع وانزل الدامبلين ناحية الجبهة وكوعك ثابت","افرد الكوع وارجع لفوق، واستعمل وزن مناسب"],["Lie on a bench holding dumbbells with an overhand grip above your chest.","Bend elbows, lowering the dumbbells toward your forehead; upper arms still.","Extend back up; use a manageable weight."]],"Dynamic_Back_Stretch":[["قف بدراع مفرودة قدامك وركبك مرنة","لف جذعك وارجع للجنب ببطء مع تقوس الظهر وفتح الكتف","كرر الحركة بسلاسة 10 مرات، ولا تتحرك بعنف"],["Stand with arms extended in front, knees soft.","Rotate and reach your torso slowly side to side, opening your upper back.","Repeat smoothly for about 10 reps; avoid jerky movement."]],"Dynamic_Chest_Stretch":[["قف ومد دراعك للجنب بمستوى الكتف","افتح دراعك للخلف لتمط صدرك وارجعها لقدام ببطء","كرر الحركة بسلاسة 10-15 مرة من غير حركات عنيفة"],["Stand with arms out to your sides at shoulder height.","Swing your arms back to open your chest, then bring them forward.","Repeat smoothly 10-15 times without jerky movement."]],"Elbow_Circles":[["قف وضع إيدك على كتفك والكوع للجنب","ارسم دوائر بكوعك للأمام ببطء وبدون ألم","بدل الاتجاه للخلف وكرر، وخلي الحركة بسيطة"],["Stand with fingertips on your shoulders, elbows out to the sides.","Draw slow circles forward with your elbows.","Reverse direction and repeat; keep the motion smooth."]],"Elbow_to_Knee":[["اتمدد على ضهرك وإيدك ورا راسك وركبك مثنية","ارفع كتفك وقرّب كوعك من الركبة المعاكسة مع مد الرجل التانية","بدل الجانبين ببطء، ولا تسحب رقبتك"],["Lie on your back, hands behind your head, knees bent.","Lift your shoulders and bring one elbow toward the opposite knee.","Alternate sides slowly; don't pull on your neck."]],"Elbows_Back":[["قف أو اجلس معتدل وإيدك على الجنب والكوع مثني","اسحب كوعك للخلف وضم لوح الكتف مع فتح الصدر","ثبّت 15-20 ثانية ثم ارتاح"],["Stand or sit tall with elbows bent at your sides.","Pull your elbows back, squeezing your shoulder blades and opening the chest.","Hold 15-20 seconds, then relax."]],"Elevated_Back_Lunge":[["قف والبار على ظهرك وقدمك على منصة صغيرة وضهرك مستقيم","ارجع برجل لورا وانزل بالركبة الخلفية ناحية الأرض","ادفع بالرجل الأمامية وارجع للوقوف، وصدرك مرفوع"],["Stand with a barbell on your upper back, front foot on a low platform.","Step one leg back and lower your rear knee toward the floor.","Push through the front foot to stand; keep chest up."]],"Elevated_Cable_Rows":[["اجلس على الجهاز مرتفع وامسك المقبض ودراعك مفرودة وضهرك مستقيم","اسحب المقبض ناحية صدرك وضم لوح الكتف","ارجع ببطء لحد ما الدراع تتفرد من غير ما تتمايل"],["Sit at the elevated cable station, gripping the handle, arms extended, back straight.","Pull the handle toward your chest, squeezing your shoulder blades.","Return slowly until arms extend; don't rock your torso."]],"Exercise_Ball_Crunch":[["اجلس على الكورة وانزل بضهرك عليها وقدمك ثابتة وإيدك ورا راسك","اطوي جسمك وارفع كتفك من الكورة وشد بطنك","انزل ببطء لتمط البطن، ولا تسحب رقبتك"],["Lie back on the ball, feet planted, hands behind your head.","Crunch up, lifting your shoulders off the ball and tightening abs.","Lower slowly into a gentle stretch; don't pull your neck."]],"Exercise_Ball_Pull-In":[["ابدأ بوضع الضغط ورجلك على الكورة وإيدك على الأرض","اسحب ركبك لصدرك وخلي الكورة تتحرك لقدام","ارجع للوضع الأول ببطء وضهرك مستقيم"],["Start in a push-up position with shins on a stability ball.","Pull your knees toward your chest, rolling the ball forward.","Extend back to start slowly; keep your back straight."]],"Extended_Range_One-Arm_Kettlebell_Floor_Press":[["اتمدد على الأرض وامسك كيتل بيل بإيد واحدة فوق صدرك والركبة مثنية","انزل الكيتل بيل لحد ما كوعك يلمس الأرض ثم اضغط لفوق","افرد الدراع بالكامل وحرّك الكتف لقدام شوية في القمة"],["Lie on the floor holding a kettlebell in one hand above your chest, knees bent.","Lower until your elbow touches the floor, then press up.","Fully extend, letting your shoulder blade protract slightly at the top."]],"External_Rotation_with_Band":[["قف وثبّت الباند بجنبك وامسك الطرف والكوع مثني 90 درجة ملصق بجنبك","لف ساعدك للخارج ببطء بدون تحريك الكوع","ارجع للوضع الأول ببطء ولا تسحب الباند بسرعة"],["Stand with a band anchored at your side, elbow bent 90 degrees against your ribs.","Rotate your forearm outward slowly without moving the elbow.","Return slowly; don't snap the band back."]],"External_Rotation_with_Cable":[["قف جنب الكابل وامسك المقبض والكوع مثني 90 درجة ملصق بجنبك","لف ساعدك للخارج ببطء بدون تحريك الكوع","ارجع بتحكم واستعمل وزن خفيف"],["Stand beside a cable, holding the handle, elbow bent 90 degrees at your side.","Rotate your forearm outward slowly without moving the elbow.","Return under control; use light weight."]],"External_Rotation":[["اتمدد على جنبك وامسك دامبل خفيف والكوع مثني 90 درجة ملصق بجنبك","لف ساعدك لفوق ببطء بدون تحريك الكوع","انزل ببطء وبتحكم، واستعمل وزن خفيف"],["Lie on your side holding a light dumbbell, elbow bent 90 degrees at your ribs.","Rotate your forearm upward slowly without moving the elbow.","Lower slowly under control; use light weight."]],"Fast_Skipping":[["قف معتدل وإيدك مثنية بزاوية 90 درجة ووزنك على مشط القدم","اقفز بالتبادل بسرعة مع رفع الركبة وحركة الدراعين","حافظ على إيقاع سريع وهبوط ناعم، وتنفس بانتظام"],["Stand tall, arms bent 90 degrees, weight on the balls of your feet.","Skip quickly, alternating knee drives with arm swings.","Keep a fast rhythm and soft landings; breathe steadily."]],"Finger_Curls":[["اجلس وامسك بار خفيف وساعدك على فخذك والإيد خارجها","افتح أصابعك وخلي البار ينزل لحد أطراف الأصابع","اغلق أصابعك وارفع البار ببطء، واستعمل وزن خفيف"],["Sit with forearms on your thighs holding a light barbell, hands past your knees.","Let the bar roll down to your fingertips.","Curl it back up with your fingers; use light weight."]],"Flat_Bench_Leg_Pull-In":[["اجلس على حافة البنش وإيدك تمسك الجنب ورجلك مفرودة","اسحب ركبك ناحية صدرك مع ميل الجذع لقدام","افرد رجلك ببطء ولا تلمس الأرض، وبطنك مشدودة"],["Sit at the edge of a bench, hands gripping the sides, legs extended.","Pull your knees toward your chest as your torso leans in.","Extend legs slowly without touching the floor; keep abs tight."]],"Flexor_Incline_Dumbbell_Curls":[["اجلس على بنش مائل وامسك دامبلين بدراع مفرودة لتحت","اثنِ الكوع ولف الدامبل لتبقى الكف لقدام وارفع ببطء","انزل ببطء لحد ما الدراع تتفرد بتحكم"],["Sit back on an incline bench holding dumbbells, arms hanging.","Curl up while rotating your palms forward, slowly.","Lower slowly until arms fully extend."]],"Floor_Glute-Ham_Raise":[["اركع على الأرض وثبّت كعبك تحت شيء ثابت وجسمك مستقيم","انزل جسمك لقدام ببطء بمرونة الهامسترنج ثم ادفع بإيدك لو احتجت","اسحب بالهامسترنج ورجع جسمك للوضع الأول"],["Kneel on the floor with heels anchored under something stable, body straight.","Lower your torso forward slowly under hamstring control; use hands to catch if needed.","Pull back up with your hamstrings to the start."]],"Floor_Press_with_Chains":[["اتمدد على الأرض وامسك البار المحمل بالسلاسل فوق صدرك","انزل لحد ما كوعك يلمس الأرض","اضغط لفوق لحد ما دراعك تتفرد، واستعن بمساعد"],["Lie on the floor holding a chained barbell above your chest.","Lower until your elbows touch the floor.","Press up until arms extend; use a spotter."]],"Floor_Press":[["اتمدد على الأرض وركبك مثنية وامسك البار فوق صدرك","انزل لحد ما كوعك يلمس الأرض","اضغط لفوق لحد ما دراعك تتفرد، واستعن بمساعد"],["Lie on the floor, knees bent, holding a barbell above your chest.","Lower until your elbows touch the floor.","Press up until arms extend; use a spotter."]],"Foot-SMR":[["قف أو اجلس وحط كرة أو رول تحت قدمك","دحرج قدمك ببطء من الكعب للمشط","اقف عند أي نقطة مشدودة 20-30 ثانية، وتنفس بهدوء"],["Stand or sit and place a ball or roller under your foot.","Roll slowly from heel to toes.","Pause 20-30 seconds on tight spots, breathing calmly."]],"Forward_Drag_with_Press":[["احط الحبل أو الزحافة قدامك وامسك المقبض وقف بوضع قوي","اسحب أو دفع الوزن لقدام ثم اضغط بإيدك لفوق","ارجع بتحكم، وخلي ضهرك مستقيم"],["Set up in front of the sled or rope, gripping the handles in a strong stance.","Drag or drive the weight forward, then press up with your hands.","Return with control; keep your back straight."]],"Frankenstein_Squat":[["قف والبار على كتفك الأمامي وإيدك مفرودة قدامك","انزل بالسكوات لحد ما فخذك يوازي الأرض","ادفع بكعبك لفوق وصدرك مرفوع وضهرك مستقيم"],["Stand with the bar resting on your front shoulders, arms extended forward.","Squat down until your thighs are parallel to the floor.","Drive up through your heels; keep chest up and back straight."]],"Frog_Hops":[["انزل لوضع القرفصاء وإيدك بين رجلك","اقفز لفوق وقدام بقوة وإيدك للأمام","اهبط بنعومة بركبة مثنية وكرر"],["Drop into a deep squat with hands between your feet.","Leap up and forward explosively.","Land softly on bent knees and repeat."]],"Frog_Sit-Ups":[["اتمدد على ضهرك وقدمك ملصقة ببعض والركبة للجنب","اطوي جسمك وارفع صدرك لقدام وإيدك لقدام","انزل ببطء مع الحفاظ على تحريك الجذع بتحكم"],["Lie on your back with soles together and knees out to the sides.","Sit up, bringing your chest forward with arms reaching.","Lower slowly with control."]],"Front_Barbell_Squat_To_A_Bench":[["قف والبار على كتفك الأمامي وكوعك مرفوع قدام البنش","انزل بورك لورا لحد ما تلمس البنش بدون ما تنهار","ادفع بكعبك لفوق وارجع للوقوف مع ضهرك مستقيم"],["Stand in front of a bench with the bar racked on your front shoulders, elbows high.","Sit back until you lightly touch the bench without collapsing.","Drive up through your heels to stand, back straight."]],"Front_Cable_Raise":[["قف وأدر ظهرك للكابل وامسك المقبض بكف لأسفل","ارفع الدراع لقدام لحد مستوى الكتف","انزل ببطء بتحكم، ولا تقوّس ضهرك"],["Stand facing away from the cable, gripping the handle overhand.","Raise your arm forward to shoulder height.","Lower slowly under control; don't arch your back."]],"Front_Cone_Hops_or_hurdle_hops":[["قف قدام قمع أو حاجز صغير ورجلك بعرض الكتف","اقفز بالرجلين مع بعض فوقه وارفع الركبة","اهبط بنعومة على ركبة مثنية وكرر"],["Stand in front of a cone or low hurdle, feet shoulder width.","Jump over it with both feet, driving knees up.","Land softly on bent knees and repeat."]],"Front_Incline_Dumbbell_Raise":[["اتمدد على بنش مائل بصدرك لأسفل وامسك دامبلين","ارفع الدراعين لقدام لحد مستوى الكتف","انزل ببطء وبتحكم، وخلي الجسم ثابت"],["Lie chest down on an incline bench holding dumbbells.","Raise your arms forward to shoulder height.","Lower slowly; keep your body still."]],"Front_Leg_Raises":[["قف معتدل وامسك حاجة ثابتة للتوازن","ارفع رجلك لقدام مفرودة لأعلى ما تقدر","انزل ببطء وبدل الرجل، وخلي ضهرك مستقيم"],["Stand tall, holding something steady for balance.","Swing one straight leg forward as high as comfortable.","Lower slowly and switch legs; keep your back straight."]],"Front_Raise_And_Pullover":[["اتمدد على بنش وامسك البار بقبضة ضيقة فوق صدرك","انزل البار خلف راسك بدراع مفرودة بقوس","ارجع البار فوق صدرك ببطء، وخلي الكوع مثني خفيف"],["Lie on a bench holding a barbell above your chest with a narrow grip.","Lower the bar in an arc behind your head, arms nearly straight.","Return it over your chest slowly; keep elbows slightly bent."]],"Front_Squat_Clean_Grip":[["قف والبار على كتفك الأمامي بقبضة الكلين وكوعك مرتفع","انزل بالسكوات لحد ما فخذك يوازي الأرض","ادفع بكعبك لفوق وصدرك مرفوع وضهرك مستقيم"],["Stand with the bar on your front shoulders in a clean grip, elbows high.","Squat down until thighs are parallel to the floor.","Drive up through your heels; keep chest up and back straight."]],"Front_Squats_With_Two_Kettlebells":[["قف والكيتل بيلين في وضع الراك عند الكتف وكوعك قريب لجسمك","انزل بالسكوات مع الحفاظ على صدرك مرفوع","ادفع بكعبك لفوق وارجع للوقوف، وضهرك مستقيم"],["Stand with two kettlebells racked at your shoulders, elbows close.","Squat down, keeping your chest up.","Drive up through your heels to stand; back straight."]],"Front_Two-Dumbbell_Raise":[["قف وامسك دامبلين قدام فخذك بكف لأسفل","ارفع الدامبلين لقدام لحد مستوى الكتف","انزل ببطء بتحكم، ولا تهز جسمك"],["Stand holding dumbbells in front of your thighs, palms down.","Raise both dumbbells forward to shoulder height.","Lower slowly under control; don't swing your body."]],"Full_Range-Of-Motion_Lat_Pulldown":[["اجلس على الجهاز وثبّت فخذك وامسك البار بقبضة أوسع من الكتف","اسحب البار لحد أعلى صدرك مع ضم لوح الكتف","ارجع ببطء لحد ما دراعك تتفرد بالكامل"],["Sit at the lat pulldown, thighs secured, gripping the bar wider than shoulders.","Pull the bar to your upper chest, squeezing your shoulder blades.","Return slowly until your arms fully extend."]],"Gironda_Sternum_Chins":[["اتعلق في البار بقبضة كف لفوق أو أوسع شوية","اسحب نفسك لحد ما صدرك يلمس البار مع ميل الجسم لورا","انزل ببطء لحد ما الدراع تتفرد، ولا تتمايل"],["Hang from a bar with an underhand or slightly wider grip.","Pull until your sternum reaches the bar, leaning back.","Lower slowly until arms extend; don't swing."]],"Glute_Ham_Raise":[["ثبّت كعبك على الجهاز وفخذك على الوسادة وجسمك معلق لتحت","ارفع جذعك لحد ما يوصل لخط مستقيم مع رجلك","انزل ببطء وبتحكم، وضهرك مستقيم"],["Secure your heels in the machine with your thighs on the pad, torso hanging down.","Raise your torso until your body forms a straight line.","Lower slowly under control; keep your back straight."]],"Glute_Kickback":[["ابدأ على إيدك وركبك وضهرك مستقيم","ارفع رجل واحدة للخلف ولفوق وانقبض الجلوت","انزل ببطء وبدل الرجل، ولا تقوّس ضهرك"],["Start on hands and knees, back flat.","Kick one leg back and up, squeezing your glute.","Lower slowly and switch legs; don't arch your lower back."]],"Good_Morning_off_Pins":[["قف والبار على ظهرك وفوق الدبابيس وضهرك مستقيم","ادفع الورك لورا وانزل بجذعك لحد ما يوازي الأرض","اسحب بالورك وارجع للوقوف، وركبك مثنية خفيف وضهرك مفرود"],["Stand with the bar on your back, set at pin height, back flat.","Push your hips back and lower your torso until parallel to the floor.","Drive hips forward to stand; knees soft, back flat."]],"Gorilla_Chin_Crunch":[["اتعلق على البار أو اتمسك بوضع ثابت وإيدك مفرودة","اسحب نفسك وقرّب ذقنك وركبك من بعض","انزل ببطء، وشد بطنك وتجنب الترجح"],["Hang from a bar with arms extended.","Pull up while drawing your chin and knees together.","Lower slowly; brace your abs and avoid swinging."]],"Groin_and_Back_Stretch":[["اجلس على الأرض ورجلك مفتوحة بقدر ما تقدر","اثنِ جذعك لقدام بين رجلك وضهرك مستقيم","ثبّت 20-30 ثانية وتنفس بعمق"],["Sit on the floor with legs spread as wide as comfortable.","Lean forward between your legs, keeping your back straight.","Hold 20-30 seconds, breathing deeply."]],"Groiners":[["ابدأ بوضع الضغط وجسمك مستقيم","اتقدم برجل لجنب إيدك وانزل بالحوض لمط الفخذ","ارجع للوضع الأول وكرر على الناحية التانية"],["Start in a push-up position, body straight.","Step one foot outside your hand and sink your hips to stretch the groin.","Return to start and alternate sides."]],"Hammer_Grip_Incline_DB_Bench_Press":[["اتمدد على بنش مائل وامسك دامبلين بكفوف متقابلة عند الكتف","اضغط الدامبلين لفوق لحد ما دراعك تتفرد","انزل ببطء لحد ما الدامبلين يوصلوا مستوى الصدر"],["Lie on an incline bench holding dumbbells with palms facing each other at your chest.","Press the dumbbells up until your arms extend.","Lower slowly back to chest level."]],"Hamstring-SMR":[["اجلس على الأرض وحط الفوم رولر تحت فخذك الخلفي وإيدك على الأرض","ارفع الحوض ودحرج الفوم رولر ببطء من أسفل الورك لفوق الركبة","اقف عند أي نقطة مشدودة 20-30 ثانية وتنفس بهدوء"],["Sit with a foam roller under your hamstrings, hands on the floor.","Lift your hips and roll slowly from below the glutes to above the knee.","Pause 20-30 seconds on tight spots, breathing calmly."]],"Hamstring_Stretch":[["اجلس على الأرض ومد رجل وثني الرجل التانية","اثنِ جذعك لقدام وضهرك مستقيم لحد ما تحس بمط فخذك الخلفي","ثبّت 20-30 ثانية وبدل الرجل"],["Sit with one leg extended and the other bent.","Hinge forward with a straight back until you feel a hamstring stretch.","Hold 20-30 seconds, then switch legs."]],"Handstand_Push-Ups":[["اقف على يدك قدام الحيطة وجسمك مستقيم وظهرك للحيطة","انزل ببطء لحد ما راسك تقرب من الأرض","ادفع لفوق بقوة لحد ما تفرد دراعك، ولا تقوّس ضهرك"],["Kick up into a handstand against a wall, body straight.","Lower slowly until your head nears the floor.","Press up forcefully until arms extend; don't arch your back."]],"Hang_Clean_-_Below_the_Knees":[["امسك البار بقبضة بعرض الكتف ودلّيه تحت الركبة بضهر مستقيم","ادفع الورك لقدام واسحب البار بسرعة لوضع الراك عند الكتف","نزّل البار بتحكم لتحت الركبة وكرر"],["Grip the bar shoulder width and lower it below the knees, back flat.","Drive hips forward and pull the bar quickly to the front rack.","Lower under control to below the knees and repeat."]],"Hang_Clean":[["امسك البار بقبضة بعرض الكتف ودلّيه عند الفخذ بضهر مستقيم","ادفع الورك لقدام واسحب البار بسرعة لوضع الراك عند الكتف","نزّل البار بتحكم وكرر"],["Grip the bar shoulder width and hold it at the thighs, back flat.","Drive hips forward and pull the bar quickly to the front rack.","Lower under control and repeat."]],"Hang_Snatch_-_Below_Knees":[["امسك البار بقبضة واسعة ودلّيه تحت الركبة بضهر مستقيم","ادفع الورك لقدام واسحب البار لفوق راسك في حركة واحدة","ثبّت فوق راسك ثم نزّل البار بتحكم"],["Grip the bar wide and lower it below the knees, back flat.","Drive hips forward and pull the bar overhead in one motion.","Stabilize overhead, then lower the bar with control."]],"Hang_Snatch":[["امسك البار بقبضة واسعة ودلّيه عند الفخذ بضهر مستقيم","ادفع الورك لقدام واسحب البار لفوق راسك في حركة واحدة","ثبّت فوق راسك ثم نزّل البار بتحكم"],["Grip the bar wide and hold it at the thighs, back flat.","Drive hips forward and pull the bar overhead in one motion.","Stabilize overhead, then lower the bar with control."]],"Hanging_Bar_Good_Morning":[["قف والبار على ظهرك وضهرك مستقيم","ادفع الورك لورا وانزل بجذعك لحد ما يوازي الأرض","ارجع للوقوف بدفع الورك لقدام، وركبك مثنية خفيف"],["Stand with the bar across your upper back, back flat.","Push your hips back and lower your torso until parallel to the floor.","Drive hips forward to stand; knees slightly bent."]],"Hanging_Pike":[["اتعلق في البار بإيدك ورجلك مفرودة","ارفع رجلك مفرودة لقدام لحد ما تلمس البار أو تقرب منه","انزل ببطء بتحكم من غير ما تتأرجح"],["Hang from a bar with legs straight.","Raise your straight legs up toward the bar, folding at the hips.","Lower slowly with control; don't swing."]],"Heaving_Snatch_Balance":[["قف والبار على ظهرك وإيدك بقبضة السناتش الواسعة","ادفع بالرجل لفوق وانزل تحت البار بالسكوات العميق وإيدك مفرودة","قف بالبار فوق راسك وثبّت ثم نزل بتحكم"],["Stand with the bar on your back, snatch-width grip.","Dip, drive, and drop under the bar into a deep squat with arms locked.","Stand up with the bar overhead and stabilize, then lower with control."]],"Heavy_Bag_Thrust":[["قف قدام الكيس الثقيل ووزنك على رجلك الخلفية وإيدك في مستوى الصدر","ادفع بكلتا إيدك الكيس لقدام مع دفع الجسم بالرجل","ارجع للوضع الأول بسرعة وكرر"],["Stand in front of the heavy bag, weight on your back leg, hands at chest.","Thrust both hands into the bag, driving from your legs.","Return to start quickly and repeat."]],"High_Cable_Curls":[["قف بين كابلين عاليين وامسك المقبضين ودراعك مفرودة للجنب","اثنِ الكوع وقرّب الإيد من راسك مع ثبات الكوع","ارجع ببطء وبتحكم لحد ما الدراع تتفرد"],["Stand between two high cables, gripping handles with arms out to the sides.","Curl your hands toward your head, keeping upper arms still.","Return slowly under control until arms extend."]],"Hip_Circles_prone":[["انبطح على بطنك أو وضع على إيدك وركبك","ارفع ركبة وارسم دوائر بالورك ببطء","كرر في الاتجاهين وخلي الحركة بسيطة"],["Get on hands and knees or lie prone.","Lift one knee and draw slow circles with your hip.","Repeat in both directions with smooth, small movements."]],"Hip_Extension_with_Bands":[["اربط الباند حول كاحلك وقف وتسند بإيدك","ارجع برجل لورا وانقبض الجلوت","ارجع ببطء وبدل الرجل، وضهرك مستقيم"],["Loop a band around your ankles and stand, holding support.","Extend one leg back, squeezing your glute.","Return slowly and switch legs; keep your back straight."]],"Hip_Flexion_with_Band":[["اربط الباند حول كاحلك وقف وتسند بإيدك","ارفع ركبتك لقدام ضد مقاومة الباند","ارجع ببطء وبدل الرجل، وضهرك مستقيم"],["Loop a band around your ankle and stand, holding support.","Lift your knee forward against the band's resistance.","Return slowly and switch legs; keep your back straight."]],"Hip_Lift_with_Band":[["اتمدد على ضهرك وركبك مثنية والباند حول فخذك","ارفع الحوض لفوق وانقبض الجلوت مع دفع الباند للخارج","انزل ببطء وبتحكم، ولا تقوّس ضهرك"],["Lie on your back, knees bent, band around your thighs.","Lift your hips, squeezing your glutes and pushing knees out against the band.","Lower slowly with control; don't over-arch your back."]],"Hug_A_Ball":[["اجلس أو اركع وحط الكورة قدامك واحضنها بإيدك","ادفع الكورة لقدام وانحني بجذعك لمط الضهر","ثبّت 20-30 ثانية وتنفس بعمق"],["Sit or kneel and hug a stability ball in front of you.","Roll the ball forward, leaning in to stretch your back.","Hold 20-30 seconds, breathing deeply."]],"Hug_Knees_To_Chest":[["اتمدد على ضهرك وركبك مثنية","اسحب ركبك لصدرك واحضنها بإيدك","ثبّت 20-30 ثانية وتنفس بهدوء"],["Lie on your back, knees bent.","Pull both knees to your chest and hug them.","Hold 20-30 seconds, breathing calmly."]],"Hurdle_Hops":[["قف قدام حاجز منخفض ورجلك بعرض الكتف","اقفز بالرجلين مع بعض فوق الحاجز وارفع الركبة","اهبط بنعومة على ركبة مثنية وكرر"],["Stand in front of a low hurdle, feet shoulder width.","Jump over it with both feet, driving knees up.","Land softly on bent knees and repeat."]],"Hyperextensions_With_No_Hyperextension_Bench":[["انبطح على بطنك على الأرض ورجلك مثبتة وإيدك جنب راسك","ارفع صدرك وراسك لفوق بقوة ضهرك السفلي","انزل ببطء ولا ترفع أعلى من اللازم عشان تحمي الضهر"],["Lie face down on the floor, legs secured, hands beside your head.","Lift your chest and head using your lower back.","Lower slowly; don't over-extend to protect your spine."]],"IT_Band_and_Glute_Stretch":[["اتمدد على ضهرك وثني رجل وعدّيها فوق الرجل التانية","اسحب الرجل المثنية ناحية صدرك ولف جسمك للجنب","ثبّت 20-30 ثانية وبدل الرجل"],["Lie on your back and cross one bent leg over the other.","Pull the legs toward your chest, rotating slightly to the side.","Hold 20-30 seconds, then switch sides."]],"Iliotibial_Tract-SMR":[["اتمدد على جنبك والفوم رولر تحت فخذك الجانبي وإيدك على الأرض","دحرج الفوم رولر ببطء من الورك لحد فوق الركبة","اقف عند أي نقطة مشدودة 20-30 ثانية وتنفس بهدوء"],["Lie on your side with a foam roller under your outer thigh.","Roll slowly from hip to just above the knee.","Pause 20-30 seconds on tight spots, breathing calmly."]],"Inchworm":[["قف معتدل ثم انحني ولمس الأرض بإيدك","امش بإيدك لقدام لحد وضع الضغط","امش برجلك ناحية إيدك وقف وكرر"],["Stand tall, then fold forward and touch the floor.","Walk your hands out to a push-up position.","Walk your feet toward your hands, stand up, and repeat."]],"Incline_Barbell_Triceps_Extension":[["اتمدد على بنش مائل وامسك البار بقبضة ضيقة فوق صدرك","اثنِ الكوع وانزل البار خلف راسك وكوعك ثابت","افرد الكوع وارجع لفوق، واستعن بمساعد"],["Lie on an incline bench holding a barbell close-grip above your chest.","Bend elbows, lowering the bar behind your head; upper arms still.","Extend back up; use a spotter."]],"Incline_Bench_Pull":[["اتمدد على بنش مائل بصدرك لأسفل وامسك البار بدراع مفرودة","اسحب البار لفوق ناحية صدرك وضم لوح الكتف","انزل ببطء وبتحكم لحد ما الدراع تتفرد"],["Lie chest down on an incline bench holding a barbell with arms extended.","Pull the bar up toward your chest, squeezing your shoulder blades.","Lower slowly until arms extend."]],"Incline_Cable_Chest_Press":[["اتمدد على بنش مائل بين كابلين وامسك المقبضين عند الصدر","اضغط المقبضين لفوق ولقدام لحد ما دراعك تتفرد","ارجع ببطء وبتحكم لحد مستوى الصدر"],["Lie on an incline bench between cables, gripping the handles at chest level.","Press the handles up and forward until your arms extend.","Return slowly with control to chest level."]],"Incline_Cable_Flye":[["اتمدد على بنش مائل بين كابلين وامسك المقبضين بدراع مفتوحة والكوع مثني خفيف","اضم المقبضين لفوق صدرك بقوس واسع","ارجع بتحكم وافتح صدرك لمط خفيف"],["Lie on an incline bench between cables, gripping handles with arms wide, elbows slightly bent.","Bring the handles together above your chest in a wide arc.","Return under control, opening your chest for a gentle stretch."]],"Incline_Dumbbell_Bench_With_Palms_Facing_In":[["اتمدد على بنش مائل وامسك دامبلين بكفوف متقابلة عند الصدر","اضغط الدامبلين لفوق لحد ما دراعك تتفرد","انزل ببطء لحد مستوى الصدر"],["Lie on an incline bench holding dumbbells with palms facing each other at chest level.","Press the dumbbells up until your arms extend.","Lower slowly back to chest level."]],"Incline_Dumbbell_Flyes_-_With_A_Twist":[["اتمدد على بنش مائل وامسك دامبلين فوق صدرك والكوع مثني خفيف","افتح دراعك للجنبين في قوس واسع","اضم الدامبلين وأثناء الرفع لف الإيد لتتقابل الكفوف"],["Lie on an incline bench, dumbbells above your chest, elbows slightly bent.","Open your arms wide in an arc.","Bring them back up while rotating your wrists so palms face each other."]],"Incline_Dumbbell_Flyes":[["اتمدد على بنش مائل وامسك دامبلين فوق صدرك والكوع مثني خفيف","افتح دراعك للجنبين في قوس واسع لحد مط الصدر","اضم الدامبلين لفوق بنفس القوس ببطء"],["Lie on an incline bench, dumbbells above your chest, elbows slightly bent.","Open your arms wide in an arc until you feel a chest stretch.","Squeeze back up along the same arc slowly."]],"Incline_Hammer_Curls":[["اجلس على بنش مائل وامسك دامبلين بكفوف متقابلة وإيدك لتحت","اثنِ الكوع وارفع الدامبلين لحد الكتف وكوعك ثابت","انزل ببطء لحد ما الدراع تتفرد"],["Sit back on an incline bench holding dumbbells, palms facing in, arms hanging.","Curl up toward your shoulders; keep upper arms still.","Lower slowly until arms are fully extended."]],"Incline_Inner_Biceps_Curl":[["اجلس على بنش مائل وامسك دامبلين بكف لفوق وإيدك لتحت","اثنِ الكوع وارفع الدامبلين لحد الكتف وكوعك للأمام شوية","انزل ببطء لحد ما الدراع تتفرد"],["Sit back on an incline bench holding dumbbells, palms up, arms hanging.","Curl up toward your shoulders, elbows slightly forward.","Lower slowly until arms are fully extended."]],"Incline_Push-Up_Close-Grip":[["حط إيدك على بنش أو حافة مرتفعة بعرض ضيق وجسمك خط مستقيم","انزل بصدرك ناحية الحافة وكوعك قريب لجسمك","ادفع لفوق لحد ما دراعك تتفرد، وشد بطنك"],["Place hands narrow on a raised bench or ledge, body in a straight line.","Lower your chest toward the edge, elbows close to your body.","Press up until arms extend; keep core tight."]],"Incline_Push-Up_Depth_Jump":[["ابدأ بضغط مائل وإيدك على بنش مرتفع","انزل بسرعة ثم ادفع بقوة لفوق ليرتفع كفك عن البنش","اهبط بنعومة على كفك والكوع مثني شوية"],["Start in an incline push-up with hands on a raised bench.","Lower quickly, then explode up so your hands leave the bench.","Land softly with slightly bent elbows."]],"Incline_Push-Up_Medium":[["حط إيدك على بنش مرتفع بعرض الكتف وجسمك خط مستقيم","انزل بصدرك ناحية الحافة وكوعك بزاوية 45 درجة","ادفع لفوق لحد ما دراعك تتفرد، وشد بطنك"],["Place hands on a raised bench shoulder width, body in a straight line.","Lower your chest to the edge, elbows at about 45 degrees.","Press up until arms extend; keep core tight."]],"Incline_Push-Up_Reverse_Grip":[["حط إيدك على بنش مرتفع بقبضة عكسية وأصابعك لجسمك وجسمك مستقيم","انزل بصدرك ناحية الحافة وكوعك قريب لجسمك","ادفع لفوق لحد ما دراعك تتفرد، واستعمل مرونة رسغك براحة"],["Place hands on a raised bench with fingers pointing back toward you, body straight.","Lower your chest to the edge, elbows close to your body.","Press up until arms extend; stop if your wrists hurt."]],"Incline_Push-Up_Wide":[["حط إيدك على بنش مرتفع بعرض أوسع من الكتف وجسمك خط مستقيم","انزل بصدرك ناحية الحافة وكوعك للجنب","ادفع لفوق لحد ما دراعك تتفرد، وشد بطنك"],["Place hands on a raised bench wider than shoulders, body in a straight line.","Lower your chest to the edge, elbows flaring out.","Press up until arms extend; keep core tight."]],"Incline_Push-Up":[["حط إيدك على بنش مرتفع بعرض الكتف وجسمك خط مستقيم","انزل بصدرك ناحية الحافة وكوعك قريب","ادفع لفوق لحد ما دراعك تتفرد، وشد بطنك"],["Place hands on a raised bench shoulder width, body in a straight line.","Lower your chest toward the edge, elbows close.","Press up until arms extend; keep core tight."]],"Intermediate_Groin_Stretch":[["اجلس على الأرض وضم قدميك لبعض والركبة للجنب","اضغط ركبك لتحت بلطف مع ميل جذعك لقدام","ثبّت 20-30 ثانية وتنفس بهدوء"],["Sit on the floor with the soles of your feet together, knees out.","Gently press your knees down while leaning forward.","Hold 20-30 seconds, breathing calmly."]],"Intermediate_Hip_Flexor_and_Quad_Stretch":[["اجلس على ركبة واحدة والرجل التانية قدامك مثنية","اسحب كعب الرجل الخلفية ناحية مؤخرتك وادفع الورك لقدام","ثبّت 20-30 ثانية وبدل الرجل"],["Kneel on one knee with the other foot in front, bent.","Pull your rear heel toward your glute and push hips forward.","Hold 20-30 seconds, then switch legs."]],"Internal_Rotation_with_Band":[["قف وثبّت الباند بجنبك وامسك الطرف والكوع مثني 90 درجة ملصق بجنبك","لف ساعدك للداخل ناحية بطنك بدون تحريك الكوع","ارجع ببطء ولا تسحب الباند بسرعة"],["Stand with a band anchored at your side, elbow bent 90 degrees against your ribs.","Rotate your forearm inward across your stomach without moving the elbow.","Return slowly; don't snap the band back."]],"Inverted_Row_with_Straps":[["اتمدد تحت الأحزمة وامسك المقبضين ودراعك مفرودة وجسمك مستقيم","اسحب صدرك لفوق ناحية المقبضين وضم لوح الكتف","انزل ببطء بتحكم وجسمك ثابت"],["Lie under the straps, gripping the handles, arms extended, body straight.","Pull your chest up to the handles, squeezing your shoulder blades.","Lower slowly under control; keep your body rigid."]],"Iron_Crosses_stretch":[["اتمدد على ضهرك ودراعك مفتوحة بالجنب","ارفع رجل وعدّيها للجنب المعاكس مع ثبات الكتف على الأرض","ثبّت 20-30 ثانية وبدل الرجل"],["Lie on your back with arms out to the sides.","Lift one leg and cross it to the opposite side, keeping shoulders down.","Hold 20-30 seconds, then switch legs."]],"Iron_Cross":[["قف وامسك دامبلين خفيفين وإيدك مفرودة للجنب","ارفع الدراعين للجنب لحد مستوى الكتف بتحكم","انزل ببطء، واستعمل وزن خفيف لحماية الكتف"],["Stand holding light dumbbells with arms extended to the sides.","Raise your arms out to shoulder height with control.","Lower slowly; use light weight to protect your shoulders."]],"Isometric_Chest_Squeezes":[["قف أو اجلس وضم كفوفك قدام صدرك","اضغط كفوفك على بعض بأقصى قوة","ثبّت 10-15 ثانية ثم ارتاح، وتنفس طبيعي"],["Stand or sit and press your palms together in front of your chest.","Squeeze your hands together as hard as you can.","Hold 10-15 seconds, then relax; keep breathing."]],"Isometric_Neck_Exercise_-_Front_And_Back":[["اجلس معتدل وحط كفك على جبهتك","اضغط راسك على كفك بدون حركة، ثم كرر مع الإيد ورا راسك","ثبّت 10 ثواني لكل ناحية بقوة خفيفة ومن غير ألم"],["Sit tall and place your palm on your forehead.","Press your head into your hand without moving; repeat with hands behind your head.","Hold 10 seconds each way with gentle force; stop if painful."]],"Isometric_Neck_Exercise_-_Sides":[["اقعد أو قف معتدل وحط كف إيدك على جنب راسك.","اضغط براسك على إيدك من غير حركة 5-10 ثواني.","سيب الضغط براحة وبدّل الجنب، وبلاش شد عنيف."],["Sit or stand tall with your palm on the side of your head.","Press your head into your hand without moving for 5-10 seconds.","Release slowly and switch sides; never push jerkily."]],"Isometric_Wipers":[["اتمدد على ضهرك وافرد دراعاتك لفوق صدرك وكفوفك ملزوقة.","اضغط كفوفك على بعض بقوة وحرّك دراعاتك يمين وشمال بقوس صغير.","ارجع للنص براحة وخلي ضهرك لازق في الأرض."],["Lie on your back, arms straight above your chest, palms together.","Squeeze your palms hard and sweep your arms side to side in a small arc.","Return to center slowly and keep your back flat on the floor."]],"JM_Press":[["اتمدد على بنش مسطح وامسك البار بقبضة ضيقة فوق صدرك.","نزّل البار ناحية الجبهة أو الدقن بثني الكوعين، والكوع ثابت.","ادفع البار لفوق بقوة الترايسبس من غير ما تقفل الكوع بعنف."],["Lie on a flat bench holding the bar above your chest, close grip.","Lower the bar toward your forehead or chin, elbows fixed in place.","Press up with your triceps without snapping the elbows locked."]],"Janda_Sit-Up":[["اقعد على الأرض ورجليك مفرودة ودراعاتك قدامك.","انزل لورا شوية وبعدين قوم ببطء بشد البطن والجلوتس.","خلي ضهرك مفرود وبلاش تشد رقبتك."],["Sit on the floor with legs extended and arms forward.","Lean back slightly, then sit up slowly, bracing abs and glutes.","Keep your back neutral and do not yank on your neck."]],"Jefferson_Squats":[["قف فوق البار ورجل قدام ورجل ورا، وامسكه بإيد قدام وإيد ورا.","قف بدفع الرجلين والورك وضهرك مفرود.","نزّل البار براحة للأرض ومتدورش ضهرك أبداً."],["Straddle the bar, one foot forward and one back, hands gripping it between your legs.","Stand up by driving through your hips and legs, back flat.","Lower the bar slowly to the floor and never round your back."]],"Jerk_Balance":[["قف والبار على كتفك أو فوق راسك وقدميك في عرض الكتف.","وزّع الوزن على النص وثبّت جسمك ببطن مشدودة.","ثبّت ثواني وارجع بتحكم وعينك لقدام."],["Stand with the bar racked or overhead, feet shoulder-width apart.","Spread your weight evenly and brace your core to stay balanced.","Hold briefly, then return under control, eyes forward."]],"Jerk_Dip_Squat":[["قف والبار على كتفك وقدميك في عرض الكتف وبطنك مشدودة.","انزل غطسة قصيرة بثني الركبتين وجذعك عمودي.","اطلع بسرعة بقوة الرجلين وركبتك ماشية مع صوابعك."],["Stand with the bar racked on your shoulders, feet shoulder-width, core tight.","Dip a short distance by bending your knees, torso upright.","Drive up fast through your legs, knees tracking over toes."]],"Jogging_Treadmill":[["اظبط السير على سرعة خفيفة ووقف على جناب الحزام.","ابدأ جري بخطوات منتظمة ودراعاتك مرتخية.","قلل السرعة تدريجي في الآخر قبل ما تنزل، وامسك الدرابزين لو احتجت."],["Set the treadmill to an easy speed and straddle the belt.","Jog with steady strides and relaxed, swinging arms.","Slow down gradually at the end before stepping off."]],"Keg_Load":[["قف قدام البرميل ورجليك واسعة وانحني من الورك وضهرك مفرود.","امسك البرميل واحضنه وارفعه بدفع الرجلين والورك.","ارفعه لكتفك أو للمنصة بتحكم وضهرك مفرود طول الوقت."],["Stand over the keg, feet wide, hinging with a flat back.","Hug the keg and lift it by driving through your legs and hips.","Load it onto your shoulder or platform under control, back flat."]],"Kettlebell_Arnold_Press":[["امسك الكيتل بيل عند الصدر وكفك ناحيتك وكوعك لتحت.","لف كفك لبرة وانت بتدفع الكيتل بيل فوق راسك.","انزل بنفس الحركة بالعكس ببطء وكتفك بعيد عن ودنك."],["Hold the kettlebell at chest height, palm facing you, elbow down.","Rotate your palm outward as you press the bell overhead.","Reverse the motion slowly, keeping your shoulder away from your ear."]],"Kettlebell_Dead_Clean":[["قف والكيتل بيل على الأرض بين رجليك وانحني بضهر مفرود.","اسحبه لفوق بدفع الورك وخليه يستقر عند الصدر.","نزّله للأرض بتحكم وضهرك مفرود."],["Stand over the kettlebell on the floor and hinge with a flat back.","Drive your hips and pull the bell up into the rack at your chest.","Lower it back to the floor under control, back flat."]],"Kettlebell_Figure_8":[["قف برجلين واسعين وانحني شوية وامسك الكيتل بيل بإيد.","لف الكيتل بيل بين رجليك وحوالين رجلك على شكل رقم 8.","بدّل الإيد بسلاسة وضهرك مفرود وركبتك لينة."],["Stand with feet wide, knees slightly bent, kettlebell in one hand.","Pass the bell around and between your legs in a figure-8 pattern.","Switch hands smoothly with a flat back and soft knees."]],"Kettlebell_Halo_With_Overhead_Extension":[["امسك الكيتل بيل من أطرافه عند الصدر وارفعه فوق راسك.","نزّله ورا راسك بثني الكوعين وبعدين افرد لفوق.","ارجع للبداية ببطء وشد بطنك عشان ضهرك ميتقوسش."],["Hold the kettlebell by the horns at chest, then press it overhead.","Lower it behind your head by bending the elbows, then extend back up.","Return to start slowly and brace your abs so your back doesn't arch."]],"Kettlebell_Halo":[["امسك الكيتل بيل مقلوب من أطرافه عند الصدر وكوعك لتحت.","لفه حوالين راسك في دايرة كبيرة وراسك مستقيمة.","اعكس الاتجاه وكتافك لتحت ووسطك مشدود."],["Hold the kettlebell upside down by the horns at chest, elbows down.","Circle it around your head, keeping your head upright.","Reverse direction, with shoulders down and core tight."]],"Kettlebell_Hang_Clean":[["قف والكيتل بيل بين رجليك وانحني بضهر مفرود.","اسحب الكيتل بيل لفوق بدفع الورك وخليه يلف لوضع الراك عند الكتف.","نزّله بتحكم للوضع المعلق وضهرك مفرود."],["Stand over the kettlebell and hinge with a flat back.","Swing it up with a hip drive and flip it into the rack at your shoulder.","Lower it back to the hang position under control."]],"Kettlebell_One-Legged_Deadlift":[["قف على رجل واحدة وامسك الكيتل بيل بإيد.","انحني من الورك والرجل التانية تتمدد ورا لحد ما ضهرك يبقى أفقي.","ارجع واقف بقوة الجلوتس وضهرك مفرود طول الوقت."],["Stand on one leg holding a kettlebell in one hand.","Hinge at the hips as the other leg extends behind you.","Return upright by squeezing your glutes, back flat throughout."]],"Kettlebell_Overhead_Triceps_Extension":[["امسك الكيتل بيل بإيدين وارفعه فوق راسك.","نزّله ورا راسك بثني الكوعين وهما قريبين من راسك.","افرد دراعاتك لفوق بقوة الترايسبس وشد بطنك."],["Hold the kettlebell with both hands and raise it overhead.","Lower it behind your head by bending your elbows, keeping them in.","Extend your arms up with your triceps and brace your abs."]],"Kettlebell_Pass_Between_The_Legs":[["قف برجلين واسعين وانحني شوية وامسك الكيتل بيل.","مرر الكيتل بيل بين رجليك من إيد لإيد.","اتحرك بسلاسة وضهرك مفرود وركبتك لينة."],["Stand with feet wide, knees slightly bent, holding a kettlebell.","Pass the bell between your legs from one hand to the other.","Move smoothly with a flat back and soft knees."]],"Kettlebell_Pirate_Ships":[["قف وامسك الكيتل بيل بإيد وذراعك لتحت.","لف دراعك في دايرة كبيرة قدام جسمك زي دفة المركب.","اعكس الاتجاه وكتفك لتحت ومرتخي، ومتكملش لو حسيت بألم."],["Stand holding a kettlebell with your arm hanging down.","Circle your arm in a large arc in front, like a ship's wheel.","Reverse direction, keeping your shoulder down; stop if it hurts."]],"Kettlebell_Pistol_Squat":[["قف وامسك الكيتل بيل عند الصدر ورجل مفرودة قدامك.","انزل ببطء على الرجل الواقفة والرجل التانية قدامك مفرودة.","اطلع بقوة الرجل وركبتك ماشية مع صوابعك، وحافظ على توازنك."],["Stand holding a kettlebell at chest, one leg extended in front.","Lower slowly on the standing leg, other leg held out.","Drive back up, knee tracking over toes, staying balanced."]],"Kettlebell_Seated_Press":[["اقعد على بنش وضهرك مسنود وامسك الكيتل بيل عند الكتف.","ادفعه لفوق راسك لحد ما دراعك يتفرد.","نزّله ببطء لمستوى الكتف وضهرك مسنود ومش مقوّس."],["Sit on a bench, back supported, bell racked at your shoulder.","Press it overhead until your arm is extended.","Lower slowly to shoulder height without arching your back."]],"Kettlebell_Seesaw_Press":[["امسك كيتل بيل في كل إيد عند الكتف.","ادفع واحدة لفوق وانزل التانية في نفس الوقت.","بدّل بتحكم وبطنك مشدودة وضهرك مفرود."],["Hold a kettlebell in each hand at shoulder height.","Press one up while lowering the other at the same time.","Alternate under control with a tight core and neutral back."]],"Kettlebell_Sumo_High_Pull":[["قف برجلين واسعين والكيتل بيل بين رجليك وانحني بضهر مفرود.","قف بقوة وسحب الكيتل بيل لعند الدقن بكوعين عاليين.","نزّله ببطء بعد الشد وضهرك مفرود."],["Stand wide over the kettlebell and hinge with a flat back.","Stand up fast and pull the bell to chin height, elbows high.","Lower slowly with control, keeping your back flat."]],"Kettlebell_Thruster":[["امسك الكيتل بيل عند الصدر وقدميك في عرض الكتف.","انزل سكوات كامل والكيتل بيل لسه عند صدرك.","اطلع بقوة وادفع الكيتل بيل فوق راسك في نفس الحركة."],["Hold the kettlebell at chest, feet shoulder-width.","Squat down fully with the bell staying at chest.","Drive up and press the bell overhead in one motion."]],"Kettlebell_Turkish_Get-Up_Lunge_style":[["اتمدد على الأرض وامسك الكيتل بيل مفرود فوق صدرك وعينك عليه.","قوم على كوعك وبعدين على إيدك، وارجع رجلك لوضع لانجز وقف.","ارجع بنفس الخطوات بالعكس ببطء والكيتل بيل مثبت فوقك."],["Lie on the floor with a kettlebell locked out above your chest, eyes on it.","Rise via elbow and hand, then sweep a leg back into a lunge and stand.","Reverse the steps slowly, keeping the weight locked overhead."]],"Kettlebell_Windmill":[["قف ورجليك أوسع من الكتف والكيتل بيل مفرود فوق راسك.","انحني من الورك للجنب وإيدك الحرة بتنزل على رجلك.","قوم ببطء وعينك على الكيتل بيل وضهرك مفرود."],["Stand with feet wide and a kettlebell locked out overhead.","Hinge sideways at the hip, sliding your free hand down your leg.","Return upright slowly, eyes on the bell, back flat."]],"Kipping_Muscle_Up":[["امسك بار العقلة بقبضة واسعة وعلّق جسمك.","اعمل ترجيحة واسحب نفسك لفوق وبعدين ادفع فوق البار.","نزل ببطء لوضع التعليق وتحكم في الترجيحة."],["Hang from the bar with a wide grip.","Swing your body, pull up, then press yourself above the bar.","Lower slowly back to the hang under control."]],"Knee_Across_The_Body":[["اتمدد على ضهرك وارفع ركبة واحدة لصدرك.","اسحب الركبة ناحية كتفك المعاكس بإيدك.","ثبّت 20-30 ثانية وبدّل الرجل."],["Lie on your back and bring one knee up to your chest.","Pull that knee across toward the opposite shoulder with your hands.","Hold 20-30 seconds and switch legs."]],"Knee_Circles":[["قف على رجل واحدة وارفع الركبة التانية قدامك.","لف الركبة في دواير صغيرة وبطيئة.","اعكس الاتجاه وبدّل الرجل، وكل الحركة سهلة من غير ألم."],["Stand on one leg and lift the other knee in front.","Rotate the knee in slow, small circles.","Reverse direction and switch legs; keep it gentle and pain-free."]],"Knee_Tuck_Jump":[["قف ورجليك في عرض الكتف وانزل شوية.","اقفز لفوق بقوة وسحب ركبتك لصدرك.","انزل بخفة على مشط القدم وركبتك لينة."],["Stand feet shoulder-width and dip slightly.","Jump up explosively, pulling your knees toward your chest.","Land softly on the balls of your feet with soft knees."]],"Kneeling_Arm_Drill":[["اقعد على ركبتك وضهرك مفرود ودراعاتك مثنية 90 درجة.","حرّك دراعاتك بالتبادل لقدام ولورا زي الجري بسرعة.","خلي جذعك ثابت وكتافك مرتخية."],["Kneel upright with a tall spine and elbows bent 90 degrees.","Swing your arms alternately forward and back as in sprinting.","Keep your torso still and shoulders relaxed."]],"Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists":[["اقعد على ركبتك قدام الكابل وامسك الحبل عند راسك.","اعمل كرانش لتحت وأنت بتلف جسمك ناحية ركبة.","ارجع للبداية وبدّل الجنب، والحركة من البطن مش الدراعين."],["Kneel facing the cable, holding the rope at your head.","Crunch down while twisting your torso toward one knee.","Return and alternate sides, moving from your abs, not your arms."]],"Kneeling_Cable_Triceps_Extension":[["اقعد على ركبتك قدام الكابل وامسك الحبل عند راسك وكوعك لقدام.","افرد دراعك لتحت بقوة الترايسبس والكوع ثابت.","ارجع ببطء لحد ما تحس بشد خفيف وضهرك مفرود."],["Kneel facing the cable, rope at your head, elbows in.","Extend your arms down using your triceps, elbows fixed.","Return slowly to a light stretch, keeping your back flat."]],"Kneeling_Forearm_Stretch":[["اقعد على ركبتك وحط كفك على الأرض وصوابعك ناحيتك.","ارجع بجسمك لورا براحة لحد ما تحس بشد في الساعد.","ثبّت 20-30 ثانية وبدّل الإيد."],["Kneel and place your palm on the floor, fingers pointing back toward you.","Sit back gently until you feel a stretch in your forearm.","Hold 20-30 seconds and switch hands."]],"Kneeling_High_Pulley_Row":[["اقعد على ركبتك قدام البكرة العالية وامسك البار بإيدين.","اسحب البار لصدرك وشد كتافك لورا.","ارجع ببطء وضهرك مفرود وبلاش ترجحة."],["Kneel facing the high pulley and grip the bar with both hands.","Pull the bar to your chest, squeezing your shoulder blades back.","Return slowly with a straight back, no swinging."]],"Kneeling_Hip_Flexor":[["اقعد على ركبة واحدة والرجل التانية قدامك بزاوية 90 درجة.","ادفع حوضك لقدام لحد ما تحس بشد في مقدمة الورك.","ثبّت 20-30 ثانية وبدّل الرجل وضهرك مفرود."],["Kneel on one knee with the other foot forward at 90 degrees.","Push your hips forward until you feel a stretch at the front of the hip.","Hold 20-30 seconds and switch legs, back tall."]],"Kneeling_Jump_Squat":[["قف والبار على كتفك وقدميك في عرض الكتف.","انزل سكوات بسرعة وبعدين اقفز لفوق بقوة.","انزل بخفة وركبتك لينة وضهرك مفرود."],["Stand with the bar on your shoulders, feet shoulder-width.","Squat down fast, then jump up explosively.","Land softly with soft knees and a straight back."]],"Kneeling_Single-Arm_High_Pulley_Row":[["اقعد على ركبتك قدام البكرة العالية وامسك المقبض بإيد واحدة.","اسحب المقبض لصدرك وشد لوح كتفك لورا.","ارجع ببطء من غير لف جسمك، وبدّل الإيد."],["Kneel facing the high pulley holding the handle in one hand.","Pull the handle toward your chest, squeezing the shoulder blade back.","Return slowly without twisting your torso, then switch arms."]],"Kneeling_Squat":[["اقعد على ركبتك والبار على كتفك وضهرك مفرود.","ارجع بحوضك لورا ناحية كعبك بتحكم.","قوم لفوق بقوة الورك من غير ما تدور ضهرك."],["Kneel upright with the bar across your shoulders, back straight.","Sit your hips back toward your heels under control.","Drive back up with your hips without rounding your back."]],"Landmine_180s":[["امسك طرف البار بإيدين قدام صدرك ورجليك واسعة.","لف البار في قوس ناحية الجنب بتشغيل الجذع والورك.","ارجع للنص وبدّل الجنب وضهرك مفرود."],["Hold the bar end at chest with both hands, stance wide.","Rotate the bar in an arc to one side, turning your torso and hips.","Return to center and alternate sides, back straight."]],"Landmine_Linear_Jammer":[["امسك طرف البار بإيد واحدة عند الكتف ورجليك ثابتة.","ادفع البار لقدام ولفوق في خط مستقيم.","ارجع ببطء وجسمك ثابت ومش مقوّس."],["Hold the bar end at your shoulder with one hand, feet planted.","Punch the bar forward and up in a straight line.","Return slowly, body stable, without arching your back."]],"Lateral_Bound":[["قف على رجل واحدة وانزل شوية.","اقفز جانبياً بقوة للرجل التانية.","انزل بخفة وثبّت قبل القفزة اللي بعدها."],["Stand on one leg with a slight dip.","Bound sideways explosively onto the other leg.","Land softly and stabilize before the next bound."]],"Lateral_Box_Jump":[["قف جنب الصندوق وقدميك في عرض الكتف.","اقفز جانبياً فوق الصندوق بقوة.","انزل منه براحة أو بخفة وركبتك لينة."],["Stand beside the box with feet shoulder-width.","Jump sideways up onto the box with power.","Step down or land softly with soft knees."]],"Lateral_Cone_Hops":[["قف جنب القمع وركبتك مثنية شوية.","اقفز جانبياً فوق القمع وارجع.","انزل بخفة وكرر بسرعة وركبتك مع صوابعك."],["Stand beside a cone with slightly bent knees.","Hop sideways over the cone and back.","Land softly, knees over toes, and repeat quickly."]],"Lateral_Raise_-_With_Bands":[["اربط الباند تحت رجلك وامسك طرفه بإيدك.","ارفع دراعك جانبياً لحد مستوى الكتف.","نزّل ببطء وكوعك مثني شوية وكتفك لتحت."],["Anchor the band under your foot and hold the end.","Raise your arm out to the side to shoulder height.","Lower slowly with a slight elbow bend and shoulder down."]],"Latissimus_Dorsi-SMR":[["اتمدد على جنبك والفوم رولر تحت إبطك.","ادحرج جسمك ببطء من الإبط لحد منتصف الضهر.","وقف على الأماكن المشدودة 20-30 ثانية وخد نفس."],["Lie on your side with the foam roller under your armpit.","Roll slowly from your armpit toward mid back.","Pause on tight spots for 20-30 seconds and breathe."]],"Leg-Over_Floor_Press":[["اتمدد على ضهرك والكيتل بيل في إيد ورجل مرفوعة أو متقاطعة.","ادفع الكيتل بيل لفوق صدرك بالإيد.","نزّل ببطء لحد ما كوعك يلمس الأرض."],["Lie on your back holding a kettlebell, one leg raised or crossed over.","Press the bell straight up above your chest.","Lower slowly until your elbow touches the floor."]],"Leg-Up_Hamstring_Stretch":[["اتمدد على ضهرك وارفع رجل مفرودة لفوق.","امسك رجلك بإيدك أو بحبل وقرّبها منك براحة.","ثبّت 20-30 ثانية وبدّل الرجل."],["Lie on your back and raise one straight leg.","Pull the leg toward you with your hands or a strap.","Hold 20-30 seconds and switch legs."]],"Leg_Lift":[["اتمدد على ضهرك أو قف وشد بطنك.","ارفع رجل لفوق بتحكم وركبتك مفرودة.","نزّل ببطء من غير ترجحة."],["Lie on your back or stand and brace your core.","Lift one leg up with control, knee straight.","Lower slowly without swinging."]],"Leg_Pull-In":[["اتمدد على ضهرك وإيدك جنبك ورجليك مفرودة.","اسحب ركبتك لصدرك براحة وارفع الورك شوية.","ارجع للبداية بتحكم وضهرك لازق في الأرض."],["Lie on your back, arms at your sides, legs extended.","Pull your knees in toward your chest slowly.","Return to start under control, lower back flat on the floor."]],"Leverage_Chest_Press":[["اقعد على الجهاز وضهرك مسنود وامسك المقابض.","ادفع المقابض لقدام لحد ما دراعك يتفرد.","ارجع ببطء من غير ما تقفل كوعك بعنف."],["Sit on the machine, back supported, and grip the handles.","Press the handles forward until your arms are extended.","Return slowly without snapping your elbows locked."]],"Leverage_Deadlift":[["قف على الجهاز وامسك المقابض وضهرك مفرود.","ادفع بالرجلين وافرد الركبة والورك لحد ما تقف.","نزّل ببطء وضهرك مفرود طول الوقت."],["Stand on the machine, back flat, gripping the handles.","Drive through your legs, extending knees and hips to stand tall.","Lower slowly with a flat back throughout."]],"Leverage_Decline_Chest_Press":[["اقعد على الجهاز وضهرك مسنود وامسك المقابض.","ادفع المقابض لتحت وقدام بقوة الصدر.","ارجع ببطء وكتافك لورا."],["Sit with your back supported and grip the decline handles.","Press the handles down and forward using your chest.","Return slowly with your shoulders pulled back."]],"Leverage_Iso_Row":[["اقعد على الجهاز وصدرك مسنود وامسك المقابض.","اسحب المقابض ناحيتك وشد لوح كتفك.","ارجع ببطء وجسمك ثابت."],["Sit with your chest supported and grip the handles.","Row the handles toward you, squeezing your shoulder blades.","Return slowly with your torso steady."]],"Leverage_Shoulder_Press":[["اقعد على الجهاز وضهرك مسنود وامسك المقابض عند الكتف.","ادفع المقابض لفوق لحد ما دراعك يتفرد.","نزّل ببطء من غير ما تقفل كوعك بعنف."],["Sit on the machine, back supported, handles at shoulder height.","Press overhead until your arms are extended.","Lower slowly without locking your elbows hard."]],"Leverage_Shrug":[["قف جوه الجهاز وامسك المقابض وكتافك مرتخية.","ارفع كتافك لفوق ناحية ودانك.","نزّل ببطء وصدرك مرفوع."],["Stand in the machine gripping the handles, shoulders relaxed.","Shrug your shoulders straight up toward your ears.","Lower slowly, keeping your chest tall."]],"Linear_3-Part_Start_Technique":[["قف بوقفة بداية ورجل قدام ورجل ورا وجسمك مايل لقدام.","ادفع الأرض بالرجل الخلفية وانطلق بخطوة قوية.","زوّد الخطوات تدريجي وارفع جسمك لحد ما تعتدل."],["Take a staggered start stance, one foot forward, body leaning forward.","Push off the back foot and drive out with a powerful step.","Lengthen your strides gradually as you rise to upright."]],"Linear_Acceleration_Wall_Drill":[["قف قدام حيطة وحط إيدك عليها وجسمك مايل بخط مستقيم.","ارفع ركبة واحدة بسرعة وادفع الأرض بالرجل التانية.","بدّل الرجلين بسرعة وجسمك مستقيم."],["Stand facing a wall, hands on it, body leaning in a straight line.","Drive one knee up fast while pushing the floor with the other leg.","Alternate legs quickly, keeping a straight body line."]],"Linear_Depth_Jump":[["قف على حافة صندوق وركبتك لينة.","انزل من الصندوق وأول ما تلمس الأرض اقفز لفوق بأقصى قوة.","انزل بخفة وركبتك مثنية."],["Stand on the edge of a box with soft knees.","Step off, land on both feet, and immediately jump up with maximum effort.","Land softly with bent knees."]],"Log_Lift":[["قف فوق جذع الشجرة وانحني بضهر مفرود.","ارفعه لوضع الكتف بدفع الرجلين والورك.","ادفعه فوق راسك بتحكم وضهرك مفرود."],["Stand over the log and hinge with a flat back.","Lift it to your shoulders by driving through legs and hips.","Press it overhead under control with a straight back."]],"London_Bridges":[["اتمدد تحت بار ثابت وامسكه بقبضة أعرض من الكتف وجسمك مفرود.","اسحب صدرك ناحية البار وشد لوح كتفك.","نزّل ببطء وجسمك في خط مستقيم."],["Lie under a fixed bar and grip it wider than shoulders, body straight.","Pull your chest toward the bar, squeezing your shoulder blades.","Lower slowly, keeping your body in a straight line."]],"Looking_At_Ceiling":[["قف أو اقعد معتدل وعينك لقدام.","ارفع راسك لورا ببطء لحد ما تحس بشد خفيف.","ثبّت 20-30 ثانية وارجع براحة من غير ألم."],["Stand or sit tall, looking straight ahead.","Tilt your head back slowly until you feel a light stretch.","Hold 20-30 seconds and return slowly, pain-free."]],"Low_Cable_Crossover":[["قف بين الكابلات وامسك المقبضين من تحت وركبتك لينة.","اسحب المقبضين لقدام ولفوق لحد ما يتقابلوا قدام صدرك.","ارجع ببطء وكوعك مثني شوية."],["Stand between the cables and grab the low handles, knees soft.","Pull the handles forward and up until they meet in front of your chest.","Return slowly with a slight bend in your elbows."]],"Low_Cable_Triceps_Extension":[["قف قدام الكابل السفلي وامسك الحبل وكوعك جنبك.","افرد دراعك بقوة الترايسبس.","ارجع ببطء وكوعك ثابت."],["Face the low cable holding the attachment, elbows at your sides.","Extend your arms using your triceps.","Return slowly with your elbows steady."]],"Low_Pulley_Row_To_Neck":[["اقعد قدام الكابل السفلي وامسك المقبض بقبضة واسعة.","اسحب المقبض لرقبتك وكوعك لبرة.","ارجع ببطء وضهرك مفرود."],["Sit at the low pulley and grip the handle with a wide grip.","Pull the handle to your neck, elbows flared out.","Return slowly with a straight back."]],"Lower_Back-SMR":[["اتمدد على ضهرك والفوم رولر تحت أسفل ضهرك وركبتك مثنية.","ادحرج جسمك ببطء لفوق ولتحت.","وقف على الأماكن المشدودة 20-30 ثانية وبلاش ضغط مباشر على العمود الفقري."],["Lie on your back with the foam roller under your lower back, knees bent.","Roll slowly up and down.","Pause on tight spots for 20-30 seconds; avoid pressing directly on the spine."]],"Lower_Back_Curl":[["اتمدد على ضهرك وركبتك مثنية.","اسحب ركبتك لصدرك وارفع راسك شوية.","ثبّت 20-30 ثانية وبعدين ارجع براحة."],["Lie on your back with knees bent.","Pull your knees to your chest and lift your head slightly.","Hold 20-30 seconds and return slowly."]],"Lunge_Pass_Through":[["اعمل خطوة لانجز وامسك كيتل بيل بإيد.","مرر الكيتل بيل تحت رجلك الأمامية لإيدك التانية.","انزل وقوم بتحكم وضهرك مفرود."],["Step into a lunge holding a kettlebell.","Pass the bell under your front leg to the other hand.","Lower and rise with control, back straight."]],"Lunge_Sprint":[["قف في وضع لانجز على الجهاز وامسك المقابض.","اجري بسرعة وبدّل الرجلين.","قلل السرعة بتدريج وارجع للوضع الأول بتحكم."],["Set up in a lunge stance on the machine and grip the handles.","Sprint quickly, alternating legs.","Slow down gradually and return to the start under control."]],"Lying_Bent_Leg_Groin":[["اتمدد على ضهرك وركبة مثنية.","افتح ركبتك للجنب ببطء.","ثبّت 20-30 ثانية وبدّل الرجل."],["Lie on your back with a knee bent.","Let the knee fall open to the side slowly.","Hold 20-30 seconds and switch legs."]],"Lying_Cable_Curl":[["اتمدد على ضهرك وامسك مقبض الكابل السفلي.","اثني الكوع واسحب المقبض ناحية كتفك.","نزّل ببطء وكوعك ثابت."],["Lie on your back and grip the low cable handle.","Curl the handle toward your shoulders, bending your elbows.","Lower slowly, keeping your elbows fixed."]],"Lying_Cambered_Barbell_Row":[["اتمدد على بطنك على بنش عالي وامسك البار.","اسحب البار لصدرك وشد لوح كتفك.","نزّل ببطء وراسك لتحت."],["Lie face down on a high bench and grip the bar.","Pull the bar to your chest, squeezing your back.","Lower slowly with your head down."]],"Lying_Close-Grip_Bar_Curl_On_High_Pulley":[["اتمدد على ضهرك وامسك البار بقبضة ضيقة من البكرة العالية.","اثني الكوع واسحب البار ناحية كتفك.","نزّل ببطء وكوعك ثابت."],["Lie on your back and grip the bar from the high pulley, close grip.","Curl the bar toward your shoulders with elbows fixed.","Lower slowly, keeping elbows still."]],"Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head":[["اتمدد على بنش وامسك البار بقبضة ضيقة فوق صدرك.","نزّل البار ورا راسك بثني الكوع ببطء.","افرد دراعك لفوق وكوعك ثابت."],["Lie on a bench, bar held above your chest, close grip.","Lower the bar behind your head by bending your elbows slowly.","Extend your arms back up, elbows fixed."]],"Lying_Close-Grip_Barbell_Triceps_Press_To_Chin":[["اتمدد على بنش وامسك البار بقبضة ضيقة فوق صدرك.","نزّل البار ناحية الدقن بثني الكوع.","ادفع البار لفوق بقوة الترايسبس."],["Lie on a bench, bar above your chest, close grip.","Lower the bar toward your chin by bending your elbows.","Press back up using your triceps."]],"Lying_Crossover":[["اتمدد على ضهرك ودراعاتك مفرودة جنبك.","اسحب دراع واحد على صدرك بإيدك التانية.","ثبّت 20-30 ثانية وبدّل الدراع."],["Lie on your back with arms out to your sides.","Cross one arm over your chest, pulling it with the other hand.","Hold 20-30 seconds and switch arms."]],"Lying_Face_Down_Plate_Neck_Resistance":[["اتمدد على بطنك على بنش وراسك برا البنش وطبق على ضهر راسك.","ارفع راسك لفوق ببطء ضد وزن الطبق.","نزّل ببطء وبلاش حركة عنيفة في رقبتك."],["Lie face down on a bench, head off the end, plate on the back of your head.","Lift your head slowly against the plate's resistance.","Lower slowly without jerking your neck."]],"Lying_Face_Up_Plate_Neck_Resistance":[["اتمدد على ضهرك على بنش وطبق خفيف على جبهتك.","ارفع راسك لقدام ببطء ضد وزن الطبق.","نزّل ببطء وخفف الوزن لو حسيت بألم."],["Lie on your back on a bench with a light plate on your forehead.","Lift your head slowly against the plate's resistance.","Lower slowly and reduce weight if you feel pain."]],"Lying_Glute":[["اتمدد على ضهرك وركبتك مثنية.","حط كاحل رجل على ركبة التانية واسحب الرجلين لصدرك.","ثبّت 20-30 ثانية وبدّل الرجل."],["Lie on your back with knees bent.","Cross one ankle over the opposite thigh and pull both legs toward your chest.","Hold 20-30 seconds and switch legs."]],"Lying_Hamstring":[["اتمدد على ضهرك وارفع رجل مفرودة.","امسك رجلك بإيدك أو بحبل وقرّبها منك.","ثبّت 20-30 ثانية وبدّل الرجل."],["Lie on your back and raise one straight leg.","Pull it toward you with your hands or a strap.","Hold 20-30 seconds and switch legs."]],"Lying_High_Bench_Barbell_Curl":[["اتمدد على بنش عالي ووشك لتحت وامسك البار.","اثني الكوع واسحب البار ناحية كتفك.","نزّل ببطء وكوعك ثابت."],["Lie face down on a high bench holding the bar.","Curl the bar toward your shoulders by bending your elbows.","Lower slowly with your elbows fixed."]],"Lying_Machine_Squat":[["اتمدد على الجهاز ورجليك على المنصة.","ادفع المنصة بالرجلين وافرد الركبة.","ارجع ببطء من غير ما تقفل ركبتك بعنف."],["Lie back in the machine with feet on the platform.","Press the platform away by extending your knees.","Return slowly without locking your knees hard."]],"Lying_One-Arm_Lateral_Raise":[["اتمدد على جنبك وامسك دامبل في الإيد اللي فوق.","ارفع دراعك لفوق لحد مستوى الكتف.","نزّل ببطء وكوعك مثني شوية."],["Lie on your side holding a dumbbell in your top hand.","Raise your arm up to shoulder height.","Lower slowly with a slight elbow bend."]],"Lying_Prone_Quadriceps":[["اتمدد على بطنك وارفع رجل مثنية.","اسحب كعبك ناحية الجلوتس بإيدك.","ثبّت 20-30 ثانية وبدّل الرجل."],["Lie face down and bend one knee.","Pull your heel toward your glutes with your hand.","Hold 20-30 seconds and switch legs."]],"Lying_Rear_Delt_Raise":[["اتمدد على بطنك على بنش مائل وامسك الدامبلز.","ارفع دراعاتك للجنب وكوعك مثني شوية.","نزّل ببطء وكتافك لتحت."],["Lie face down on an incline bench holding dumbbells.","Raise your arms out to the sides, elbows slightly bent.","Lower slowly with your shoulders down."]],"Lying_Supine_Dumbbell_Curl":[["اتمدد على ضهرك على بنش وامسك الدامبلز.","اثني الكوع وارفع الدامبل ناحية كتفك وكفك لفوق.","نزّل ببطء وكوعك ثابت."],["Lie on your back on a bench holding dumbbells, palms up.","Curl the dumbbells toward your shoulders by bending elbows.","Lower slowly with your elbows steady."]],"Lying_T-Bar_Row":[["اتمدد على بطنك على الجهاز وامسك المقابض.","اسحب المقابض ناحية صدرك.","نزّل ببطء وصدرك مسنود."],["Lie face down on the machine and grip the handles.","Row the handles toward your chest.","Lower slowly with your chest supported."]],"Lying_Triceps_Press":[["اتمدد على بنش وامسك البار فوق صدرك.","اثني الكوع ونزّل البار ناحية جبهتك.","ادفع البار لفوق بقوة الترايسبس."],["Lie on a bench holding the bar above your chest.","Bend your elbows and lower the bar toward your forehead.","Press back up with your triceps."]],"Machine_Bicep_Curl":[["اقعد على الجهاز وكوعك على الوسادة وامسك المقابض.","اثني الكوع واسحب المقابض ناحية كتفك.","نزّل ببطء من غير ما تفرد كوعك بعنف."],["Sit on the machine with your elbows on the pad and grip the handles.","Curl the handles toward your shoulders.","Lower slowly without snapping elbows straight."]],"Machine_Preacher_Curls":[["اقعد على جهاز البريتشر وكوعك على الوسادة.","اثني الكوع واسحب المقابض لفوق.","نزّل ببطء من غير ما تفرد كوعك بعنف."],["Sit at the preacher machine with your elbows on the pad.","Curl the handles up toward your shoulders.","Lower slowly without snapping elbows straight."]],"Machine_Triceps_Extension":[["اقعد على الجهاز وامسك المقابض عند الصدر.","ادفع المقابض لتحت بقوة الترايسبس.","ارجع ببطء وكوعك ثابت."],["Sit on the machine and grip the handles near your chest.","Press the handles down using your triceps.","Return slowly with your elbows steady."]],"Medicine_Ball_Chest_Pass":[["قف قدام حيطة أو شريك وامسك الميديسن بول عند الصدر.","ادفع الكورة بقوة لقدام من صدرك.","امسكها لما ترجع وكرر بنفس الوضع."],["Stand facing a wall or partner, ball held at chest.","Push the ball forward forcefully from your chest.","Catch it on the return and repeat."]],"Medicine_Ball_Full_Twist":[["قف ورجليك واسعة وامسك الميديسن بول بإيدين.","لف جسمك في دايرة كاملة بالكورة.","اعكس الاتجاه وبطنك مشدودة وضهرك مفرود."],["Stand feet wide, holding the medicine ball with both hands.","Rotate your torso in a full circle with the ball.","Reverse direction with core tight and back straight."]],"Medicine_Ball_Scoop_Throw":[["قف ورجليك واسعة وانزل سكوات وامسك الميديسن بول.","ارفع الكورة بحركة سكوب لفوق ولقدام بقوة الرجلين.","رجع الكورة لما ترجع بتحكم وكرر."],["Stand feet wide, squat down, holding the medicine ball low.","Scoop it up and throw forward and upward using your legs.","Reset under control and repeat."]],"Middle_Back_Shrug":[["امسك دامبلز على جنبك وقف معتدل.","ارفع كتافك لفوق وشد لوح كتفك لورا.","نزّل ببطء من غير ما تلف كتافك."],["Hold dumbbells at your sides standing tall.","Shrug your shoulders up and squeeze your shoulder blades back.","Lower slowly without rolling your shoulders."]],"Middle_Back_Stretch":[["اقعد على ركبتك وكفوفك على الأرض.","ارجع بحوضك لورا ناحية كعبك وإيدك مفرودة قدامك.","ثبّت 20-30 ثانية وارجع براحة."],["Kneel on all fours.","Sit your hips back toward your heels, arms stretched forward.","Hold 20-30 seconds and return slowly."]],"Mixed_Grip_Chin":[["امسك بار العقلة بقبضة مختلطة، إيد من فوق وإيد من تحت.","اسحب نفسك لفوق لحد ما دقنك تعدي البار.","نزّل ببطء وبدّل القبضة في المجموعة اللي بعدها."],["Hang from the bar with one hand over, one hand under.","Pull up until your chin clears the bar.","Lower slowly and switch grips next set."]],"Monster_Walk":[["حط الباند حوالين رجليك وقف ورجليك واسعة وركبتك مثنية.","امشي بخطوات قطرية واسعة.","حافظ على شد الباند وضهرك مفرود."],["Place a band around your legs and stand with feet wide, knees bent.","Walk forward with wide diagonal steps.","Keep tension in the band and your back straight."]],"Moving_Claw_Series":[["قف معتدل وارفع ركبة واحدة قدامك.","اسحب القدم لتحت ولورا زي المخلب وانت بتتحرك لقدام.","بدّل الرجلين بإيقاع ثابت وجسمك معتدل."],["Stand tall and drive one knee up in front.","Claw the foot down and back under your hip while moving forward.","Alternate legs in a steady rhythm with an upright torso."]],"Muscle_Snatch":[["قف والبار على الأرض وإيدك بقبضة واسعة وضهرك مفرود.","اسحب البار لفوق راسك بحركة سريعة واحدة.","ثبّت البار فوق راسك ونزّله بتحكم."],["Stand over the bar with a wide grip and flat back.","Pull it overhead in one fast motion, keeping it close to your body.","Lock it out overhead and lower under control."]],"Muscle_Up":[["امسك بار العقلة أو الحلق بقبضة واسعة.","اسحب نفسك لفوق وادفع جسمك فوق البار.","نزّل ببطء وتحكم لحد التعليق."],["Hang from the bar or rings with a wide grip.","Pull up and press yourself above the bar.","Lower slowly under control to the hang."]],"Narrow_Stance_Hack_Squats":[["قف على جهاز الهاك سكوات ورجليك قريبة من بعض وضهرك مسنود.","انزل بحوضك بثني الركبتين.","ادفع لفوق ببطء من غير قفل الركبة."],["Stand on the hack squat machine, feet close together, back against the pad.","Lower your hips by bending your knees.","Press up slowly without locking your knees."]],"Narrow_Stance_Leg_Press":[["اقعد على الجهاز ورجليك قريبة من بعض على المنصة.","نزّل المنصة ببطء وضهرك لازق في المسند.","ادفع بالرجلين من غير قفل الركبة."],["Sit on the leg press with feet close together on the platform.","Lower the platform slowly, back flat against the pad.","Press up without locking your knees."]],"Narrow_Stance_Squats":[["قف والبار على كتفك ورجليك قريبة من بعض.","انزل سكوات وضهرك مفرود.","اطلع بقوة وركبتك ماشية مع صوابعك."],["Stand with the bar on your shoulders, feet close together.","Squat down with a straight back.","Drive up with knees tracking over toes."]],"Neck-SMR":[["اتمدد على ضهرك والفوم رولر تحت رقبتك.","حرّك راسك ببطء يمين وشمال.","وقف على الأماكن المشدودة 20-30 ثانية وبلاش ضغط قوي."],["Lie on your back with the foam roller under your neck.","Roll your head slowly from side to side.","Pause on tight spots for 20-30 seconds; keep pressure gentle."]],"Neck_Press":[["اتمدد على بنش وامسك البار بقبضة أعرض من الكتف.","نزّل البار ببطء لحد الرقبة وكوعك لبرة.","ادفع البار لفوق بتحكم ومن غير قفل الكوع بعنف."],["Lie on a bench and grip the bar wider than shoulders.","Lower the bar slowly toward your neck, elbows flared.","Press it back up under control without locking out hard."]],"Oblique_Crunches_-_On_The_Floor":[["اتمدد على الأرض وركبتك مثنية وإيدك خلف راسك.","ارفع كتفك ناحية الركبة المعاكسة.","نزّل ببطء وبدّل الجنب من غير شد رقبتك."],["Lie on the floor, knees bent, hands behind your head.","Lift one shoulder toward the opposite knee.","Lower slowly and switch sides without pulling your neck."]],"Oblique_Crunches":[["اتمدد على ضهرك وركبتك مثنية وإيدك خلف راسك.","ارفع جذعك ولف ناحية جنب واحد.","نزّل ببطء وبدّل الجنب."],["Lie on your back, knees bent, hands behind your head.","Crunch up and twist toward one side.","Lower slowly and switch sides."]],"Olympic_Squat":[["قف والبار على كتفك ورجليك في عرض الكتف.","انزل سكوات عميق وضهرك مفرود.","اطلع بقوة وتحكم وركبتك ماشية مع صوابعك."],["Stand with the bar on your shoulders, feet shoulder-width.","Squat deep with a straight back.","Drive up under control, knees tracking over toes."]],"On-Your-Back_Quad_Stretch":[["اتمدد على ضهرك وامسك كعب رجل مثنية.","اسحب كعبك ناحية الجلوتس براحة.","ثبّت 20-30 ثانية وبدّل الرجل."],["Lie on your back and bend one knee, holding the ankle.","Pull your heel gently toward your glutes.","Hold 20-30 seconds and switch legs."]],"On_Your_Side_Quad_Stretch":[["اتمدد على جنبك وامسك كاحل الرجل اللي فوق.","اسحب كعبك ناحية الجلوتس وحوضك ثابت.","ثبّت 20-30 ثانية وبدّل الجنب."],["Lie on your side and hold the top ankle.","Pull your heel toward your glutes, keeping your hips steady.","Hold 20-30 seconds and switch sides."]],"One-Arm_Flat_Bench_Dumbbell_Flye":[["اتمدد على بنش مسطح وامسك دامبل بإيد واحدة فوق صدرك.","افتح دراعك للجنب بقوس وكوعك مثني شوية.","ارجع للبداية بتحكم وشد الصدر."],["Lie on a flat bench holding a dumbbell above your chest in one hand.","Open your arm out in an arc with a slight elbow bend.","Return to the start under control, squeezing your chest."]],"One-Arm_High-Pulley_Cable_Side_Bends":[["قف جنب البكرة العالية وامسك المقبض بإيد واحدة.","اثني جذعك جانبياً بعيد عن الكابل.","ارجع ببطء وبدّل الجنب."],["Stand beside the high pulley holding the handle with one hand.","Bend sideways away from the cable.","Return slowly and switch sides."]],"One-Arm_Incline_Lateral_Raise":[["اتمدد على جنبك على بنش مائل وامسك دامبل بإيد واحدة.","ارفع دراعك جانبياً لحد مستوى الكتف.","نزّل ببطء وكوعك مثني شوية."],["Lie sideways on an incline bench holding a dumbbell in one hand.","Raise your arm out to the side to shoulder height.","Lower slowly with a slight elbow bend."]],"One-Arm_Kettlebell_Clean_and_Jerk":[["امسك الكيتل بيل بإيد واحدة عند الكتف وقدميك في عرض الكتف.","اثني ركبتك وادفع بالرجلين لحد ما الكيتل بيل فوق راسك.","نزّله لكتفك ثم للأرض بتحكم وضهرك مفرود."],["Hold a kettlebell at one shoulder, feet shoulder-width.","Dip and drive through your legs to jerk the bell overhead.","Lower it to your shoulder then the floor under control, back flat."]],"One-Arm_Kettlebell_Clean":[["قف والكيتل بيل بين رجليك وانحني بضهر مفرود.","اسحب الكيتل بيل لفوق بدفع الورك لحد الكتف.","نزّله بتحكم لوضع التعليق وضهرك مفرود."],["Stand over the kettlebell and hinge with a flat back.","Pull it up with a hip drive to the shoulder rack.","Lower it back to the hang under control, back flat."]],"One-Arm_Kettlebell_Floor_Press":[["اتمدد على ضهرك وامسك الكيتل بيل بإيد واحدة عند الكتف.","ادفع الكيتل بيل لفوق صدرك.","نزّل ببطء لحد ما كوعك يلمس الأرض."],["Lie on your back holding a kettlebell at your shoulder in one hand.","Press the bell straight up above your chest.","Lower slowly until your elbow touches the floor."]],"One-Arm_Kettlebell_Jerk":[["امسك الكيتل بيل عند الكتف وقدميك في عرض الكتف.","اثني ركبتك شوية وادفع بالرجلين وارفع الكيتل بيل لفوق.","نزّله بتحكم لكتفك وبدّل الإيد."],["Hold a kettlebell at your shoulder, feet shoulder-width.","Dip slightly and drive up with your legs, jerking the bell overhead.","Lower to the shoulder under control and switch hands."]],"One-Arm_Kettlebell_Military_Press_To_The_Side":[["قف وامسك الكيتل بيل عند الكتف ورجليك في عرض الكتف.","ادفع الكيتل بيل لفوق وانحني جنب شوية بعيد عنه.","نزّله ببطء وبدّل الجنب."],["Stand with a kettlebell at your shoulder, feet shoulder-width.","Press it overhead, leaning slightly away from the weight.","Lower slowly and switch sides."]],"One-Arm_Kettlebell_Para_Press":[["اتمدد على ضهرك وامسك الكيتل بيل عند الكتف.","ادفع الكيتل بيل لفوق وبعدين انزل بتحكم.","ارجع للكتف ببطء وكوعك ثابت."],["Lie on your back with the kettlebell at your shoulder.","Press the bell straight up until your arm is locked out.","Lower back to the shoulder slowly, elbow steady."]],"One-Arm_Kettlebell_Push_Press":[["قف وامسك الكيتل بيل عند الكتف ورجليك في عرض الكتف.","اثني ركبتك شوية وادفع بالرجلين لحد ما الكيتل بيل فوق راسك.","نزّله ببطء لكتفك وبدّل الإيد."],["Stand with a kettlebell at your shoulder, feet shoulder-width.","Dip slightly and drive up with your legs, pressing the bell overhead.","Lower slowly to the shoulder and switch hands."]],"One-Arm_Kettlebell_Row":[["انحني على بنش بإيد واحدة وامسك الكيتل بيل بالإيد التانية وضهرك مفرود.","اسحب الكيتل بيل ناحية وركك وشد لوح كتفك.","نزّل ببطء وضهرك مفرود."],["Brace one hand on a bench, hold a kettlebell with the other, back flat.","Row the bell toward your hip, squeezing your shoulder blade.","Lower slowly with a flat back."]],"One-Arm_Kettlebell_Snatch":[["قف والكيتل بيل بين رجليك وانحني بضهر مفرود.","اسحب الكيتل بيل لفوق راسك بحركة واحدة بدفع الورك.","نزّله بتحكم وبدّل الإيد."],["Stand over the kettlebell and hinge with a flat back.","Snatch it overhead in one fluid motion, driving with your hips.","Lower under control and switch hands."]],"One-Arm_Kettlebell_Split_Jerk":[["امسك الكيتل بيل عند الكتف ورجليك في عرض الكتف.","اثني ركبتك وادفع واعمل وضع سبليت وإيدك لفوق.","ارجع لرجليك مع بعض ونزّل الكيتل بيل بتحكم وبدّل الرجل."],["Hold a kettlebell at the shoulder, feet shoulder-width.","Dip, drive up, and split your feet as the bell locks out overhead.","Bring your feet together and lower the bell under control; alternate legs."]],"One-Arm_Kettlebell_Split_Snatch":[["قف والكيتل بيل بين رجليك وانحني بضهر مفرود.","اسحب الكيتل بيل لفوق بدفع الورك واعمل وضع سبليت.","ارجع لرجليك مع بعض ونزّل بتحكم وبدّل الرجل."],["Stand over the kettlebell and hinge with a flat back.","Snatch the bell overhead and drop into a split stance.","Bring your feet together and lower under control; alternate legs."]],"One-Arm_Long_Bar_Row":[["قف على البار الطويل وإيدك على طرفه وانحني بضهر مفرود.","اسحب البار ناحية صدرك بإيد واحدة.","نزّل ببطء وضهرك مفرود وبدّل الجنب."],["Straddle the long bar, hinge with a flat back, one hand on the bar.","Row the bar toward your chest with one arm.","Lower slowly with a flat back and switch sides."]],"One-Arm_Medicine_Ball_Slam":[["قف ورجليك واسعة وامسك الميديسن بول فوق راسك بإيد.","اضرب الكورة بقوة على الأرض بإيد واحدة مع شد البطن.","امسكها وكرر وضهرك مفرود."],["Stand feet wide, holding the medicine ball overhead with one hand.","Slam the ball hard into the floor, bracing your abs.","Catch it and repeat with a straight back."]],"One-Arm_Open_Palm_Kettlebell_Clean":[["قف والكيتل بيل بين رجليك وانحني بضهر مفرود.","اسحب الكيتل بيل لفوق بدفع الورك بكف مفتوح.","نزّله بتحكم وضهرك مفرود."],["Stand over the kettlebell and hinge with a flat back.","Swing it up with a hip drive, hand open, into the rack.","Lower under control with a flat back."]],"One-Arm_Overhead_Kettlebell_Squats":[["قف وامسك كيتل بيل فوق راسك بإيد واحدة مفرودة.","انزل سكوات ببطء والدراع مثبت فوق راسك.","اطلع بقوة وضهرك مفرود وشد البطن."],["Stand holding a kettlebell locked out overhead with one hand.","Squat down slowly, keeping your arm locked above you.","Drive up with a straight back and tight core."]],"One-Arm_Side_Deadlift":[["قف وامسك البار بإيد واحدة على الجنب وانحني بضهر مفرود.","ارفع البار بفرد الورك والركبة.","نزّله ببطء وضهرك مفرود."],["Stand over the bar, hinge with a flat back, one hand gripping it at your side.","Lift it by extending hips and knees.","Lower slowly with a flat back."]],"One-Arm_Side_Laterals":[["قف وامسك دامبل بإيد واحدة على الجنب.","ارفع دراعك جانبياً لحد مستوى الكتف.","نزّل ببطء وكوعك مثني شوية."],["Stand holding a dumbbell in one hand at your side.","Raise your arm out to the side to shoulder height.","Lower slowly with a slight elbow bend."]],"One_Arm_Against_Wall":[["قف جنب حيطة وحط كف إيدك عليها وراسها لفوق.","لف جسمك بعيد عن الحيطة ببطء.","ثبّت 20-30 ثانية وبدّل الإيد."],["Stand beside a wall and place your palm on it, arm out.","Slowly turn your body away from the wall.","Hold 20-30 seconds and switch arms."]],"One_Arm_Chin-Up":[["امسك البار بقبضة من تحت بإيد واحدة والتانية تسند.","اسحب نفسك لفوق لحد ما دقنك تعدي البار.","نزّل ببطء وتحكم لحد التعليق."],["Hang from the bar with an underhand grip on one hand, the other assisting.","Pull yourself up until your chin clears the bar.","Lower slowly under control to the hang."]],"One_Arm_Dumbbell_Bench_Press":[["اتمدد على بنش مسطح وامسك دامبل بإيد واحدة عند الصدر.","ادفع الدامبل لفوق صدرك.","نزّل ببطء وكوعك مائل شوية."],["Lie on a flat bench with a dumbbell in one hand at chest level.","Press the dumbbell up above your chest.","Lower slowly with your elbow slightly angled."]],"One_Arm_Dumbbell_Preacher_Curl":[["اقعد على بنش بريتشر وامسك دامبل بإيد واحدة.","اثني الكوع وارفع الدامبل لكتفك.","نزّل ببطء من غير ما تفرد كوعك بعنف."],["Sit at a preacher bench holding a dumbbell in one hand.","Curl the dumbbell toward your shoulder.","Lower slowly without snapping your elbow straight."]],"One_Arm_Floor_Press":[["اتمدد على الأرض وامسك البار بإيد واحدة عند صدرك.","ادفع البار لفوق صدرك مع ترايسبس.","نزّل ببطء لحد ما كوعك يلمس الأرض."],["Lie on the floor holding the bar in one hand at chest level.","Press the bar up above your chest.","Lower slowly until your elbow touches the floor."]],"One_Arm_Lat_Pulldown":[["اقعد قدام البكرة العالية وامسك المقبض بإيد واحدة.","اسحب المقبض لتحت ناحية كتفك.","ارجع ببطء وضهرك مفرود."],["Sit at the high pulley gripping the handle with one hand.","Pull the handle down toward your shoulder.","Return slowly with a straight back."]],"One_Arm_Pronated_Dumbbell_Triceps_Extension":[["قف وامسك دامبل فوق راسك بإيد واحدة وكفك لقدام.","نزّل الدامبل ورا راسك بثني الكوع.","افرد دراعك لفوق وكوعك ثابت."],["Stand holding a dumbbell overhead in one hand, palm forward.","Lower the dumbbell behind your head by bending your elbow.","Extend your arm up with your elbow fixed."]],"One_Arm_Supinated_Dumbbell_Triceps_Extension":[["قف وامسك دامبل فوق راسك بإيد واحدة وكفك لورا.","نزّل الدامبل ورا راسك بثني الكوع.","افرد دراعك لفوق وكوعك ثابت."],["Stand holding a dumbbell overhead in one hand, palm back.","Lower the dumbbell behind your head by bending your elbow.","Extend your arm up with your elbow fixed."]],"One_Half_Locust":[["اتمدد على بطنك ورجليك مفرودة.","ارفع رجل واحدة لفوق من الورك بتحكم.","ثبّت 20-30 ثانية وبدّل الرجل."],["Lie face down with your legs straight.","Lift one leg up from the hip with control.","Hold 20-30 seconds and switch legs."]],"One_Handed_Hang":[["امسك بار العقلة بإيد واحدة وسيب جسمك معلق.","شد كتفك لتحت وخلي جسمك مستقر.","ثبّت 20-30 ثانية وبدّل الإيد."],["Grab the bar with one hand and hang.","Keep your shoulder pulled down and your body steady.","Hold 20-30 seconds and switch hands."]],"One_Knee_To_Chest":[["اتمدد على ضهرك وركبتك مثنية.","اسحب ركبة واحدة لصدرك بإيدك.","ثبّت 20-30 ثانية وبدّل الرجل."],["Lie on your back with knees bent.","Pull one knee toward your chest with your hands.","Hold 20-30 seconds and switch legs."]],"One_Leg_Barbell_Squat":[["قف والبار على كتفك وارفع رجل واحدة.","انزل سكوات ببطء على رجل واحدة.","اطلع بقوة وتحكم وركبتك ماشية مع صوابعك."],["Stand with the bar on your shoulders and one leg lifted.","Squat down slowly on one leg.","Drive up with control, knee tracking over toes."]],"Open_Palm_Kettlebell_Clean":[["قف والكيتل بيل بين رجليك وانحني بضهر مفرود.","اسحب الكيتل بيل لفوق بكف مفتوح.","نزّله بتحكم وضهرك مفرود."],["Stand over the kettlebell and hinge with a flat back.","Swing it up to the rack with an open palm.","Lower it under control with a flat back."]],"Otis-Up":[["اتمدد على ضهرك وركبتك مثنية وامسك وزن خفيف عند صدرك.","اعمل سيت أب ببطء بشد البطن.","نزّل ببطء وضهرك لازق في الأرض."],["Lie on your back, knees bent, holding a light weight at your chest.","Sit up slowly by bracing your abs.","Lower slowly, keeping your lower back controlled."]],"Overhead_Cable_Curl":[["قف قدام الكابل وامسك الحبل فوق راسك.","اثني الكوع واسحب الحبل ناحية راسك.","نزّل ببطء وكوعك ثابت."],["Stand facing the cable with the handle overhead.","Curl the handle toward your head.","Lower slowly with your elbows fixed."]],"Overhead_Lat":[["قف أو اقعد وارفع دراعاتك فوق راسك وامسك كوع بإيدك التانية","اسحب الكوع ورا الراس وميّل جذعك ناحية الجنب ببطء","ثبّت 20-30 ثانية وحافظ على بطنك مشدودة وظهرك مش مقوس"],["Raise both arms overhead and hold one elbow with the opposite hand.","Gently pull the elbow behind your head and lean to the side.","Hold 20-30 seconds, keeping your core tight and back from arching."]],"Overhead_Slam":[["قف بقدمين أعرض من الكتف وامسك كورة السلام فوق راسك","اضرب الكورة في الأرض بكل قوتك وانت بتنزل بجسمك","التقط الكورة وارجع اطلع بيها فوق راسك وظهرك مفرود"],["Stand feet shoulder-width apart holding a slam ball overhead.","Slam the ball hard into the floor, hinging down with your hips.","Pick it up and return overhead, keeping your back flat."]],"Overhead_Squat":[["امسك البار بقبضة واسعة وارفعه فوق راسك بدراعات مفرودة","انزل في سكوات ببطء والبار ثابت فوق راسك وصدرك مرفوع","اطلع بقوة من الكعب وماتقفلش الكوع بعنف وخلي ظهرك مفرود"],["Hold the bar overhead with a wide grip and arms extended.","Squat down slowly, keeping the bar stable over your head and chest up.","Drive up through your heels, keeping your back flat and core braced."]],"Overhead_Stretch":[["قف وشبّك صوابعك وارفع دراعاتك فوق راسك وكف إيدك لفوق","مدّ دراعاتك لفوق وللخلف شوية وانت بتاخد نفس عميق","ثبّت 20-30 ثانية وماتقوّسش ضهرك"],["Stand tall, interlace your fingers and raise arms overhead, palms up.","Reach up and slightly back while breathing deeply.","Hold 20-30 seconds without arching your lower back."]],"Overhead_Triceps":[["قف وارفع دراع فوق راسك وانثني الكوع ليكون إيدك ورا رقبتك","امسك الكوع بإيدك التانية واسحبه ببطء لورا الراس","ثبّت 20-30 ثانية وبدّل الدراع وخلي رقبتك مرتاحة"],["Stand and raise one arm overhead, bending the elbow so your hand drops behind your neck.","Hold that elbow with the other hand and gently pull it back.","Hold 20-30 seconds, then switch arms, keeping your neck relaxed."]],"Pallof_Press_With_Rotation":[["قف جنب الكابل وامسك الإيد بالإيدين قدام صدرك والكور مشدود","ادفع الكابل لقدام لحد ما دراعاتك تتفرد وبعدين لف الجذع شوية بعيد عن الكابل","رجّع الإيد لصدرك ببطء وماتسيبش الكابل يلفك"],["Stand sideways to the cable, handle held at your chest, core braced.","Press the handle straight out, then rotate your torso slightly away from the cable.","Return to center and bring the handle back in, resisting the cable's pull."]],"Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench":[["اقعد وسند ساعديك على البنش وكفوفك لأسفل ماسكين الدامبل والرسغ برا البنش","نزّل الرسغ لتحت ببطء وبعدين ارفعه لفوق بأقصى مدى","تحكّم في الحركة وخلي الساعد ثابت على البنش بدون حركة"],["Kneel or sit, forearms on a bench, palms down holding dumbbells with wrists past the edge.","Lower the wrists slowly, then curl them up as high as you can.","Control the movement and keep your forearms still on the bench."]],"Palms-Down_Wrist_Curl_Over_A_Bench":[["اقعد وسند ساعديك على البنش وكفوفك لأسفل ماسكين البار والرسغ برا البنش","ارفع الرسغ لفوق بأقصى مدى وساعدك ثابت","نزّل البار ببطء لحد ما تحس بشد في الساعد"],["Sit with forearms on a bench, palms down gripping the bar, wrists past the edge.","Extend your wrists upward as far as possible, forearms still.","Lower the bar slowly until you feel a stretch in the forearms."]],"Palms-Up_Barbell_Wrist_Curl_Over_A_Bench":[["اقعد وسند ساعديك على البنش وكفوفك لأعلى ماسكين البار والرسغ برا البنش","اثني الرسغ وارفع البار لفوق بأقصى مدى","نزّل البار ببطء وساعدك ثابت على البنش"],["Sit with forearms on a bench, palms up holding the bar, wrists past the edge.","Curl the bar upward by flexing your wrists as high as you can.","Lower it slowly with your forearms staying flat on the bench."]],"Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench":[["اقعد وسند ساعديك على البنش وكفوفك لأعلى ماسكين الدامبل والرسغ برا البنش","اثني الرسغ وارفع الدامبل لفوق بأقصى مدى","نزّل الدامبل ببطء وماتحركش ساعدك"],["Sit with forearms on a bench, palms up holding dumbbells, wrists past the edge.","Curl the dumbbells up by flexing your wrists fully.","Lower slowly without lifting your forearms off the bench."]],"Parallel_Bar_Dip":[["اتسند على العقلتين المتوازيتين بدراعات مفرودة والكتف بعيد عن ودانك","انزل ببطء بثني الكوع لحد ما تحس بشد في الصدر والترايسبس","ادفع لفوق لحد ما دراعك يتفرد من غير ما تقفل الكوع بعنف"],["Support yourself on parallel bars with arms straight and shoulders down.","Lower slowly by bending your elbows until you feel a chest and triceps stretch.","Press back up until arms are straight, without locking elbows hard."]],"Pelvic_Tilt_Into_Bridge":[["اتمدد على ضهرك وركبك مثنية والقدمين مفرودين على الأرض","شد بطنك وميّل الحوض لحد ما ضهرك السفلي يلزق في الأرض","ارفع الأرداف لفوق لحد ما تعمل جسر ونزّل ببطء فقرة فقرة"],["Lie on your back with knees bent and feet flat on the floor.","Tighten your abs and tilt your pelvis so your lower back presses into the floor.","Lift your hips into a bridge, then lower slowly one vertebra at a time."]],"Peroneals-SMR":[["اقعد على الأرض وحط الفوم رولر تحت الجزء الخارجي من الساق","ارفع جسمك بإيديك وادحرج الفوم رولر ببطء على طول الساق","وقّف على أي نقطة مشدودة شوية وماتدحرجش على عظمة الركبة"],["Sit and place the foam roller under the outer side of your lower leg.","Support with your hands and roll slowly along the outer shin.","Pause on tight spots and avoid rolling directly over the knee joint."]],"Peroneals_Stretch":[["اقعد وحط رجل فوق التانية وامسك جزء القدم الخارجي","اسحب القدم لجوه وللأسفل شوية لحد ما تحس بشد في خارج الساق","ثبّت 20-30 ثانية وبدّل الرجل من غير ألم حاد"],["Sit and cross one ankle over the opposite knee, gripping your foot.","Gently turn the sole inward and down until you feel a stretch on the outer shin.","Hold 20-30 seconds, then switch legs, stopping if you feel sharp pain."]],"Physioball_Hip_Bridge":[["اتمدد على ضهرك وحط كعب رجليك على الكورة السويسرية وركبك مفرودة شوية","اضغط بكعبك وارفع الأرداف لحد ما جسمك يبقى خط مستقيم","اعصر الأرداف في القمة ونزّل ببطء وماتقوّسش ضهرك"],["Lie on your back with heels on a stability ball and legs nearly straight.","Press your heels in and lift your hips until your body forms a straight line.","Squeeze your glutes at the top and lower slowly without arching your back."]],"Pin_Presses":[["اضبط البار على بنز في الراك تحت مستوى الصدر وانبطح على البنش","ادفع البار لفوق بقوة من على البنز لحد ما دراعك يتفرد","نزّل البار ببطء وخليه يرتاح على البنز وبعدين كرر"],["Set the pins in the rack at your target height and lie on the bench with the bar resting on them.","Press the bar up explosively until your arms are extended.","Lower it under control back onto the pins and reset before the next rep."]],"Piriformis-SMR":[["اقعد على الفوم رولر وحط كاحل رجل على ركبة الرجل التانية","ميّل وزنك على جنب الرجل المتصالبة وادحرج ببطء على الأرداف","وقّف على النقاط المشدودة وماتدحرجش على أسفل الضهر"],["Sit on the foam roller and cross one ankle over the opposite knee.","Lean toward the crossed-leg side and roll slowly over the deep glute area.","Pause on tight spots and avoid rolling over your lower back."]],"Plate_Pinch":[["امسك طبقين أملسين مع بعض بصوابعك وإبهامك من غير ما تمسك الحافة بكفك","ارفع الطبقين وانت واقف وكتفك لورا وضهرك مفرود","ثبّت المسكة أطول وقت ممكن وبعدين نزّلهم بتحكم"],["Pinch two smooth plates together with fingers and thumb, smooth sides out.","Lift them and stand tall with shoulders back and spine neutral.","Hold the pinch as long as you can, then lower under control."]],"Plate_Twist":[["اقعد على الأرض وركبك مثنية وامسك طبق قدام صدرك وانحني لورا شوية","لف جذعك لجنب وحرك الطبق ناحيته","لف للجنب التاني ببطء وخلي ضهرك مفرود والبطن مشدودة"],["Sit with knees bent, holding a plate at your chest and leaning back slightly.","Rotate your torso to one side, moving the plate with you.","Rotate to the other side slowly, keeping your back straight and abs tight."]],"Platform_Hamstring_Slides":[["اتمدد على ضهرك وكعب رجليك على منصة منزلقة وارفع الأرداف","اسحب كعبك ناحية جسمك وانت ماسك الأرداف مرفوعة","افرد رجليك ببطء لحد ما ترجع للبداية وماتنزلش الحوض"],["Lie on your back with heels on a sliding platform and hips lifted.","Slide your heels toward your glutes while keeping your hips up.","Slowly extend your legs back out without dropping your hips."]],"Plie_Dumbbell_Squat":[["قف بقدمين أوسع من الكتف وصوابعك للخارج وامسك دامبل بين رجليك بالإيدين","انزل بالركبة في اتجاه صوابعك وضهرك مفرود لحد ما فخذك يوازي الأرض","اطلع بالضغط على كعبك واعصر الأرداف في القمة"],["Stand with a wide stance, toes turned out, holding a dumbbell between your legs.","Lower by bending your knees over your toes, back straight, to thigh parallel.","Drive up through your heels and squeeze your glutes at the top."]],"Plyo_Kettlebell_Pushups":[["خد وضع الضغط ويد واحدة على كيتل بيل والتانية على الأرض وجسمك مستقيم","انزل بصدرك ثم ادفع بانفجار لفوق وبدّل الإيدين في الهواء","انزل بنعومة على الإيد التانية مع ثني الكوع وبطنك مشدود"],["Start in a push-up position with one hand on a kettlebell, body straight.","Lower your chest, then explode up and switch hands in the air.","Land softly with bent elbows on the opposite side, core tight."]],"Posterior_Tibialis_Stretch":[["قف قدام حيطة أو اقعد وحط رجلك للأمام وصوابعك لفوق","اثني رجلك الخلفية شوية وميّل الكاحل لبرا بلطف لحد ما تحس بشد بجوه الساق","ثبّت 20-30 ثانية وبدّل الرجل بدون ألم"],["Stand facing a wall or sit with one foot forward, toes up.","Gently roll the ankle outward to feel a stretch along the inner shin and calf.","Hold 20-30 seconds, then switch legs, staying pain-free."]],"Power_Clean_from_Blocks":[["قف بالقدمين بعرض الحوض وامسك البار الموضوع على البلوكات بقبضة أعرض من الركب وضهرك مفرود","ارفع البار بقوة وافرد الركبة والحوض وشد الكتف بسرعة وادخل تحت البار","استقبل البار على الكتف بكوعك لقدام وبعدين انزل البار بتحكم"],["Set feet hip-width and grip the bar on blocks just outside the knees, back flat.","Drive up explosively through legs and hips, shrug, and pull under the bar.","Catch it on your front shoulders in a quarter squat, then lower with control."]],"Power_Jerk":[["ثبّت البار على كتفك قدام والقدمين بعرض الحوض وبطنك مشدود","اثني الركبة شوية وانفجر لفوق وادفع البار فوق راسك وانزل في ربع سكوات","ثبّت البار فوق راسك بدراعات مفرودة وبعدين ارجع واقف بتحكم"],["Rack the bar on your front shoulders, feet hip-width, core braced.","Dip slightly then drive up explosively, pressing the bar overhead and catching in a quarter squat.","Lock the bar overhead stably, stand tall, then lower with control."]],"Power_Partials":[["قف وامسك دامبل في كل إيد جنبك وضهرك مفرود وركبك مثنية شوية","ارفع الدامبل للجنب لحد مستوى الكتف في نطاق قصير وبقوة","نزّلهم ببطء وماتستخدمش زخم من الجسم"],["Stand holding dumbbells at your sides, back straight, knees slightly bent.","Raise the dumbbells out to the sides in a short, strong range to shoulder height.","Lower slowly without swinging your torso for momentum."]],"Power_Snatch_from_Blocks":[["قف بالقدمين بعرض الحوض وامسك البار على البلوكات بقبضة واسعة وضهرك مفرود","افرد الرجل والحوض بانفجار واشد الكتف وارفع البار فوق راسك","استقبل البار بدراعات مفرودة فوق الراس في ربع سكوات وبعدين ثبّت وقف"],["Set feet hip-width and grip the bar on blocks with a wide grip, back flat.","Extend hips and legs explosively, shrug, and pull the bar overhead.","Catch it with locked arms overhead in a quarter squat, then stand tall."]],"Power_Snatch":[["قف على البار بقدمين بعرض الحوض وقبضة واسعة وضهرك مفرود وصدرك مرفوع","ارفع البار من الأرض ثم افرد الحوض بانفجار واشد الكتف واسحب البار فوق الراس","استقبل البار فوق راسك بدراعات مفرودة في ربع سكوات وثبّت وقف"],["Stand over the bar, feet hip-width, wide grip, back flat and chest up.","Lift off the floor, then extend hips explosively, shrug, and pull the bar overhead.","Catch it with locked arms in a quarter squat, then stand tall."]],"Power_Stairs":[["قف قدام سلم وحط قدم كاملة على أول درجة وجسمك مايل لقدام شوية","ادفع بقوة من الرجل اللي على الدرجة واطلع درجتين أو أكتر بسرعة","انزل بحذر وبتحكم وماتجريش من غير ما تثبت قدمك"],["Face a staircase and plant your full foot on the first step, torso leaning slightly forward.","Drive off the lead leg and climb the steps quickly and powerfully.","Come down carefully and controlled, planting your whole foot each step."]],"Preacher_Hammer_Dumbbell_Curl":[["اقعد على البريتشر وامسك دامبل بقبضة هامر وكفوفك ناحية بعض والدراع مفرود","اثني الكوع وارفع الدامبل لحد ما تحس بانقباض في البايسبس","نزّل ببطء لحد ما دراعك يتفرد تقريبا من غير ما تقفل الكوع بعنف"],["Sit at a preacher bench holding a dumbbell with a hammer grip, arm extended.","Curl the dumbbell up until your biceps are fully contracted.","Lower slowly until the arm is nearly straight, without locking the elbow hard."]],"Press_Sit-Up":[["اتمدد على ضهرك وركبك مثنية وامسك بار خفيف على صدرك","اطلع بجذعك لفوق لحد ما تقعد وفي نفس الوقت ادفع البار فوق راسك","نزّل ببطء ونزّل البار لصدرك بتحكم من غير ما تشد رقبتك"],["Lie on your back with knees bent, holding a light bar at your chest.","Sit up while pressing the bar overhead.","Lower back down slowly and bring the bar to your chest, without yanking your neck."]],"Prone_Manual_Hamstring":[["انبطح على بطنك وخلي شريك يمسك كعب رجل واحدة","اثني ركبتك وارفع كعبك ناحية الأرداف وشريكك بيقاوم بلطف","ارجع رجلك ببطء لحد ما تتفرد وماتقوّسش ضهرك"],["Lie face down with a partner holding one ankle.","Curl your heel toward your glutes while your partner resists gently.","Straighten the leg slowly and keep your lower back from arching."]],"Prowler_Sprint":[["امسك مقابض البروولر بدراعات مفرودة وجسمك مايل لقدام وضهرك مفرود","ادفع بقوة وجري بخطوات قصيرة وسريعة وانت قاعد على الرجل","وقّف بشكل تدريجي في نهاية المسافة وخد نفسك"],["Grip the prowler handles with arms extended, body leaning forward, back flat.","Drive hard with short, fast steps pushing through the balls of your feet.","Slow down gradually at the end of the distance and catch your breath."]],"Pull_Through":[["قف ضهرك للكابل المنخفض وامسك الحبل بين رجليك وركبك مثنية شوية","اثني من الحوض ورجّع الأرداف لورا وضهرك مفرود","افرد الحوض بقوة واعصر الأرداف وانت واقف وقف مفرود"],["Face away from a low cable, holding the rope between your legs, knees slightly bent.","Hinge at the hips, pushing them back with a flat back.","Drive your hips forward and squeeze your glutes to stand tall."]],"Push-Ups_With_Feet_Elevated":[["حط رجليك على بنش وإيديك على الأرض أعرض من الكتف وجسمك مستقيم","انزل بصدرك ببطء لحد ما يقرب من الأرض والكوع بزاوية 45 درجة","ادفع لفوق لحد ما دراعك يتفرد وماتسيبش وسطك يقع"],["Place feet on a bench and hands on the floor slightly wider than shoulders, body straight.","Lower your chest toward the floor with elbows at about 45 degrees.","Press back up until arms are straight, keeping your hips from sagging."]],"Push-Ups_With_Feet_On_An_Exercise_Ball":[["حط رجليك على كورة سويسرية وإيديك على الأرض أعرض من الكتف وجسمك مستقيم","انزل بصدرك ببطء وشد بطنك عشان تثبت الجسم","ادفع لفوق لحد ما دراعك يتفرد وماتقوّسش ضهرك"],["Put your feet on a stability ball with hands on the floor, wider than shoulders, body straight.","Lower your chest slowly while bracing your core for balance.","Push back up until arms are straight without arching your back."]],"Push_Press_-_Behind_the_Neck":[["ثبّت البار على كتفك ورا رقبتك بقبضة واسعة وقدميك بعرض الكتف","اثني ركبتك شوية وادفع بقوة وارفع البار فوق راسك","نزّل البار ببطء لورا الرقبة وماتعملش الحركة لو كتفك مش مرن"],["Rest the bar behind your neck on your shoulders with a wide grip, feet shoulder-width.","Dip slightly and drive up, pressing the bar overhead.","Lower it slowly behind the neck; skip this if your shoulders lack mobility."]],"Push_Up_to_Side_Plank":[["خد وضع الضغط وإيديك تحت الكتف وجسمك مستقيم","اعمل ضغطة وبعدين لف جسمك ورفع دراع واحد لفوق لوضع بلانك جانبي","ارجع لوضع الضغط ببطء وبدّل الجنب في التكرار التاني"],["Start in a push-up position with hands under shoulders and body straight.","Do a push-up, then rotate and lift one arm to the ceiling into a side plank.","Return to the push-up position slowly and alternate sides."]],"Pushups_Close_and_Wide_Hand_Positions":[["خد وضع الضغط وإيديك قريبين من بعض تحت الصدر وجسمك مستقيم","انزل واطلع بالضغط بقبضة ضيقة وبعدين وسّع إيديك أعرض من الكتف","كرر بنفس الشكل وخلي بطنك مشدود وماتسيبش الحوض يقع"],["Start in a push-up position with hands close together under your chest.","Do reps close-grip, then move hands wider than shoulders.","Repeat, keeping your core tight and hips from sagging."]],"Pyramid":[["اركع على الأرض وانحني وحط إيديك على كورة سويسرية قدامك","اضغط على الكورة وارفع أردافك لفوق لوضع هرم وضهرك مفرود","ثبّت 20-30 ثانية وانزل ببطء مع التنفس"],["Kneel and place your hands on a stability ball in front of you.","Push your hips up and back into an inverted-V pyramid shape, back straight.","Hold 20-30 seconds while breathing, then lower slowly."]],"Quad_Stretch":[["قف وامسك حاجة للتوازن وارفع كعب رجل ناحية أردافك","امسك القدم بإيدك واسحب كعبك لأردافك وخلي الركبتين جنب بعض","ثبّت 20-30 ثانية وماتقوّسش ضهرك وبدّل الرجل"],["Stand holding something for balance and lift one heel toward your glutes.","Hold your foot and pull the heel to your glutes, knees together.","Hold 20-30 seconds without arching your back, then switch legs."]],"Quadriceps-SMR":[["انبطح وحط الفوم رولر تحت فخذك الأمامي وارتكز على ساعديك","ادحرج جسمك لقدام ولورا ببطء من الحوض لفوق الركبة","وقّف على أي نقطة مشدودة شوية وماتدحرجش على الركبة نفسها"],["Lie face down with the foam roller under your front thighs, propped on forearms.","Roll slowly from hip to just above the knee.","Pause on tight spots and avoid rolling over the knee itself."]],"Quick_Leap":[["قف بقدمين بعرض الكتف وركبك مثنية شوية وإيديك جنبك","اقفز لأعلى وللأمام بسرعة وانت بتمرجح إيديك","انزل بنعومة على مشط القدم مع ثني الركبة"],["Stand feet shoulder-width, knees slightly bent, arms ready.","Leap up and forward quickly, swinging your arms.","Land softly on the balls of your feet with bent knees."]],"Rack_Delivery":[["قف والبار على الراكة على مستوى الفخذ أو الركبة وامسك بقبضة أعرض من الكتف","اسحب البار بقوة وافرد الحوض وشد الكتف وانت بتدخل تحته","استقبل البار على كتفك قدام بكوع مرفوع وثبّت وقفتك"],["Stand at a rack with the bar at thigh or knee height, grip wider than shoulders.","Pull explosively, extend your hips, shrug, and drop under the bar.","Catch it on your front shoulders with elbows up and stand tall."]],"Rack_Pull_with_Bands":[["اضبط البار على الراكة على مستوى الركبة مع الباند وامسك بقبضة أعرض من الكتف","ارفع البار بافراد الحوض والركبة وضهرك مفرود لحد ما تقف","نزّل البار بتحكم لمستوى الراكة وماتقوّسش ضهرك"],["Set the bar on the rack at knee height with bands attached, grip shoulder-width or wider.","Pull by extending your hips and knees, back flat, until you stand tall.","Lower the bar under control to the rack without rounding your back."]],"Rack_Pulls":[["اضبط البار على الراكة على مستوى الركبة وامسك بقبضة أعرض من الكتف وضهرك مفرود","ارفع البار بافراد الحوض والركبة وشد لوحي الكتف","نزّل البار ببطء للراكة وصدرك مرفوع وماتقوّسش ضهرك"],["Set the bar on the rack at knee height, grip just outside your legs, back flat.","Lift by extending hips and knees, squeezing your shoulder blades back.","Lower the bar slowly to the rack, chest up, without rounding your back."]],"Rear_Leg_Raises":[["ادخل على أربع وإيديك تحت الكتف وركبك تحت الحوض","افرد رجل لورا وارفعها لحد مستوى الأرداف وماتقوّسش ضهرك","نزّلها ببطء وكرر ثم بدّل الرجل"],["Start on all fours with hands under shoulders and knees under hips.","Extend one leg back and lift it to hip height without arching your back.","Lower slowly, repeat, then switch legs."]],"Recumbent_Bike":[["اقعد على العجلة وظهرك على المسند واضبط البدال بحيث ركبك مثنية شوية","دوّس البدال بإيقاع ثابت وبمقاومة مناسبة","حافظ على ضهرك لاصق في المسند وخد نفس منتظم"],["Sit with your back against the seat and adjust pedals so knees stay slightly bent.","Pedal at a steady pace with moderate resistance.","Keep your back against the seat and breathe steadily."]],"Return_Push_from_Stance":[["قف في وضع المقاتل وإيدك قدامك وركبك مثنية شوية","ادفع بإيدك لقدام بقوة وانت بتنقل وزنك للرجل الأمامية","ارجع للوضع الأول بسرعة وتحكم"],["Stand in a staggered stance with knees slightly bent and hands up.","Push forward with your hands powerfully while shifting weight onto the front leg.","Return to the start position quickly and under control."]],"Reverse_Band_Bench_Press":[["انبطح على البنش والبار متعلق بباند وامسك بقبضة أعرض من الكتف","نزّل البار لصدرك ببطء وكوعك بزاوية 45 درجة","ادفع البار لفوق لحد ما دراعك يتفرد من غير ما تقفل الكوع بعنف"],["Lie on the bench with the bar attached to bands overhead, grip wider than shoulders.","Lower the bar to your chest slowly, elbows at about 45 degrees.","Press up until arms extend, without locking elbows hard."]],"Reverse_Band_Box_Squat":[["قف قدام صندوق والبار على ضهرك والباند متعلق من فوق وقدميك أعرض من الكتف","انزل بأردافك لورا لحد ما تلمس الصندوق بتحكم وضهرك مفرود","اطلع بقوة من الكعب وماتسيبش جسمك يرتخي على الصندوق"],["Stand in front of a box with the bar on your back, bands attached overhead, feet wide.","Sit your hips back to lightly touch the box, back flat.","Drive up through your heels without relaxing completely on the box."]],"Reverse_Band_Deadlift":[["قف على البار والباند متعلق من فوق وامسك البار بقبضة بعرض الكتف وضهرك مفرود","ارفع البار بافراد الحوض والركبة وصدرك مرفوع","نزّل البار ببطء على رجليك وماتقوّسش ضهرك"],["Stand at the bar with bands attached overhead, grip shoulder-width, back flat.","Lift by extending hips and knees, chest up.","Lower the bar slowly along your legs without rounding your back."]],"Reverse_Band_Power_Squat":[["ضع البار على ضهرك والباند من فوق وقدميك أعرض من الكتف وصدرك مرفوع","انزل بسكوات بأردافك لورا لحد ما فخذك يوازي الأرض","اطلع بقوة من الكعب وماتخلّيش ركبك تدخل لجوه"],["Place the bar on your back with bands attached overhead, feet wider than shoulders, chest up.","Squat down, hips back, until thighs are parallel.","Drive up through your heels, keeping knees tracking over toes."]],"Reverse_Band_Sumo_Deadlift":[["قف بقدمين واسعين وصوابعك لبرا والباند من فوق وامسك البار بقبضة ضيقة بين رجليك","ارفع البار بدفع الأرض وافرد الحوض وصدرك مرفوع","نزّل البار ببطء مع الحفاظ على ضهرك مفرود"],["Stand with a wide stance, toes out, bands attached overhead, grip the bar between your legs.","Push the floor away and extend your hips, chest up.","Lower the bar slowly, keeping your back flat."]],"Reverse_Barbell_Preacher_Curls":[["اقعد على البريتشر وامسك EZ بار بقبضة عكسية وكفوفك لأسفل","اثني كوعك وارفع البار لحد ما الساعد يقرب من الدراع","نزّل ببطء لحد ما دراعك يتفرد تقريبا وماتقفلش الكوع بعنف"],["Sit at a preacher bench holding an EZ bar with an overhand (reverse) grip.","Curl the bar up until your forearms approach your upper arms.","Lower slowly until arms are nearly straight, without locking elbows hard."]],"Reverse_Cable_Curl":[["قف قدام كابل منخفض وامسك البار بقبضة كفوف لأسفل وكوعك جنبك","اثني كوعك وارفع البار لحد مستوى الكتف وماتحركش كوعك","نزّل ببطء وخلي الرسغ ثابت"],["Stand facing a low cable, holding the bar palms down, elbows at your sides.","Curl the bar up toward shoulder height without moving your elbows.","Lower slowly, keeping your wrists steady."]],"Reverse_Flyes_With_External_Rotation":[["انحني من الحوض وضهرك مفرود وامسك دامبل في كل إيد ودراعك مثنية شوية","ارفع دراعك للجنب لحد مستوى الكتف ثم لف الدراع لفوق لدوران خارجي","نزّل ببطء وماتستخدمش زخم"],["Hinge at the hips with a flat back, holding dumbbells with slightly bent arms.","Raise your arms out to shoulder height, then rotate them up (external rotation).","Lower slowly and avoid using momentum."]],"Reverse_Grip_Bent-Over_Rows":[["انحني من الحوض وضهرك مفرود وامسك البار بقبضة عكسية كفوف لفوق","اسحب البار لأسفل صدرك وشد لوحي الكتف ورا","نزّل البار ببطء وماتقوّسش ضهرك"],["Hinge at the hips with a flat back, holding the bar with an underhand grip.","Pull the bar to your lower chest, squeezing your shoulder blades.","Lower slowly without rounding your back."]],"Reverse_Plate_Curls":[["قف وامسك طبق بقبضة عكسية من الحافتين وكوعك جنبك","اثني الكوع وارفع الطبق لحد مستوى الكتف","نزّل ببطء وماتميلش جسمك لورا"],["Stand holding a plate by its edges with an overhand grip, elbows at your sides.","Curl the plate up toward shoulder height.","Lower slowly without leaning back."]],"Reverse_Triceps_Bench_Press":[["انبطح على البنش وامسك البار بقبضة عكسية ضيقة كفوف لفوق وكوعك جنب جسمك","نزّل البار لصدرك ببطء وكوعك قريب من الجسم","ادفع البار لفوق لحد ما دراعك يتفرد من غير ما تقفل الكوع بعنف"],["Lie on the bench and hold the bar with a narrow underhand grip.","Lower the bar to your chest slowly, elbows tucked in close.","Press up until arms extend, without locking elbows hard."]],"Rhomboids-SMR":[["اتمدد على الفوم رولر بحيث يكون تحت أعلى الضهر وإيدك متقاطعين على صدرك","ارفع الأرداف وادحرج الجسم ببطء بين لوحي الكتف","وقّف على النقاط المشدودة وماتدحرجش على أسفل الضهر"],["Lie with the foam roller under your upper back, arms crossed over your chest.","Lift your hips and roll slowly across the area between your shoulder blades.","Pause on tight spots and avoid rolling your lower back."]],"Rickshaw_Carry":[["قف جوه إطار الريكشو وامسك المقابض وضهرك مفرود وصدرك مرفوع","ارفع الإطار بافراد الركبة والحوض وامشي بخطوات ثابتة","نزّل الإطار بتحكم لما تخلص المسافة"],["Stand inside the rickshaw frame, grip the handles, back flat and chest up.","Lift by driving through your legs and walk with steady steps.","Set the frame down under control when you finish the distance."]],"Rickshaw_Deadlift":[["قف جوه إطار الريكشو وامسك المقابض وضهرك مفرود وصدرك مرفوع","ارفع الإطار بدفع الأرض وافراد الحوض والركبة","نزّل الإطار ببطء للأرض وماتقوّسش ضهرك"],["Stand inside the rickshaw frame, grip the handles, back flat and chest up.","Drive through the floor and extend your hips and knees to stand.","Lower the frame slowly to the floor without rounding your back."]],"Ring_Dips":[["ثبّت نفسك على الحلق بدراعات مفرودة والحلق قريبين من جسمك","انزل ببطء بثني الكوع مع الحفاظ على ثبات الحلق","ادفع لفوق لحد ما دراعك يتفرد وماتقفلش الكوع بعنف"],["Support yourself on rings with arms straight and rings close to your body.","Lower slowly by bending your elbows, keeping the rings stable.","Press back up until arms extend, without locking elbows hard."]],"Rocket_Jump":[["قف بقدمين بعرض الكتف وانزل في نصف سكوات وإيدك لورا","اقفز لفوق بأقصى قوة ومد دراعك لفوق","انزل بنعومة على مشط القدم مع ثني الركبة"],["Stand feet shoulder-width and drop into a half squat with arms back.","Jump up explosively, reaching your arms overhead.","Land softly on the balls of your feet with bent knees."]],"Rocking_Standing_Calf_Raise":[["قف والبار على ضهرك على كتفك ومشط قدمك على حافة مرتفعة","ارفع كعبك لفوق بأقصى مدى وانقل وزنك على مشط القدم","نزّل ببطء لحد ما تحس بشد في السمانة وماتقفلش الركبة"],["Stand with a bar on your upper back and the balls of your feet on a raised edge.","Rise onto your toes as high as you can, rocking weight onto the forefoot.","Lower slowly until you feel a calf stretch, keeping knees soft."]],"Rocky_Pull-Ups_Pulldowns":[["امسك البار بقبضة أعرض من الكتف وجسمك متعلق ودراعك مفرود","اسحب نفسك لفوق لحد ما راسك يقرب من البار مع شد الكتف لتحت","نزّل ببطء لحد ما دراعك يتفرد وماتتأرجحش"],["Grip the bar wider than shoulders and hang with arms extended.","Pull yourself up until your head is near the bar, shoulders pulled down.","Lower slowly until arms are straight without swinging."]],"Romanian_Deadlift_from_Deficit":[["قف على قرص أو منصة مرتفعة وامسك البار بقبضة بعرض الكتف وركبك مثنية شوية","اثني من الحوض ورجّع الأرداف لورا ونزّل البار على رجليك وضهرك مفرود","افرد الحوض واعصر الأرداف وارجع واقف"],["Stand on a raised platform holding the bar shoulder-width, knees slightly bent.","Hinge at the hips, pushing them back, lowering the bar along your legs with a flat back.","Drive hips forward and squeeze your glutes to stand."]],"Rope_Climb":[["امسك الحبل بإيديك وإيدك فوق بعض وارفع رجليك للحبل","اسحب بدراعك وانقل إيدك لفوق وارفع رجلك للتثبيت","انزل بتحكم إيد بعد إيد وماتنزلش بسرعة على الحبل"],["Grip the rope with both hands and wrap your feet around it.","Pull with your arms, reach higher, and clamp the rope with your feet.","Descend under control hand over hand, avoiding fast slides that burn your hands."]],"Rope_Crunch":[["اركع قدام كابل عالي وامسك الحبل جنب راسك وحوضك ثابت","اثني جذعك لتحت وقرّب كوعك من ركبتك وشد بطنك","ارجع ببطء لوضع البداية وماتشدش بدراعك"],["Kneel facing a high cable, holding the rope beside your head, hips still.","Crunch down, bringing elbows toward your knees and squeezing your abs.","Return slowly to the start without pulling with your arms."]],"Rope_Straight-Arm_Pulldown":[["قف قدام كابل عالي وامسك الحبل ودراعك مفرود لقدام وانحني شوية","اسحب الحبل لأسفل لحد فخذك بدراع مفرود وشد الظهر","ارجع ببطء لفوق وحافظ على كوعك ثابت"],["Stand facing a high cable, holding the rope with straight arms and a slight forward lean.","Pull the rope down to your thighs, arms straight, squeezing your lats.","Return slowly upward, keeping your elbows fixed."]],"Round_The_World_Shoulder_Stretch":[["قف وامسك عصا أو منشفة بقبضة واسعة قدام جسمك","ارفع العصا فوق راسك ثم لورا ظهرك بدراع مفرود","ارجع بنفس الطريق ببطء وثبّت 10-15 ثانية عند الشد"],["Stand holding a stick or towel with a wide grip in front of you.","Raise it overhead and then behind your back with straight arms.","Return the same way slowly, holding 10-15 seconds at the tight point."]],"Runners_Stretch":[["ادخل في وضع اللانج واحط إيدك على الأرض جنب رجلك الأمامية","ثبّت رجلك الخلفية مفرودة واضغط بحوضك لتحت وقدام","ثبّت 20-30 ثانية وبدّل الرجل وماتقوّسش ضهرك"],["Step into a lunge with hands on the floor beside your front foot.","Keep the back leg straight and sink your hips forward and down.","Hold 20-30 seconds, then switch legs, keeping your back flat."]],"Sandbag_Load":[["قف قدام كيس الرمل وانزل بركبك ومسك الكيس بإيدك وضهرك مفرود","ارفع الكيس وادفع الحوض لقدام وحمّله على كتفك","ثبّت الكيس على الكتف أو على المنصة بتحكم"],["Stand over the sandbag, squat down, and grip it with a flat back.","Lift it and drive your hips forward, bringing it to your shoulder.","Place it on the shoulder or platform under control."]],"Scapular_Pull-Up":[["امسك بار العقلة وجسمك متعلق ودراعك مفرود","اسحب لوحي الكتف لتحت وارفع جسمك قليلا من غير ما تثني الكوع","ارجع لوضع التعلق ببطء وتحكم"],["Hang from a pull-up bar with arms fully extended.","Pull your shoulder blades down to lift your body slightly, without bending your elbows.","Return to the dead hang slowly and under control."]],"Scissor_Kick":[["اتمدد على ضهرك وإيدك تحت أردافك وارفع رجليك شوية عن الأرض","افتح رجليك وقفلهم بالتبادل زي المقص وبطنك مشدود","حافظ على ضهرك السفلي لاصق في الأرض وماتقوّسش"],["Lie on your back with hands under your glutes and legs lifted slightly.","Open and cross your legs alternately like scissors, abs tight.","Keep your lower back pressed into the floor and don't arch."]],"Scissors_Jump":[["قف في وضع لانج ورجل قدام ورجل ورا وركبك مثنية","اقفز لفوق وبدّل رجليك في الهواء","انزل بنعومة في لانج بالرجل المعكوسة وكرر"],["Stand in a split-stance lunge with knees bent.","Jump up and switch your legs in mid-air.","Land softly in a lunge with opposite legs, then repeat."]],"Seated_Band_Hamstring_Curl":[["اقعد وثبّت الباند حوالين كاحلك ورجلك مفرودة قدامك","اسحب كعبك لتحت وورا ضد مقاومة الباند وثني الركبة","ارجع ببطء لحد ما رجلك تتفرد وماتقفلش الركبة بعنف"],["Sit with a band anchored around your ankle and leg extended forward.","Curl your heel down and back against the band's resistance.","Return slowly until the leg is straight without locking the knee hard."]],"Seated_Barbell_Military_Press":[["اقعد على بنش بظهر وامسك البار بقبضة أعرض من الكتف عند مستوى الكتف","ادفع البار لفوق لحد ما دراعك يتفرد فوق راسك","نزّل البار ببطء لمستوى الذقن وضهرك مسنود"],["Sit on a bench with back support, gripping the bar slightly wider than shoulders at shoulder height.","Press the bar overhead until arms are extended.","Lower slowly to chin level with your back supported."]],"Seated_Barbell_Twist":[["اقعد على بنش وحط بار خفيف على كتفك ورا رقبتك وضهرك مفرود","لف جذعك لجنب ببطء وبطنك مشدودة","لف للجنب التاني وحافظ على الحوض ثابت"],["Sit on a bench with a light bar across your upper back, spine straight.","Rotate your torso slowly to one side, abs tight.","Rotate to the other side, keeping your hips still."]],"Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension":[["اقعد على بنش وانحني لقدام وامسك دامبل بإيد واحدة وكوعك جنب جسمك","افرد الدراع لورا لحد ما تتفرد بالكامل وشد الترايسبس","ارجع ببطء وكوعك ثابت وضهرك مفرود"],["Sit on a bench, lean forward, holding a dumbbell in one hand with your elbow by your side.","Extend your arm backward until it's straight, squeezing the triceps.","Return slowly keeping your elbow fixed and back flat."]],"Seated_Bent-Over_Rear_Delt_Raise":[["اقعد على بنش وانحني لقدام وامسك دامبل في كل إيد وصدرك قريب من فخذك","ارفع الدامبل للجنب لحد مستوى الكتف وكوعك مثني شوية","نزّلهم ببطء وماتشدش بالرقبة"],["Sit on a bench, bend forward, holding a dumbbell in each hand with chest near your thighs.","Raise the dumbbells out to shoulder height, elbows slightly bent.","Lower slowly without straining your neck."]],"Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension":[["اقعد على بنش وانحني لقدام وامسك دامبل في كل إيد وكوعك جنب جسمك","افرد الدراعين لورا لحد ما يتفردوا بالكامل وشد الترايسبس","ارجع ببطء وكوعك ثابت وضهرك مفرود"],["Sit on a bench, lean forward, holding a dumbbell in each hand with elbows by your sides.","Extend both arms backward until straight, squeezing the triceps.","Return slowly with your elbows fixed and back flat."]],"Seated_Biceps":[["اقعد على الأرض وحط إيدك وراك وكفوفك لتحت وصوابعك لورا","ابعد أردافك لقدام ببطء لحد ما تحس بشد في البايسبس","ثبّت 20-30 ثانية وماتضغطش لو حسيت بألم في الكتف"],["Sit on the floor with hands behind you, palms down, fingers pointing back.","Slide your hips forward slowly until you feel a biceps stretch.","Hold 20-30 seconds and stop if you feel shoulder pain."]],"Seated_Cable_Shoulder_Press":[["اقعد على بنش بظهر بين كابلين وامسك المقابض عند مستوى الكتف","ادفع المقابض لفوق لحد ما دراعك يتفرد فوق راسك","نزّل المقابض ببطء وماتقوّسش ضهرك"],["Sit on a bench between low cables, holding the handles at shoulder height.","Press the handles overhead until arms are extended.","Lower slowly without arching your back."]],"Seated_Calf_Stretch":[["اقعد على الأرض ورجلك مفرودة قدامك ولف شريط حوالين مشط قدمك","اسحب القدم ناحيتك مع الحفاظ على الركبة مفرودة","ثبّت 20-30 ثانية وبدّل الرجل"],["Sit with one leg extended and a band or towel looped around the ball of your foot.","Pull your foot toward you, keeping the knee straight.","Hold 20-30 seconds, then switch legs."]],"Seated_Close-Grip_Concentration_Barbell_Curl":[["اقعد على بنش وامسك البار بقبضة ضيقة وكوعك على فخذك الداخلي","اثني الكوع وارفع البار لفوق لحد ما تحس بانقباض البايسبس","نزّل ببطء لحد ما دراعك يتفرد تقريبا"],["Sit on a bench, grip the bar close, elbows against inner thighs.","Curl the bar up until your biceps are fully contracted.","Lower slowly until your arms are nearly straight."]],"Seated_Dumbbell_Curl":[["اقعد على بنش وامسك دامبل في كل إيد وكفوفك لقدام ودراعك مفرود","اثني الكوع وارفع الدامبل لحد الكتف وكوعك ثابت","نزّل ببطء وماتميلش جسمك لورا"],["Sit on a bench holding dumbbells with palms forward and arms extended.","Curl the dumbbells up to shoulder level, elbows fixed.","Lower slowly without leaning back."]],"Seated_Dumbbell_Inner_Biceps_Curl":[["اقعد على بنش وامسك دامبل بقبضة واسعة وكفوفك لقدام","اثني الكوع وارفع الدامبل مع لف الكف لبرا شوية","نزّل ببطء وحافظ على كوعك جنب جسمك"],["Sit on a bench holding dumbbells with palms forward.","Curl up while turning your palms slightly outward.","Lower slowly, keeping your elbows by your sides."]],"Seated_Dumbbell_Palms-Down_Wrist_Curl":[["اقعد وسند ساعديك على فخذك وكفوفك لتحت ماسكين الدامبل والرسغ برا الركبة","ارفع الرسغ لفوق بأقصى مدى وساعدك ثابت","نزّل الدامبل ببطء لحد ما تحس بشد في الساعد"],["Sit with forearms on your thighs, palms down holding dumbbells, wrists past your knees.","Extend your wrists upward as far as possible, forearms still.","Lower slowly until you feel a forearm stretch."]],"Seated_Dumbbell_Press":[["اقعد على بنش بظهر وامسك دامبل عند الكتف وكفوفك لقدام","ادفع الدامبل لفوق لحد ما دراعك يتفرد فوق راسك","نزّلهم ببطء لمستوى الكتف وماتقفلش الكوع بعنف"],["Sit on a bench with back support, holding dumbbells at shoulder height, palms forward.","Press the dumbbells overhead until arms are extended.","Lower slowly to shoulder level without locking elbows hard."]],"Seated_Flat_Bench_Leg_Pull-In":[["اقعد على حافة بنش مسطح وامسك الحافة وارجع جسمك لورا شوية وإرفع رجلك","اسحب ركبك ناحية صدرك وشد البطن","افرد رجلك ببطء وماتسيبش ضهرك يقوّس"],["Sit on the edge of a flat bench, grip it, lean back slightly with legs extended.","Pull your knees toward your chest, tightening your abs.","Extend your legs slowly without arching your back."]],"Seated_Floor_Hamstring_Stretch":[["اقعد على الأرض ورجلك مفرودة قدامك والتانية مثنية","ميّل جذعك لقدام من الحوض ومد إيدك ناحية القدم","ثبّت 20-30 ثانية وضهرك مفرود وبدّل الرجل"],["Sit on the floor with one leg extended and the other bent.","Hinge forward from the hips, reaching toward your foot.","Hold 20-30 seconds with a flat back, then switch legs."]],"Seated_Front_Deltoid":[["اقعد على الأرض وحط إيدك وراك وكفوفك لتحت","ابعد أردافك لقدام ببطء وافتح صدرك","ثبّت 20-30 ثانية وبلاش ألم حاد في الكتف"],["Sit with hands behind you, palms down on the floor.","Slide your hips forward slowly and open your chest.","Hold 20-30 seconds, stopping if you feel sharp shoulder pain."]],"Seated_Glute":[["اقعد على الأرض وحط كاحل رجل على ركبة الرجل التانية","اسحب ركبتك ناحية صدرك بلطف مع ضهر مفرود","ثبّت 20-30 ثانية وبدّل الرجل"],["Sit on the floor and cross one ankle over the opposite knee.","Gently pull the knee toward your chest, keeping your back straight.","Hold 20-30 seconds, then switch legs."]],"Seated_Good_Mornings":[["اقعد على بنش والبار على ضهرك وقدمك ثابتة وضهرك مفرود","ميّل جذعك لقدام من الحوض لحد ما يبقى تقريبا موازي للأرض","ارجع لوضع الجلوس بضهر مفرود وماتقوّسش ضهرك"],["Sit on a bench with the bar across your back, feet planted, spine neutral.","Hinge forward from the hips until your torso is nearly parallel to the floor.","Return upright with a flat back; never round your spine."]],"Seated_Hamstring_and_Calf_Stretch":[["اقعد على الأرض ورجلك مفرودة ولف شريط حوالين مشط القدم","اسحب القدم ناحيتك مع ميل الجذع لقدام بضهر مفرود","ثبّت 20-30 ثانية وبدّل الرجل"],["Sit with one leg extended and a band or towel around the ball of your foot.","Pull your foot toward you while leaning forward with a flat back.","Hold 20-30 seconds, then switch legs."]],"Seated_Hamstring":[["اقعد على حافة كرسي وافرد رجل قدامك والكعب على الأرض","ميّل جذعك لقدام من الحوض وضهرك مفرود","ثبّت 20-30 ثانية وبدّل الرجل"],["Sit on the edge of a chair with one leg extended, heel on the floor.","Hinge forward from the hips, keeping your back flat.","Hold 20-30 seconds, then switch legs."]],"Seated_Head_Harness_Neck_Resistance":[["اقعد على بنش وركّب الهارنس على راسك وصل بالكابل أو الوزن","اثني رقبتك أو ميّلها ببطء ضد المقاومة بحركة صغيرة","ارجع ببطء وتحكم وماتستخدمش وزن ثقيل"],["Sit on a bench wearing the head harness attached to a light cable or weight.","Move your neck slowly against the resistance in a small range.","Return slowly and under control, using only light weight."]],"Seated_Leg_Tucks":[["اقعد على حافة بنش وامسك الحافة وارجع جسمك لورا شوية ورجلك مفرودة","اسحب ركبك ناحية صدرك وشد بطنك","افرد رجلك ببطء وماتسيبش ضهرك يقوّس"],["Sit on the edge of a bench, grip it, lean back slightly with legs extended.","Pull your knees toward your chest, tightening your abs.","Extend your legs slowly without arching your back."]],"Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl":[["اقعد وسند ساعد على فخذك وكفك لتحت ماسك دامبل والرسغ برا الركبة","ارفع الرسغ لفوق بأقصى مدى وساعدك ثابت","نزّل الدامبل ببطء لحد ما تحس بشد في الساعد"],["Sit with one forearm on your thigh, palm down holding a dumbbell, wrist past your knee.","Extend your wrist upward as far as possible, forearm still.","Lower slowly until you feel a forearm stretch."]],"Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl":[["اقعد وسند ساعد على فخذك وكفك لفوق ماسك دامبل والرسغ برا الركبة","اثني الرسغ وارفع الدامبل لفوق بأقصى مدى","نزّل ببطء وساعدك ثابت على فخذك"],["Sit with one forearm on your thigh, palm up holding a dumbbell, wrist past your knee.","Curl the dumbbell up by flexing your wrist fully.","Lower slowly with your forearm staying still on your thigh."]],"Seated_Overhead_Stretch":[["اقعد بضهر مفرود وشبّك صوابعك وارفع دراعك فوق راسك","مد دراعك لفوق وميّل جذعك لجنب ببطء","ثبّت 20-30 ثانية وبدّل الجنب"],["Sit tall, interlace your fingers, and raise arms overhead.","Reach up and lean slowly to one side.","Hold 20-30 seconds, then switch sides."]],"Seated_Palm-Up_Barbell_Wrist_Curl":[["اقعد وسند ساعديك على فخذك وكفوفك لفوق ماسكين البار والرسغ برا الركبة","اثني الرسغ وارفع البار لفوق بأقصى مدى","نزّل البار ببطء وساعدك ثابت"],["Sit with forearms on your thighs, palms up holding the bar, wrists past your knees.","Curl the bar up by flexing your wrists fully.","Lower slowly with your forearms still."]],"Seated_Palms-Down_Barbell_Wrist_Curl":[["اقعد وسند ساعديك على فخذك وكفوفك لتحت ماسكين البار والرسغ برا الركبة","ارفع الرسغ لفوق بأقصى مدى وساعدك ثابت","نزّل البار ببطء لحد ما تحس بشد في الساعد"],["Sit with forearms on your thighs, palms down holding the bar, wrists past your knees.","Extend your wrists upward as far as possible, forearms still.","Lower slowly until you feel a forearm stretch."]],"Seated_Side_Lateral_Raise":[["اقعد على بنش وامسك دامبل في كل إيد جنبك وضهرك مفرود","ارفع دراعك للجنب لحد مستوى الكتف وكوعك مثني شوية","نزّل ببطء وماتستخدمش زخم"],["Sit on a bench holding dumbbells at your sides, back straight.","Raise your arms out to shoulder height with slightly bent elbows.","Lower slowly without using momentum."]],"Seated_Triceps_Press":[["اقعد على بنش وامسك دامبل بالإيدين فوق راسك وكوعك لقدام","نزّل الدامبل ورا راسك بثني الكوع وكوعك ثابت","ادفع الدامبل لفوق لحد ما دراعك يتفرد"],["Sit on a bench holding one dumbbell overhead with both hands, elbows pointing forward.","Lower the dumbbell behind your head by bending your elbows.","Press back up until your arms are extended."]],"Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl":[["اقعد قدام كابل منخفض وامسك البار كفوف لفوق وساعدك على فخذك","اثني الرسغ وارفع البار بأقصى مدى وساعدك ثابت","نزّل ببطء ضد مقاومة الكابل"],["Sit facing a low pulley, holding the bar palms up with forearms on your thighs.","Curl the bar up by flexing your wrists fully, forearms still.","Lower slowly against the cable's resistance."]],"See-Saw_Press_Alternating_Side_Press":[["قف وامسك دامبل في كل إيد عند الكتف وكفوفك لقدام","ادفع دامبل لفوق بينما تنزّل الدامبل التاني بالتبادل","كرر بالتبادل وحافظ على بطنك مشدودة وضهرك مفرود"],["Stand holding dumbbells at shoulder height, palms forward.","Press one dumbbell overhead while lowering the other in alternating motion.","Continue alternating, keeping your core tight and back neutral."]],"Shotgun_Row":[["قف قدام كابل منخفض وامسك المقبض بإيد واحدة وضهرك مفرود وركبك مثنية","اسحب المقبض لجنبك وشد لوح الكتف","ارجع ببطء وماتلفش جسمك"],["Stand facing a low cable holding the handle with one hand, back flat, knees bent.","Pull the handle to your side, squeezing your shoulder blade.","Return slowly without twisting your torso."]],"Shoulder_Circles":[["قف بضهر مفرود ودراعك جنبك وكتفك مرتاحين","ارفع كتفك لفوق ثم لورا في دايرة كبيرة","كرر ببطء ثم اعكس اتجاه الدوران"],["Stand tall with arms at your sides and shoulders relaxed.","Roll your shoulders up and back in large circles.","Repeat slowly, then reverse the direction."]],"Shoulder_Press_-_With_Bands":[["قف على الباند وامسك الطرفين عند الكتف وكفوفك لقدام","ادفع الباند لفوق لحد ما دراعك يتفرد فوق راسك","نزّل ببطء لمستوى الكتف وماتقوّسش ضهرك"],["Stand on a band holding the ends at shoulder height, palms forward.","Press up until your arms are extended overhead.","Lower slowly to shoulder level without arching your back."]],"Shoulder_Raise":[["قف بضهر مفرود ودراعك جنبك","ارفع كتفك لأعلى ناحية ودانك وثبّت ثانية","نزّلهم ببطء وارتاح"],["Stand tall with arms at your sides.","Raise your shoulders toward your ears and hold for a second.","Lower them slowly and relax."]],"Shoulder_Stretch":[["قف وارفع دراع قدام صدرك بشكل مفرود","استخدم الدراع التاني واسحبه ناحية صدرك بلطف","ثبّت 20-30 ثانية وبدّل الدراع"],["Stand and bring one arm straight across your chest.","Use the other arm to gently pull it closer.","Hold 20-30 seconds, then switch arms."]],"Side-Lying_Floor_Stretch":[["اتمدد على جنبك على الأرض وارفع دراعك فوق راسك","مد جسمك من الكاحل لأطراف الصوابع وخد نفس عميق","ثبّت 20-30 ثانية وبدّل الجنب"],["Lie on your side on the floor with your top arm overhead.","Lengthen your body from ankles to fingertips and breathe deeply.","Hold 20-30 seconds, then switch sides."]],"Side_Hop-Sprint":[["قف في وضع جاهز وركبك مثنية شوية","اقفز جانبيا بسرعة بقدم واحدة ثم انطلق جري سريع","هدّي السرعة تدريجيا وارجع لوضع البداية"],["Stand in an athletic stance with slightly bent knees.","Hop sideways quickly, then sprint forward immediately.","Slow down gradually and return to the start."]],"Side_Jackknife":[["اتمدد على جنبك وإيدك فوق راسك ورجلك مفرودة","ارفع رجليك وجذعك في نفس الوقت وشد بطنك الجانبية","نزّل ببطء وحافظ على الحركة بتحكم"],["Lie on your side with your arm overhead and legs straight.","Lift your legs and upper body together, squeezing your side abs.","Lower slowly under control."]],"Side_Laterals_to_Front_Raise":[["قف وامسك دامبل في كل إيد جنبك وكوعك مثني شوية","ارفع الدامبل للجنب لحد الكتف ثم نزّلهم وارفعهم لقدام","نزّل ببطء وماتستخدمش زخم"],["Stand holding dumbbells at your sides with slightly bent elbows.","Raise them out to the side to shoulder height, lower, then raise them to the front.","Lower slowly without using momentum."]],"Side_Leg_Raises":[["اتمدد على جنبك ورجلك مفرودة وضهرك مفرود","ارفع الرجل العليا لفوق لحد ما تحس بالأرداف تشتغل","نزّلها ببطء وكرر ثم بدّل الجنب"],["Lie on your side with legs straight and body in a line.","Lift your top leg until you feel your glutes working.","Lower slowly and repeat, then switch sides."]],"Side_Lying_Groin_Stretch":[["اتمدد على جنبك وثني الرجل العلوية وحط ركبتها على الأرض قدامك","افرد الرجل السفلية وارفعها لفوق ببطء","ثبّت 20-30 ثانية وبدّل الجنب"],["Lie on your side, bend the top knee and place it on the floor in front.","Raise the bottom leg slowly until you feel an inner-thigh stretch.","Hold 20-30 seconds, then switch sides."]],"Side_Neck_Stretch":[["اقعد أو قف بضهر مفرود وكتفك مرتاحين","ميّل راسك بلطف ناحية كتفك وساعد بإيدك من غير شد قوي","ثبّت 20-30 ثانية وبدّل الجنب"],["Sit or stand tall with shoulders relaxed.","Tilt your head gently toward one shoulder, helping lightly with your hand.","Hold 20-30 seconds, then switch sides."]],"Side_Standing_Long_Jump":[["قف جنب الخط وركبك مثنية وإيدك للجنب","اقفز جانبيا لأبعد مسافة بقدمين مع تمرجح دراعك","انزل بنعومة مع ثني الركبة وحافظ على توازنك"],["Stand sideways to a line with bent knees and arms ready.","Jump sideways as far as you can using both legs and arm swing.","Land softly with bent knees and hold your balance."]],"Side_To_Side_Chins":[["امسك بار العقلة بقبضة أعرض من الكتف وجسمك متعلق","اسحب نفسك لفوق ناحية إيد واحدة ثم انتقل للجنب التاني","نزّل ببطء لحد ما دراعك يتفرد"],["Grip a pull-up bar wider than shoulders and hang with arms extended.","Pull up toward one hand, then shift across to the other side.","Lower slowly until arms are straight."]],"Side_Wrist_Pull":[["قف أو اقعد ومد دراع قدامك وكفك لتحت","امسك صوابعك بإيدك التانية واسحبها بلطف لورا","ثبّت 20-30 ثانية وبدّل الدراع"],["Stand or sit and extend one arm in front, palm down.","Gently pull your fingers back with the other hand.","Hold 20-30 seconds, then switch arms."]],"Side_to_Side_Box_Shuffle":[["قف جنب صندوق وركبك مثنية وإيدك جاهزة","اتحرك جانبيا بسرعة فوق الصندوق وبالتبادل بخطوات صغيرة","حافظ على خطواتك خفيفة وضهرك مفرود"],["Stand beside a box with knees bent and hands ready.","Shuffle sideways over the box quickly with small steps.","Keep your steps light and your back flat."]],"Single-Arm_Cable_Crossover":[["قف في وضع المقاتل وامسك مقبض كابل عالي بإيد واحدة","اسحب المقبض لأسفل وللداخل قدام صدرك مع انقباض الصدر","ارجع ببطء وكوعك مثني شوية"],["Stand in a staggered stance holding a high cable handle in one hand.","Pull the handle down and across in front of your chest, squeezing your pecs.","Return slowly with a slight bend in the elbow."]],"Single-Arm_Linear_Jammer":[["قف في وضع المقاتل وامسك طرف البار على كتفك","ادفع البار لفوق وللأمام بقوة مع لف الجسم","نزّله ببطء لكتفك وحافظ على بطنك مشدودة"],["Stand in a staggered stance holding the end of the bar at your shoulder.","Drive the bar up and forward powerfully with a slight rotation.","Lower it to your shoulder under control, core braced."]],"Single-Arm_Push-Up":[["خد وضع الضغط ورجلك أعرض من الكتف وإيد واحدة تحتك والتانية خلف ضهرك","انزل بصدرك ببطء وجسمك مستقيم","ادفع لفوق لحد ما دراعك يتفرد وماتلفش وسطك"],["Start in a push-up position with feet wide, one hand on the floor and the other behind your back.","Lower your chest slowly, keeping your body straight.","Press back up until your arm is straight, without twisting your hips."]],"Single-Cone_Sprint_Drill":[["قف خلف خط البداية وقدامك قمع على مسافة محددة","انطلق بأقصى سرعة ناحية القمع ولف حوله","اجري راجع لخط البداية وخد نفسك بين التكرارات"],["Stand behind the start line with a cone placed ahead.","Sprint to the cone and turn around it.","Sprint back to the start and rest between reps."]],"Single-Leg_High_Box_Squat":[["قف على صندوق عالي بوقفة رجل واحدة والرجل التانية مرفوعة","انزل ببطء بثني ركبة الرجل الثابتة وضهرك مفرود","اطلع بدفع الأرض وافرد الركبة وحافظ على التوازن"],["Stand on a high box on one leg with the other leg lifted.","Lower slowly by bending the standing knee, back straight.","Drive up through your foot, extending the knee and keeping balance."]],"Single-Leg_Hop_Progression":[["قف على رجل واحدة وركبتك مثنية شوية","اقفز لقدام لمسافة قصيرة ثم زوّد المسافة تدريجيا","انزل بنعومة على نفس الرجل وركبتك مثنية"],["Stand on one leg with a slight knee bend.","Hop forward a short distance, then progress to longer hops.","Land softly on the same leg with a bent knee."]],"Single-Leg_Lateral_Hop":[["قف على رجل واحدة وركبتك مثنية شوية","اقفز جانبيا لمسافة قصيرة على نفس الرجل","انزل بنعومة وثبّت قبل القفزة التالية"],["Stand on one leg with a slight knee bend.","Hop sideways a short distance on the same leg.","Land softly and stabilize before the next hop."]],"Single-Leg_Leg_Extension":[["اقعد على جهاز الاكستنشن واضبط المخدة على كاحلك وارفع رجل واحدة","افرد ركبتك لحد ما رجلك تتفرد وشد الفخذ الأمامي","نزّل ببطء ماتقفلش الركبة بعنف"],["Sit on the leg extension machine with the pad on one ankle.","Extend your knee until the leg is straight, squeezing your quads.","Lower slowly without locking the knee hard."]],"Single-Leg_Stride_Jump":[["قف على رجل واحدة وركبتك مثنية شوية","اقفز لقدام بخطوة واسعة من نفس الرجل وبتمرجح دراعك","انزل بنعومة على نفس الرجل وركبتك مثنية"],["Stand on one leg with a slight knee bend.","Bound forward in a long stride off that leg, swinging your arms.","Land softly on the same leg with a bent knee."]],"Single_Dumbbell_Raise":[["قف وامسك دامبل واحد بالإيدين قدام فخذك وضهرك مفرود","ارفع الدامبل لقدام لحد مستوى الكتف أو فوق بدراع مفرودة تقريبا","نزّل ببطء وماتستخدمش زخم"],["Stand holding one dumbbell with both hands in front of your thighs, back straight.","Raise the dumbbell forward to shoulder height or above with nearly straight arms.","Lower slowly without using momentum."]],"Single_Leg_Butt_Kick":[["قف على رجل واحدة وركبتك مثنية شوية وإيدك جنبك","ارفع كعب الرجل الثانية ناحية أردافك بسرعة","بدّل الرجل واحتفظ بتوازنك وجسمك مفرود"],["Stand on one leg with a slight knee bend and arms at your sides.","Kick your other heel quickly toward your glutes.","Switch legs, keeping your balance and body upright."]],"Single_Leg_Glute_Bridge":[["اتمدد على ضهرك وركبك مثنية وقدمك على الأرض ورجل مرفوعة","ارفع أردافك لفوق بالضغط على كعب الرجل الثابتة","نزّل ببطء وماتقوّسش ضهرك"],["Lie on your back with knees bent, feet flat and one leg lifted.","Raise your hips by pressing through the heel of the planted foot.","Lower slowly without arching your back."]],"Single_Leg_Push-off":[["قف على رجل واحدة وارتكز على صندوق بالرجل التانية","ادفع الأرض بقوة بالرجل العليا وارتفع لفوق","انزل بنعومة وثبّت قبل التكرار"],["Stand with one foot on a box and the other leg ready to drive.","Push off the box forcefully with the top leg and rise up.","Land softly and stabilize before the next rep."]],"Sit_Squats":[["قف بقدمين أعرض من الكتف وإيدك قدامك","انزل بأردافك لورا لحد ما تقعد في وضع القرفصاء","ثبّت 20-30 ثانية ثم اطلع بحذر وضهرك مفرود"],["Stand with feet wider than shoulders and arms forward.","Sit your hips back into a deep squat position.","Hold 20-30 seconds, then rise carefully with a straight back."]],"Skating":[["قف على رجل واحدة وركبتك مثنية شوية وإيدك للجنب","اقفز جانبيا للرجل التانية وكأنك بتتزلج وبتمرجح إيدك","انزل بنعومة وثبّت قبل القفزة التالية"],["Stand on one leg with a slight knee bend and arms ready.","Bound sideways to the other leg like a speed skater, swinging your arms.","Land softly and stabilize before the next stride."]],"Sled_Drag_-_Harness":[["البس الهارنس وصل الزحافة وإنحني لقدام شوية","امشي لقدام بخطوات قوية وادفع الأرض وانت بتسحب الزحافة","هدّي الخطوة وارجع واقف وخد نفسك"],["Put on the harness attached to the sled and lean slightly forward.","Walk forward with strong strides, driving into the floor as you drag the sled.","Slow down, stand tall, and catch your breath."]],"Sled_Overhead_Backward_Walk":[["امسك مقبض الزحافة فوق راسك بدراعات مفرودة وقف قدام الزحافة","امشي لورا بخطوات صغيرة وانت بتسحب الزحافة","وقّف وانزل المقبض بتحكم وماتقوّسش ضهرك"],["Hold the sled handle overhead with straight arms, facing the sled.","Walk backward in small steps, pulling the sled.","Stop and lower the handle under control without arching your back."]],"Sled_Overhead_Triceps_Extension":[["امسك حبل أو مقبض الزحافة فوق راسك بالإيدين وكوعك لقدام","ثني الكوع ورا راسك ثم افرد لحد ما دراعك يتفرد","ارجع ببطء وحافظ على كوعك ثابت"],["Hold a rope or handle attached to the sled overhead with both hands, elbows forward.","Bend your elbows behind your head, then extend until arms are straight.","Return slowly, keeping your elbows fixed."]],"Sled_Reverse_Flye":[["قف قدام الزحافة وامسك الحبال بإيدك وانحني من الحوض وضهرك مفرود","افتح دراعك للجنب وشد لوحي الكتف ورا","ارجع ببطء وكوعك مثني شوية"],["Stand facing the sled holding the ropes, hinged at the hips with a flat back.","Open your arms out to the sides, squeezing your shoulder blades.","Return slowly with slightly bent elbows."]],"Sled_Row":[["امسك حبال الزحافة بإيدك وإنحني من الحوض وضهرك مفرود","اسحب الحبال ناحية بطنك وشد لوحي الكتف ورا","ارجع ببطء وحافظ على ضهرك مفرود"],["Hold the sled ropes, hinged at the hips with a flat back.","Pull the ropes toward your abdomen, squeezing your shoulder blades.","Return slowly keeping your back flat."]],"Sledgehammer_Swings":[["امسك المطرقة بإيديك الاتنين وقف بوقفة ثابتة","اترجح بالمطرقة لفوق وبعدين اضرب الإطار بقوة","ارجع للوضع الأول وخلي ضهرك مفرود وبنفس الإيقاع"],["Grip the sledgehammer with both hands, feet shoulder-width apart.","Swing it up overhead, then drive it down onto the tire.","Reset with a flat back and repeat at a steady rhythm."]],"Smith_Incline_Shoulder_Raise":[["اضبط البنش مائل وامسك البار بقبضة بعرض الكتف","ارفع البار لقدام لحد مستوى الكتف بدراعين شبه مفرودين","نزّله ببطء وخلي صدرك ثابت على البنش"],["Set the bench incline and grip the bar shoulder-width.","Raise the bar forward to shoulder height with arms nearly straight.","Lower slowly, keeping your chest anchored on the bench."]],"Smith_Machine_Behind_the_Back_Shrug":[["وقف قدام البار ومسكه ورا ضهرك بقبضة بعرض الحوض","ارفع كتافك لفوق ناحية ودانك من غير ما تلف","نزّلهم ببطء وخلي دراعاتك مفرودة وضهرك مستقيم"],["Stand in front of the bar and hold it behind you, hip-width grip.","Shrug your shoulders straight up toward your ears, no rolling.","Lower slowly with arms straight and back upright."]],"Smith_Machine_Bent_Over_Row":[["امسك البار وانحني من الورك وضهرك مفرود وركبك مثنية شوية","اسحب البار ناحية أسفل صدرك وشد لوحي الكتف","نزّله ببطء لحد ما دراعك تتفرد وماتدورش ضهرك"],["Grip the bar, hinge at the hips with a flat back, knees soft.","Pull the bar toward your lower chest, squeezing your shoulder blades.","Lower under control until arms extend; never round your back."]],"Smith_Machine_Calf_Raise":[["وقف تحت البار على حرف خطوة بمشط رجلك وركبك شبه مفرودة","ارفع كعبك لأعلى قدر ما تقدر وشد السمانة","نزّل كعبك ببطء لحد ما تحس بشد في السمانة"],["Stand under the bar with balls of your feet on a step, knees nearly straight.","Rise onto your toes as high as you can and squeeze your calves.","Lower your heels slowly until you feel a calf stretch."]],"Smith_Machine_Close-Grip_Bench_Press":[["ارقد على البنش وامسك البار بقبضة ضيقة بعرض الكتف تقريبًا","فك البار ونزّله ببطء لحد أسفل صدرك ومرفقك قريب من جسمك","ادفعه لفوق لحد ما تفرد دراعك من غير قفل المرفق"],["Lie on the bench and grip the bar about shoulder-width or slightly narrower.","Unrack and lower to your lower chest, elbows tucked close.","Press up until arms are straight without locking the elbows."]],"Smith_Machine_Decline_Press":[["اضبط البنش منخفض وارقد وامسك البار بقبضة أعرض من الكتف","فك البار ونزّله ببطء لحد أسفل الصدر","ادفعه لفوق لحد ما تفرد دراعك من غير قفل المرفق"],["Set the bench to decline, lie back, grip the bar wider than shoulders.","Unrack and lower the bar slowly to your lower chest.","Press up until arms are straight without locking the elbows."]],"Smith_Machine_Hang_Power_Clean":[["وقف قدام البار وامسكه ونزّله لحد فوق ركبتك وضهرك مفرود","اندفع بالحوض والرجلين وشرّاج الكتف وارفع البار لمستوى الكتف","استقبل البار على كتفك بركب مثنية شوية وبعدين وقف عدل"],["Stand at the bar, lower it to just above the knees with a flat back.","Drive hips and legs explosively, shrug, and pull the bar to shoulder height.","Catch it on your shoulders with soft knees, then stand tall."]],"Smith_Machine_Hip_Raise":[["ارقد على ضهرك أو علّق نفسك وإيديك ثابتة وركبك مثنية","ارفع حوضك لفوق ناحية صدرك بتحكم من غير تأرجح","نزّله ببطء وخلي بطنك مشدودة طول الحركة"],["Lie on your back or hang securely, hands fixed, knees bent.","Curl your hips up toward your chest with control, no swinging.","Lower slowly and keep your abs tight throughout."]],"Smith_Machine_Incline_Bench_Press":[["اضبط البنش مائل وارقد وامسك البار بقبضة أعرض من الكتف","فك البار ونزّله ببطء لحد أعلى الصدر","ادفعه لفوق لحد ما تفرد دراعك من غير قفل المرفق"],["Set the bench to incline, lie back, grip the bar wider than shoulders.","Unrack and lower the bar slowly to your upper chest.","Press up until arms are straight without locking the elbows."]],"Smith_Machine_Leg_Press":[["ارقد على ضهرك تحت البار وحط رجلك عليه بعرض الكتف","فك الأمان وانزل بركبك ببطء لحد ما تقارب صدرك","ادفع بكعبك لفوق من غير قفل الركبة وضهرك لازق في الأرض"],["Lie on your back under the bar and place feet on it shoulder-width.","Release the safeties and lower your knees slowly toward your chest.","Push through your heels without locking knees, back flat on the floor."]],"Smith_Machine_One-Arm_Upright_Row":[["وقف قدام البار وامسكه بإيد واحدة والإيد التانية جنبك","اسحب البار لفوق ناحية دقنك ومرفقك أعلى من إيدك","نزّله ببطء لحد ما دراعك تتفرد وخلي ضهرك مستقيم"],["Stand facing the bar and grip it with one hand, other arm at your side.","Pull it up toward your chin, elbow leading above the hand.","Lower slowly until the arm is straight, keeping your back upright."]],"Smith_Machine_Pistol_Squat":[["وقف قدام البار ورجل واحدة مفرودة قدامك والتانية شايلة الوزن","انزل بالرجل الواحدة ببطء لحد ما تقعد قدر ما تقدر وضهرك مستقيم","ادفع بكعبك وقف مع الحفاظ على التوازن"],["Stand at the bar with one leg extended forward, the other bearing weight.","Lower slowly on one leg as deep as you can, back upright.","Drive through your heel to stand, keeping balance."]],"Smith_Machine_Reverse_Calf_Raises":[["وقف بكعبك على حرف خطوة ومشط رجلك لأعلى وايدك ماسكة البار","ارفع مشط رجلك لأعلى ناحية رجلك بتحكم","نزّله ببطء وخلي ركبك مفرودة من غير قفل"],["Stand with toes elevated on a step, heels down, hands on the bar.","Raise your toes up toward your shins with control.","Lower slowly, keeping knees soft and not locked."]],"Smith_Machine_Stiff-Legged_Deadlift":[["وقف قدام البار وامسكه بقبضة بعرض الكتف وركبك مثنية شوية","انزل بالبار على رجلك بحني الحوض لورا وضهرك مفرود","اطلع بشد الفخذ الخلفي والحوض لحد ما تقف عدل"],["Stand at the bar with a shoulder-width grip and slightly bent knees.","Hinge at the hips, sliding the bar down your legs with a flat back.","Drive hips forward to stand tall, squeezing your hamstrings and glutes."]],"Smith_Machine_Upright_Row":[["وقف قدام البار وامسكه بقبضة ضيقة بعرض الكتف تقريبًا","اسحب البار لفوق ناحية دقنك ومرفقك أعلى من إيدك","نزّله ببطء لحد ما دراعك تتفرد"],["Stand facing the bar with a narrow grip, about shoulder-width.","Pull it up toward your chin with elbows leading above hands.","Lower slowly until your arms are straight."]],"Smith_Single-Leg_Split_Squat":[["وقف قدام البار برجل قدامك والتانية ورا على بنش أو فوق مشطها","انزل بالركبة الورانية لحد قريب من الأرض وضهرك مستقيم","ادفع بكعب الرجل اللي قدام وقف من غير قفل الركبة"],["Stand at the bar with one foot forward, the other behind on a bench or toes.","Lower your back knee near the floor, torso upright.","Push through the front heel to stand without locking the knee."]],"Snatch_Balance":[["شيل البار على كتفك بقبضة واسعة وقدميك بعرض الحوض","اضغط البار لفوق وانزل في سكوات عميق وهو فوق راسك","وقف بالبار مثبت فوق راسك وإيدك مفرودة وضهرك مشدود"],["Rest the bar on your upper back, wide snatch grip, feet hip-width.","Press the bar overhead as you drop into a deep squat.","Stand up with the bar locked overhead, core tight."]],"Snatch_Deadlift":[["وقف قدام البار وامسكه بقبضة واسعة وضهرك مفرود وكتفك فوق البار","ارفع البار من الأرض بدفع الرجلين وضهرك ثابت","وقف عدل وشد الحوض وبعدين نزّله بتحكم"],["Stand at the bar with a wide grip, flat back, shoulders over the bar.","Lift by driving through the legs, keeping your back flat.","Stand tall, squeeze your glutes, then lower with control."]],"Snatch_Pull":[["وقف قدام البار وامسكه بقبضة واسعة وضهرك مفرود","اسحب البار من الأرض بقوة وابقى مسافة قريبة من جسمك لحد الصدر","نزّله بتحكم لحد الأرض وضهرك مستقيم"],["Stand at the bar with a wide grip and a flat back.","Pull explosively from the floor, keeping the bar close, to chest height.","Lower under control to the floor with your back flat."]],"Snatch_Shrug":[["امسك البار بقبضة سناتش واسعة وانت واقف وهو عند أعلى الفخذ","اشرّج كتافك لفوق وارفع على مشط رجلك والدراعات مفرودة","نزّل بتحكم وارجع للوضع الأول وضهرك مستقيم"],["Hold the bar with a wide snatch grip at upper thigh, standing tall.","Shrug your shoulders up and rise onto your toes, arms straight.","Lower under control to the start with your back upright."]],"Snatch_from_Blocks":[["حط البار على بلوكات وامسكه بقبضة واسعة وضهرك مفرود","اسحب البار من البلوكات بقوة وارفعه فوق راسك في حركة واحدة","وقف بالبار ثابت فوق راسك ودراعك مفرودة"],["Set the bar on blocks and grip wide with a flat back.","Pull explosively off the blocks and throw it overhead in one motion.","Stand with the bar locked out overhead, arms straight."]],"Snatch":[["امسك البار بقبضة واسعة وضهرك مفرود وكتفك فوق البار","اسحب البار بقوة من الأرض وانزل تحته وارفعه فوق راسك","وقف بالبار ثابت فوق راسك ونزّله بتحكم"],["Grip the bar wide with a flat back and shoulders over the bar.","Pull explosively from the floor, drop under it, catch overhead.","Stand with it locked overhead, then lower with control."]],"Speed_Band_Overhead_Triceps":[["اربط الباند تحت رجلك وامسكه بإيديك ورا راسك ومرفقك لفوق","افرد دراعك لفوق بسرعة وانت ثابت المرفق","رجّع الباند ببطء ورا راسك وخلي بطنك مشدودة"],["Anchor the band under your foot and hold it behind your head, elbows up.","Extend your arms overhead quickly, keeping elbows still.","Return slowly behind your head, core braced."]],"Speed_Box_Squat":[["حط بوكس وراك وشيل البار على ضهرك ووقفتك أوسع من الكتف","اقعد على البوكس بتحكم وضهرك مفرود","اندفع لفوق بسرعة بكعبك وقف من غير قفل الركبة"],["Set a box behind you, bar on your back, stance wider than shoulders.","Sit back onto the box with control, keeping your back flat.","Drive up fast through your heels without locking your knees."]],"Speed_Squats":[["شيل البار على ضهرك ووقف بعرض الكتف وصدرك مفتوح","انزل في سكوات بتحكم لحد ما فخدك توازي الأرض","اندفع لفوق بسرعة وانت ثابت الركبة والضهر مستقيم"],["Rest the bar on your upper back, feet shoulder-width, chest up.","Squat down with control until thighs are parallel to the floor.","Drive up fast with knees tracking over toes and back flat."]],"Spell_Caster":[["وقف ماسك دامبل في إيديك الاتنين ودراعك مفرودة ورجليك أوسع من الكتف","لف الجذع والدامبل في قوس قطري من جنب لجنب فوق راسك","ارجع بنفس القوس وخلي بطنك مشدودة وركبك مثنية شوية"],["Hold a dumbbell in both hands, arms straight, feet wide.","Rotate your torso, swinging the dumbbell in a diagonal arc across your body.","Return along the same arc, core tight, knees slightly bent."]],"Spider_Crawl":[["خد وضع بلانك على إيديك ورجلك وجسمك مستقيم","ازحف لقدام وارفع ركبة ناحية كوعك من نفس الجنب","بدّل الجنب واستمر وحافظ على الحوض ثابت"],["Start in a plank on hands and toes, body straight.","Crawl forward, bringing one knee toward the same-side elbow.","Alternate sides, keeping your hips steady."]],"Spinal_Stretch":[["اقعد على الأرض ورجلك مفرودة قدامك وضهرك مستقيم","لف جذعك وحط إيدك على الأرض ورا ضهرك أو على ركبتك","ثبّت 20-30 ثانية وتنفس بهدوء وبعدين بدّل الجنب"],["Sit on the floor with legs extended and back tall.","Twist your torso, hand on the floor behind you or on the opposite knee.","Hold 20-30 seconds, breathing calmly, then switch sides."]],"Split_Clean":[["وقف قدام البار وامسكه بقبضة بعرض الكتف وضهرك مفرود","اسحب البار بقوة لفوق وبدّل رجليك في وضع سبليت واستقبله على كتفك","اجمع رجليك ووقف عدل وبعدين نزّل البار بتحكم"],["Stand at the bar with a shoulder-width grip and flat back.","Pull explosively, split your feet, and catch the bar on your shoulders.","Bring your feet together, stand tall, then lower the bar with control."]],"Split_Jerk":[["شيل البار على كتفك قدام وقف بعرض الحوض وصدرك مفتوح","انزل شوية ثم اندفع بقوة وارفع البار وبدّل رجليك في وضع سبليت","ثبّت البار فوق راسك ورجّع رجليك واحدة واحدة"],["Rack the bar on your front shoulders, feet hip-width, chest up.","Dip slightly, drive up, and split your feet as you press overhead.","Lock the bar overhead, then bring your feet back together one at a time."]],"Split_Jump":[["وقف في وضع سبليت برجل قدام والتانية ورا وركبك مثنية","اقفز لفوق بقوة وبدّل رجليك في الهوا","انزل بنعومة على مشط رجلك وكرر وضهرك مستقيم"],["Stand in a split stance, one foot forward, knees bent.","Jump up explosively and switch legs in the air.","Land softly on the balls of your feet and repeat, torso upright."]],"Split_Snatch":[["امسك البار بقبضة واسعة وضهرك مفرود وكتفك فوق البار","اسحب البار بقوة وبدّل رجليك في وضع سبليت واستقبله فوق راسك","ثبّت البار وجمّع رجليك ووقف عدل"],["Grip the bar wide with a flat back, shoulders over the bar.","Pull explosively, split your feet, and catch the bar overhead.","Stabilize the bar, bring your feet together, and stand tall."]],"Split_Squats":[["وقف برجل قدام والتانية ورا بمسافة واسعة وإيدك على وسطك","انزل بالركبة الورانية لحد قريب من الأرض وضهرك مستقيم","ثبّت 20-30 ثانية تحت أو ارجع لفوق وبدّل الرجل"],["Stand with one foot far forward, the other back, hands on hips.","Lower your back knee toward the floor, torso upright.","Hold 20-30 seconds in the low position, or rise, then switch legs."]],"Squat_Jerk":[["شيل البار على كتفك قدام وقف بعرض الحوض وصدرك مفتوح","انزل شوية واندفع بقوة وارفع البار فوق راسك وانزل في سكوات وهو ثابت","وقف والبار مثبت فوق راسك وإيدك مفرودة"],["Rack the bar on your front shoulders, feet hip-width, chest up.","Dip, drive up, press the bar overhead, and drop into a squat.","Stand with the bar locked overhead and arms straight."]],"Squat_with_Bands":[["اربط الباند حوالين البار وشيل البار على ضهرك ووقف بعرض الكتف","انزل في سكوات بتحكم لحد ما فخدك توازي الأرض","اندفع لفوق بكعبك وركبك مع اتجاه صوابعك وضهرك مستقيم"],["Attach bands to the bar, rest it on your upper back, feet shoulder-width.","Squat down with control until thighs are parallel to the floor.","Drive up through your heels, knees tracking over toes, back flat."]],"Squat_with_Chains":[["علّق الجنازير في البار وشيل البار على ضهرك ووقف بعرض الكتف","انزل في سكوات بتحكم لحد ما فخدك توازي الأرض","اندفع لفوق بكعبك وضهرك مستقيم وصدرك مفتوح"],["Hang chains on the bar, rest it on your upper back, feet shoulder-width.","Squat down with control until thighs are parallel to the floor.","Drive up through your heels with a flat back and open chest."]],"Squat_with_Plate_Movers":[["حط منزلقات الأوزان تحت رجلك وشيل البار على ضهرك","انزل في سكوات بتحكم وضهرك مستقيم","اندفع لفوق وتحكم في الانزلاق وركبك مع اتجاه صوابعك"],["Place plate movers under your feet and rest the bar on your back.","Squat down with control, keeping your back flat.","Drive up, controlling any sliding, knees tracking over toes."]],"Squats_-_With_Bands":[["اقف على الباند وحطه على كتفك وقدميك بعرض الكتف","انزل في سكوات بتحكم لحد ما فخدك توازي الأرض","اندفع لفوق بكعبك وضهرك مستقيم من غير قفل الركبة"],["Stand on the band, loop it over your shoulders, feet shoulder-width.","Squat down with control until thighs are parallel to the floor.","Drive up through your heels, back flat, without locking your knees."]],"Standing_Alternating_Dumbbell_Press":[["وقف ماسك دامبل في كل إيد عند الكتف وبطنك مشدودة","اضغط دامبل واحد لفوق لحد ما تفرد دراعك","نزّله ببطء واضغط التاني وبدّل بالتناوب"],["Stand holding a dumbbell at each shoulder, core braced.","Press one dumbbell overhead until your arm is straight.","Lower it slowly and press the other, alternating sides."]],"Standing_Barbell_Calf_Raise":[["شيل البار على ضهرك ووقف بمشط رجلك على حرف خطوة أو على الأرض","ارفع كعبك لأعلى قدر ما تقدر وشد السمانة","نزّل كعبك ببطء لحد ما تحس بشد في السمانة"],["Rest the bar on your upper back, balls of your feet on a step or floor.","Rise onto your toes as high as you can and squeeze your calves.","Lower your heels slowly until you feel a calf stretch."]],"Standing_Barbell_Press_Behind_Neck":[["وقف وشيل البار على ضهرك بقبضة واسعة وبطنك مشدودة","اضغط البار لفوق راسك لحد ما تفرد دراعك","نزّله ببطء لحد ما يلمس كتفك وماتنزلش أبعد من كده"],["Stand with the bar on your upper back, wide grip, core tight.","Press the bar straight up overhead until your arms are straight.","Lower slowly to shoulder level, no lower, to protect your shoulders."]],"Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension":[["انحني من الورك وضهرك مفرود وماسك دامبل بإيد وإيدك التانية على بنش","ثبّت مرفقك جنبك وافرد دراعك ورا الدامبل","ارجع ببطء لحد ما مرفقك يتثني 90 درجة"],["Hinge at the hips with a flat back, one hand on a bench, dumbbell in the other.","Keep your elbow tucked and extend the arm back.","Return slowly until your elbow bends to 90 degrees."]],"Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension":[["انحني من الورك وضهرك مفرود وماسك دامبل في كل إيد ومرفقك جنبك","افرد دراعيك ورا الدامبل مع تثبيت المرفق","ارجع ببطء لحد ما مرفقك يتثني 90 درجة"],["Hinge at the hips with a flat back, a dumbbell in each hand, elbows tucked.","Extend both arms back, keeping elbows fixed.","Return slowly until your elbows bend to 90 degrees."]],"Standing_Biceps_Stretch":[["وقف عدل وافرد دراعك لورا وكفك لأسفل على حاجة ثابتة أو إيدك فاتحة","افرد دراعك وارفعه لحد ما تحس بشد في البايسبس","ثبّت 20-30 ثانية وبعدين بدّل الدراع"],["Stand tall and extend one arm behind you, palm down on a fixed surface.","Keep the arm straight and rotate away until you feel a biceps stretch.","Hold 20-30 seconds, then switch arms."]],"Standing_Bradford_Press":[["وقف وامسك البار عند الكتف بقبضة بعرض الكتف وبطنك مشدودة","اضغط البار لفوق راسك وبعدين نزّله ورا الرقبة بالتبادل مع قدام","كمل بالتبادل بحركة بطيئة وخلي ضهرك مستقيم"],["Stand holding the bar at your shoulders, shoulder-width grip, core tight.","Press it overhead, then lower it behind the head, alternating front and back.","Continue the pattern slowly, keeping your back straight."]],"Standing_Cable_Lift":[["وقف جنب الكابل المرتفع وامسك المقبض بإيدين مفرودتين","اسحب الكابل قطري لحد فوق الجنب الثاني وبطنك مشدودة","ارجع ببطء وخلي الحوض ثابت وماتلفش بسرعة"],["Stand sideways to a high cable and hold the handle with both hands.","Pull diagonally across your body, upward past the opposite hip, core tight.","Return slowly, keeping hips stable and avoiding fast twisting."]],"Standing_Concentration_Curl":[["وقف وانحني شوية وماسك دامبل بإيد ودراعك مفرودة قدام","اثني الدراع لفوق ناحية كتفك وانت ثابت المرفق","نزّله ببطء لحد ما يتفرد وماتتأرجحش بجسمك"],["Stand and lean forward slightly, holding a dumbbell with arm hanging.","Curl the dumbbell up toward your shoulder, keeping your elbow still.","Lower slowly until the arm is straight, without swinging your body."]],"Standing_Dumbbell_Press":[["وقف ماسك دامبل في كل إيد عند الكتف وبطنك مشدودة","اضغط الدامبل لفوق لحد ما تفرد دراعك","نزّلهم ببطء لحد الكتف وخلي ضهرك مستقيم"],["Stand holding a dumbbell at each shoulder, core braced.","Press both dumbbells overhead until your arms are straight.","Lower slowly back to your shoulders, keeping your back straight."]],"Standing_Dumbbell_Reverse_Curl":[["وقف وماسك دامبل في كل إيد وكفك لأسفل ومرفقك جنبك","اثني دراعك لفوق وكفك لتحت وانت ثابت المرفق","نزّلهم ببطء لحد ما يتفرد دراعك"],["Stand holding a dumbbell in each hand, palms down, elbows tucked.","Curl the dumbbells up with palms facing down, elbows still.","Lower slowly until your arms are straight."]],"Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head":[["وقف ماسك دامبل في إيديك قدام فخدك ودراعك مفرودة","ارفع الدامبل قدامك بدراع مفرودة لحد فوق راسك","نزّلهم ببطء لحد الفخد وبطنك مشدودة وضهرك مستقيم"],["Stand holding dumbbells in front of your thighs, arms straight.","Raise them forward with straight arms until overhead.","Lower slowly to your thighs, core braced and back straight."]],"Standing_Dumbbell_Upright_Row":[["وقف ماسك دامبل في إيديك قدام فخدك بقبضة ضيقة","اسحب الدامبل لفوق ناحية دقنك ومرفقك أعلى من إيدك","نزّلهم ببطء لحد ما يتفرد دراعك"],["Stand holding dumbbells in front of your thighs.","Pull them up toward your chin, elbows leading above hands.","Lower slowly until your arms are straight."]],"Standing_Elevated_Quad_Stretch":[["وقف عدل وامسك حاجة ثابتة وثني ركبة وامسك كعبك ورا","اسحب كعبك ناحية الأرداف وخلي ركبتك لتحت وحوضك للأمام","ثبّت 20-30 ثانية وبعدين بدّل الرجل"],["Stand tall, hold a support, bend one knee, and grab your foot behind you.","Pull your heel toward your glutes, knee pointing down, hips forward.","Hold 20-30 seconds, then switch legs."]],"Standing_Front_Barbell_Raise_Over_Head":[["وقف وامسك البار قدام فخدك بقبضة بعرض الكتف ودراعك مفرودة","ارفع البار لقدام بدراع مفرودة لحد فوق راسك","نزّله ببطء لحد الفخد وبطنك مشدودة وضهرك مستقيم"],["Stand holding the bar in front of your thighs, shoulder-width grip, arms straight.","Raise the bar forward with straight arms until overhead.","Lower slowly to your thighs, core braced, back straight."]],"Standing_Gastrocnemius_Calf_Stretch":[["وقف قدام الحيط وإيدك عليه ورجل ورا مفرودة وكعبها على الأرض","اميل بجسمك لقدام لحد ما تحس بشد في السمانة","ثبّت 20-30 ثانية وبعدين بدّل الرجل"],["Stand facing a wall, hands on it, one leg back straight with heel down.","Lean forward until you feel a stretch in the calf.","Hold 20-30 seconds, then switch legs."]],"Standing_Hamstring_and_Calf_Stretch":[["وقف وحط كعب رجل واحدة على حاجة قدامك ورجلك مفرودة","اميل بضهرك مستقيم ناحية صوابعك وشد صوابعك ناحيتك","ثبّت 20-30 ثانية وبعدين بدّل الرجل"],["Stand and place one heel on a raised surface, leg straight.","Lean forward with a flat back and pull your toes toward you.","Hold 20-30 seconds, then switch legs."]],"Standing_Hip_Circles":[["وقف وإيدك على وسطك ورجلك بعرض الكتف وركبك مفرودة شوية","لف الحوض في دايرة كبيرة وبطيئة في اتجاه","اعمل نفس الدايرة في الاتجاه التاني وخلي كتفك ثابت"],["Stand with hands on hips, feet shoulder-width, knees soft.","Rotate your hips in a large, slow circle in one direction.","Repeat in the opposite direction, keeping your shoulders still."]],"Standing_Hip_Flexors":[["اقف في وضع سبليت برجل قدام وركبتك الورانية على الأرض أو قريبة منها","ادفع الحوض لقدام وخلي صدرك مرفوع وضهرك مستقيم","ثبّت 20-30 ثانية وبعدين بدّل الرجل"],["Get into a split stance, back knee on or near the floor.","Push your hips forward, keeping your chest up and back straight.","Hold 20-30 seconds, then switch legs."]],"Standing_Inner-Biceps_Curl":[["وقف وماسك دامبل في كل إيد وكفك لقدام ومرفقك جنبك","اثني دراعك لفوق وبرم الدامبل ناحية جوه وانت ثابت المرفق","نزّلهم ببطء لحد ما يتفرد دراعك"],["Stand holding a dumbbell in each hand, palms forward, elbows tucked.","Curl up, rotating the dumbbells inward, elbows still.","Lower slowly until your arms are straight."]],"Standing_Lateral_Stretch":[["وقف بعرض الكتف وارفع دراع فوق راسك","اميل بجسمك على الجنب ناحية التانية لحد ما تحس بشد في الجنب","ثبّت 20-30 ثانية وبعدين بدّل الجنب"],["Stand feet shoulder-width and raise one arm overhead.","Lean sideways to the opposite side until you feel a stretch along your side.","Hold 20-30 seconds, then switch sides."]],"Standing_Leg_Curl":[["وقف قدام الجهاز وحط كعب رجل واحدة تحت الوسادة وامسك المقبض","اثني ركبتك وارفع كعبك ناحية الأرداف بتحكم","نزّل الرجل ببطء لحد ما تتفرد وماتتأرجحش بجسمك"],["Stand at the machine with one heel under the pad, holding the handles.","Curl your heel toward your glutes with control.","Lower slowly until the leg is straight, without swinging your body."]],"Standing_Long_Jump":[["وقف بقدميك بعرض الكتف وانزل شوية ودراعك لورا","اقفز لقدام بأقصى قوة وإيدك بتتأرجح لقدام","انزل بنعومة بركب مثنية وثبّت"],["Stand feet shoulder-width, dip slightly, and swing your arms back.","Jump forward as far as you can, driving your arms forward.","Land softly with bent knees and hold your balance."]],"Standing_Low-Pulley_Deltoid_Raise":[["وقف جنب الكابل السفلي وامسك المقبض بالإيد البعيدة","ارفع دراعك جانبًا لحد مستوى الكتف ومرفقك مثني شوية","نزّله ببطء وماتتأرجحش بجسمك"],["Stand beside the low pulley and hold the handle with your far hand.","Raise your arm out to the side to shoulder height, elbow slightly bent.","Lower slowly without swinging your body."]],"Standing_Low-Pulley_One-Arm_Triceps_Extension":[["وقف قدام الكابل السفلي وامسك المقبض بإيد واحدة وارفعه فوق راسك ومرفقك لفوق","افرد دراعك لفوق وانت ثابت المرفق","ارجع ببطء لحد ما يتثني المرفق وبطنك مشدودة"],["Face away from the low pulley, hold the handle overhead with one hand, elbow up.","Extend your arm upward, keeping your elbow still.","Return slowly until the elbow bends, core braced."]],"Standing_Military_Press":[["وقف وامسك البار عند الكتف بقبضة بعرض الكتف وبطنك مشدودة","اضغط البار لفوق راسك لحد ما تفرد دراعك","نزّله ببطء لحد الكتف وماتقوّسش ضهرك"],["Stand holding the bar at your shoulders, shoulder-width grip, core tight.","Press the bar overhead until your arms are straight.","Lower slowly to your shoulders without arching your back."]],"Standing_Olympic_Plate_Hand_Squeeze":[["وقف وامسك طبق أولمبي بين إيديك بقبضة ماسكة الحافة","اضغط الطبق بقوة بين إيديك وشد البطن","ثبّت الضغط 10-15 ثانية وبعدين ارتاح"],["Stand holding an Olympic plate by its edges between both hands.","Squeeze the plate hard with your fingers and thumbs.","Hold the squeeze 10-15 seconds, then relax."]],"Standing_One-Arm_Cable_Curl":[["وقف قدام الكابل السفلي وامسك المقبض بإيد واحدة ومرفقك جنبك","اثني دراعك لفوق ناحية كتفك وانت ثابت المرفق","نزّله ببطء لحد ما يتفرد دراعك"],["Stand facing the low cable and hold the handle with one hand, elbow tucked.","Curl the handle toward your shoulder, elbow still.","Lower slowly until your arm is straight."]],"Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench":[["وقف وراء بنش مائل وإيدك الواحدة ماسكة دامبل ودراعك مفرودة فوق البنش","اثني دراعك لفوق ناحية كتفك وانت ثابت المرفق","نزّله ببطء لحد ما يتفرد دراعك وماتتأرجحش"],["Stand behind an incline bench, one arm extended over it holding a dumbbell.","Curl the dumbbell toward your shoulder, elbow still.","Lower slowly until the arm is straight, no swinging."]],"Standing_One-Arm_Dumbbell_Triceps_Extension":[["وقف وامسك دامبل بإيد واحدة وارفعه فوق راسك ومرفقك لفوق","نزّل الدامبل ورا راسك بثني المرفق وانت ثابت المرفق","افرد دراعك لفوق وماتفتحش المرفق لبرة"],["Stand holding a dumbbell in one hand, raised overhead, elbow up.","Lower it behind your head by bending only the elbow.","Extend your arm back up, keeping your elbow from flaring out."]],"Standing_Overhead_Barbell_Triceps_Extension":[["وقف وامسك البار فوق راسك بقبضة ضيقة ودراعك مفرودة","نزّل البار ورا راسك بثني المرفق وانت ثابت المرفق","افرد دراعك لفوق وخلي بطنك مشدودة وضهرك مستقيم"],["Stand holding the bar overhead with a narrow grip, arms straight.","Lower it behind your head by bending only your elbows.","Extend back up, core braced and back straight."]],"Standing_Palm-In_One-Arm_Dumbbell_Press":[["وقف وامسك دامبل بإيد واحدة عند الكتف وكفك لجوه","اضغط الدامبل لفوق لحد ما تفرد دراعك","نزّله ببطء لحد الكتف وخلي بطنك مشدودة"],["Stand holding one dumbbell at your shoulder, palm facing in.","Press it overhead until your arm is straight.","Lower slowly to your shoulder, core braced."]],"Standing_Palms-In_Dumbbell_Press":[["وقف ماسك دامبل في كل إيد عند الكتف وكفك لجوه","اضغط الدامبل لفوق لحد ما تفرد دراعك","نزّلهم ببطء لحد الكتف وخلي ضهرك مستقيم"],["Stand holding a dumbbell at each shoulder, palms facing in.","Press both dumbbells overhead until your arms are straight.","Lower slowly to your shoulders, keeping your back straight."]],"Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl":[["وقف وامسك البار ورا ضهرك بكفوف لأعلى ودراعك مفرودة","اثني رسغك لفوق وانت ثابت الدراع","نزّل البار ببطء لحد ما يتفرد الرسغ"],["Stand holding the bar behind you, palms up, arms straight.","Curl your wrists upward, keeping your forearms still.","Lower slowly until your wrists are extended."]],"Standing_Pelvic_Tilt":[["وقف وضهرك على الحيط وركبك مثنية شوية","اشد بطنك وإمال حوضك لأعلى وخلي أسفل ضهرك لازق في الحيط","ثبّت 5 ثواني وبعدين ارتاح وكرر"],["Stand with your back against a wall, knees slightly bent.","Brace your abs and tilt your pelvis up, flattening your lower back to the wall.","Hold 5 seconds, then relax and repeat."]],"Standing_Soleus_And_Achilles_Stretch":[["وقف قدام الحيط وإيدك عليه ورجل ورا وركبتها مثنية شوية","اميل بجسمك لقدام وكعبك على الأرض لحد ما تحس بشد في أسفل السمانة","ثبّت 20-30 ثانية وبعدين بدّل الرجل"],["Stand facing a wall, hands on it, back knee slightly bent.","Lean forward with your heel down until you feel a stretch low in the calf.","Hold 20-30 seconds, then switch legs."]],"Standing_Toe_Touches":[["وقف عدل بقدميك بعرض الحوض وركبك مفرودة شوية","انحني لقدام ببطء ووصل إيدك ناحية صوابعك","ثبّت 20-30 ثانية وبعدين ارجع ببطء وماتحاولش تشد بقوة"],["Stand tall, feet hip-width, knees slightly soft.","Fold forward slowly and reach your hands toward your toes.","Hold 20-30 seconds, then rise slowly without bouncing."]],"Standing_Towel_Triceps_Extension":[["وقف وامسك فوطة بإيديك الاتنين ورا راسك ومرفقك لفوق","افرد دراعك لفوق وشد الفوطة بين إيديك","ارجع ببطء لحد ما يتثني المرفق وخلي ضهرك مستقيم"],["Stand holding a towel with both hands behind your head, elbows up.","Extend your arms overhead, keeping tension on the towel.","Return slowly until your elbows bend, back straight."]],"Standing_Two-Arm_Overhead_Throw":[["وقف وامسك الكرة بإيديك الاتنين عند صدرك وقدميك بعرض الكتف","ارفع الكرة فوق راسك وارميها لقدام أو لورا بكل قوتك","ارجع للوضع الأول وجهّز لرمية جديدة وبطنك مشدودة"],["Stand holding a ball with both hands at your chest, feet shoulder-width.","Swing it overhead and throw it forward or back with full force.","Reset your stance, core braced, and prepare the next throw."]],"Star_Jump":[["وقف وقدميك مع بعض ودراعك جنبك وركبك مثنية شوية","اقفز لفوق وافتح رجليك ودراعك على شكل نجمة","انزل بنعومة على مشط رجلك وارجع للوضع الأول وكرر"],["Stand with feet together and arms at your sides, knees slightly bent.","Jump up, spreading your arms and legs into a star shape.","Land softly on your toes, return to start, and repeat."]],"Step-up_with_Knee_Raise":[["وقف قدام بنش أو خطوة وحط رجل واحدة كلها على البنش","اندفع بالرجل اللي على البنش وارفع الركبة التانية لفوق","نزّل ببطء وبدّل الرجل وخلي ضهرك مستقيم"],["Stand facing a bench with one foot fully on it.","Drive through that foot to stand, lifting the other knee up.","Step down slowly and alternate legs, back straight."]],"Step_Mill":[["اطلع على الجهاز وامسك الدرابزين بخفة وضهرك مستقيم","ابدأ الجهاز وامشي على السلالم بخطوات منتظمة","حافظ على وقفة مستقيمة وماتشدش الدرابزين بقوة"],["Step onto the machine, hold the rails lightly, back upright.","Start the machine and climb the steps at a steady pace.","Stay upright and don't lean heavily on the rails."]],"Stiff_Leg_Barbell_Good_Morning":[["شيل البار على ضهرك ووقف بعرض الكتف وركبك مثنية شوية","انحني من الورك لحد ما ضهرك يوازي الأرض وضهرك مفرود","اطلع بدفع الحوض لقدام وماتدورش ضهرك"],["Rest the bar on your upper back, feet shoulder-width, knees slightly bent.","Hinge at the hips until your torso is near parallel, back flat.","Drive hips forward to stand, never rounding your back."]],"Stomach_Vacuum":[["وقف أو اقعد وايدك على ركبتك وخد نفس عميق","ازفر كل الهوا واسحب بطنك لجوه ناحية العمود الفقري","ثبّت 10-15 ثانية وبعدين ارتاح وتنفس عادي"],["Stand or kneel, hands on thighs, and take a deep breath.","Exhale fully and pull your belly in toward your spine.","Hold 10-15 seconds, then relax and breathe normally."]],"Straight-Arm_Dumbbell_Pullover":[["ارقد بضهرك على بنش وامسك دامبل بإيديك فوق صدرك ودراعك شبه مفرودة","نزّل الدامبل ورا راسك بدراع مفرودة وانت بتحس بشد في الضهر","ارجع بالدامبل فوق صدرك بتحكم وبطنك مشدودة"],["Lie on a bench holding one dumbbell over your chest, arms nearly straight.","Lower it back behind your head with straight arms until you feel a lat stretch.","Return it over your chest with control, core braced."]],"Straight_Bar_Bench_Mid_Rows":[["انحني من الورك على بنش وامسك البار بقبضة بعرض الكتف وضهرك مفرود","اسحب البار ناحية وسطك وشد لوحي الكتف","نزّله ببطء لحد ما يتفرد دراعك"],["Lean over a bench, grip the bar shoulder-width, back flat.","Pull the bar toward your midsection, squeezing your shoulder blades.","Lower slowly until your arms are straight."]],"Straight_Raises_on_Incline_Bench":[["اقعد أو ارقد على بنش مائل وامسك البار بقبضة بعرض الكتف ودراعك مفرودة","ارفع البار لقدام بدراع مفرودة لحد مستوى الكتف","نزّله ببطء وخلي صدرك ثابت على البنش"],["Sit or lie on an incline bench, grip the bar shoulder-width, arms straight.","Raise the bar forward with straight arms to shoulder height.","Lower slowly, keeping your chest on the bench."]],"Stride_Jump_Crossover":[["وقف بوقفة مفتوحة وركبك مثنية شوية وإيدك جنبك","اقفز عرضيًا وقاطع رجليك في الهوا","انزل بنعومة على مشط رجلك وكرر في الاتجاه التاني"],["Stand in a wide stance, knees slightly bent, arms at your sides.","Jump sideways, crossing your legs in the air.","Land softly on the balls of your feet and repeat to the other side."]],"Sumo_Deadlift_with_Bands":[["اربط الباند على البار وقف بوقفة سومو واسعة ورجلك للخارج","امسك البار بقبضة ضيقة وضهرك مفرود وارفعه بدفع الرجلين","وقف عدل وشد الحوض وبعدين نزّله بتحكم"],["Attach bands to the bar and stand in a wide sumo stance, toes out.","Grip the bar inside your knees, flat back, and lift by driving through your legs.","Stand tall, squeeze your glutes, then lower with control."]],"Sumo_Deadlift_with_Chains":[["علّق الجنازير في البار وقف بوقفة سومو واسعة ورجلك للخارج","امسك البار بقبضة ضيقة وضهرك مفرود وارفعه بدفع الرجلين","وقف عدل وشد الحوض وبعدين نزّله بتحكم"],["Hang chains on the bar and stand in a wide sumo stance, toes out.","Grip the bar inside your knees, flat back, and lift by driving through your legs.","Stand tall, squeeze your glutes, then lower with control."]],"Supine_Chest_Throw":[["ارقد على ضهرك وامسك الكرة بإيديك عند صدرك وركبك مثنية","ارميها لفوق بقوة بدفع الدراعين","امسكها وارجع بها لصدرك بتحكم وكرر"],["Lie on your back holding a ball at your chest, knees bent.","Throw the ball straight up forcefully with both arms.","Catch it and return to your chest with control, then repeat."]],"Supine_One-Arm_Overhead_Throw":[["ارقد على ضهرك وامسك الكرة بإيد واحدة ورا راسك وركبك مثنية","ارفع الدراع فوق صدرك وارمي الكرة لفوق بقوة","امسكها وارجع للوضع الأول وبدّل الدراع"],["Lie on your back, ball in one hand behind your head, knees bent.","Swing your arm up and throw the ball upward forcefully.","Catch it, return to start, and switch arms."]],"Supine_Two-Arm_Overhead_Throw":[["ارقد على ضهرك وامسك الكرة بإيديك الاتنين ورا راسك وركبك مثنية","ارفع الدراعين فوق صدرك وارمي الكرة لفوق بقوة","امسكها وارجع للوضع الأول وبطنك مشدودة"],["Lie on your back, ball in both hands behind your head, knees bent.","Swing your arms up and throw the ball upward forcefully.","Catch it and return to start, core braced."]],"Suspended_Fallout":[["اركع وامسك مقبضين معلقين بدراع مفرودة وجسمك مستقيم","افرد جسمك لقدام وانزل بالدراعين لحد ما يبقى جسمك مفرود","اسحب نفسك للوضع الأول وبطنك مشدودة وماتقوّسش ضهرك"],["Kneel holding suspended handles, arms straight, body in line.","Roll your body forward, extending your arms overhead as far as control allows.","Pull back to start with abs tight, never arching your back."]],"Suspended_Push-Up":[["امسك مقبضين معلقين وخد وضع بلانك مائل وجسمك مستقيم","انزل بصدرك ببطء ما بين المقبضين ومرفقك قريب من جسمك","ادفع لفوق لحد ما تفرد دراعك وبطنك مشدودة"],["Grip suspended handles and take a plank position, body straight.","Lower your chest slowly between the handles, elbows close to your body.","Press back up until arms are straight, abs tight."]],"Suspended_Reverse_Crunch":[["ارقد على ضهرك وحط رجلك في المقبضين المعلقة وإيدك جنبك","اثني ركبك وارفع حوضك لفوق ناحية صدرك بتحكم","نزّل ببطء وماتتأرجحش وخلي بطنك مشدودة"],["Lie on your back with feet in the suspended straps, hands at sides.","Bend your knees and curl your hips up toward your chest with control.","Lower slowly without swinging, abs tight."]],"Suspended_Row":[["امسك مقبضين معلقين وميّل جسمك لورا ودراعك مفرودة وجسمك مستقيم","اسحب صدرك ناحية المقبضين وشد لوحي الكتف","نزّل ببطء لحد ما تتفرد دراعك وخلي جسمك في خط مستقيم"],["Hold suspended handles, lean back with arms straight, body in line.","Pull your chest toward the handles, squeezing your shoulder blades.","Lower slowly until arms are straight, body in a straight line."]],"Suspended_Split_Squat":[["وقف ورا الحبل المعلق وحط رجلك الورانية في المقبض وإيدك على وسطك","انزل بالركبة الأمامية لحد ما فخدك توازي الأرض وضهرك مستقيم","ادفع بكعب رجلك اللي قدام وقف"],["Stand facing away, rear foot in the suspended strap, hands on hips.","Lower with the front knee until the thigh is parallel to the floor, torso upright.","Push through your front heel to stand."]],"Tate_Press":[["ارقد على بنش وامسك دامبل فوق صدرك بقبضة مغلقة ودراعك مفرودة","نزّل الدامبل ناحية صدرك بثني المرفق لبرة","ادفع لفوق لحد ما تفرد دراعك من غير قفل المرفق"],["Lie on a bench holding dumbbells over your chest, arms straight.","Lower the dumbbells toward your chest by bending the elbows outward.","Press up until arms are straight, without locking the elbows."]],"The_Straddle":[["اقعد على الأرض وافتح رجلك على الجنب قد ما تقدر وضهرك مستقيم","اميل لقدام من الحوض ودراعك قدامك على الأرض","ثبّت 20-30 ثانية وتنفس بهدوء وماتشدش بعنف"],["Sit on the floor with legs spread wide, back tall.","Hinge forward from the hips, walking your hands out in front.","Hold 20-30 seconds, breathing calmly, without forcing the stretch."]],"Tire_Flip":[["وقف قدام الإطار ورجلك واسعة وانحني وحط إيدك تحت حافته","ارفع الإطار بدفع الرجلين وبعدها ادفعه بصدرك وضهرك مفرود","اقلبه للجهة التانية وارجع واستعد لتكرار جديد"],["Stand facing the tire, feet wide, hinge down and grip under its edge.","Lift by driving your legs, then push it over with your chest, back flat.","Flip it fully, reset your stance, and repeat."]],"Torso_Rotation":[["وقف بقدميك بعرض الكتف وامسك عصا خفيفة على كتافك","لف جذعك ببطء لجنب وانت ثابت الحوض","ارجع للنص وبعدين لف للجنب التاني بتحكم"],["Stand feet shoulder-width, a light stick across your shoulders.","Rotate your torso slowly to one side, hips facing forward.","Return to center, then rotate to the other side with control."]],"Tricep_Side_Stretch":[["وقف عدل وارفع دراع فوق راسك وثني المرفق ورا راسك","امسك المرفق بإيدك التانية واسحبه بلطف لجنب","ثبّت 20-30 ثانية وبعدين بدّل الدراع"],["Stand tall, raise one arm overhead and bend the elbow behind your head.","Hold the elbow with your other hand and gently pull it sideways.","Hold 20-30 seconds, then switch arms."]],"Triceps_Overhead_Extension_with_Rope":[["وقف مدّي ضهرك للكابل وامسك الحبل فوق راسك ومرفقك لقدام","افرد دراعك لفوق وانت ثابت المرفق","رجّع الحبل ورا راسك ببطء وخلي بطنك مشدودة"],["Face away from the cable, hold the rope overhead, elbows forward.","Extend your arms upward, keeping your elbows still.","Lower the rope behind your head slowly, core braced."]],"Triceps_Pushdown_-_V-Bar_Attachment":[["وقف قدام الكابل العالي وامسك المقبض المثلث ومرفقك جنبك","اضغط المقبض لتحت لحد ما تفرد دراعك","ارجع ببطء لحد ما يتثني مرفقك 90 درجة وماتتأرجحش"],["Stand at the high cable and hold the V-bar, elbows at your sides.","Push the bar down until your arms are straight.","Return slowly to a 90-degree elbow bend without swinging."]],"Triceps_Stretch":[["وقف عدل وارفع دراع فوق راسك وثني المرفق ورا راسك","امسك المرفق بإيدك التانية واسحبه بلطف","ثبّت 20-30 ثانية وبعدين بدّل الدراع"],["Stand tall, raise one arm and bend the elbow behind your head.","Hold the elbow with the other hand and gently pull it back.","Hold 20-30 seconds, then switch arms."]],"Tuck_Crunch":[["ارقد على ضهرك وركبك مثنية وإيدك ورا راسك أو على صدرك","اثني ركبك ناحية صدرك وارفع كتافك لفوق","نزّل ببطء وخلي بطنك مشدودة وماتشدش رقبتك"],["Lie on your back, knees bent, hands behind your head or on your chest.","Pull your knees toward your chest as you lift your shoulders.","Lower slowly with abs tight, without pulling on your neck."]],"Two-Arm_Dumbbell_Preacher_Curl":[["اقعد على بنش بريتشر وامسك دامبل في كل إيد ودراعك مفرودة على الوسادة","اثني دراعك لفوق ناحية كتفك وانت ثابت المرفق","نزّلهم ببطء لحد ما يتفرد دراعك من غير قفل المرفق"],["Sit at a preacher bench holding a dumbbell in each hand, arms on the pad.","Curl both dumbbells toward your shoulders, elbows still.","Lower slowly until arms are nearly straight, without locking the elbows."]],"Two-Arm_Kettlebell_Clean":[["وقف وكيتل بيل بين رجليك وانحني بضهر مفرود وامسك المقبضين","اسحب الكيتل بيل لفوق بسرعة وقرب مرفقك من جسمك","استقبل الكيتل بيل على كتفك ووقف عدل"],["Stand with a kettlebell between your feet, hinge down with a flat back, and grip it.","Pull it up fast, keeping elbows close to your body.","Catch it at your shoulder and stand tall."]],"Two-Arm_Kettlebell_Jerk":[["وقف وامسك كيتل بيل عند الكتف بكل إيد وبطنك مشدودة","انزل شوية واندفع بقوة وارفع الكيتل بيل فوق راسك","ثبّتهم فوق راسك ودراعك مفرودة وبعدين نزّلهم بتحكم"],["Stand holding a kettlebell at each shoulder, core tight.","Dip slightly, drive up, and punch the kettlebells overhead.","Lock them out overhead, then lower with control."]],"Two-Arm_Kettlebell_Military_Press":[["وقف وامسك كيتل بيل عند الكتف بكل إيد وبطنك مشدودة","اضغط الكيتل بيل لفوق لحد ما تفرد دراعك","نزّلهم ببطء لحد الكتف وماتقوّسش ضهرك"],["Stand holding a kettlebell at each shoulder, core tight.","Press both kettlebells overhead until your arms are straight.","Lower slowly to your shoulders without arching your back."]],"Two-Arm_Kettlebell_Row":[["انحني من الورك وضهرك مفرود وامسك كيتل بيل في كل إيد","اسحب الكيتل بيل ناحية وسطك وشد لوحي الكتف","نزّلهم ببطء لحد ما يتفرد دراعك وماتدورش ضهرك"],["Hinge at the hips with a flat back, a kettlebell in each hand.","Pull the kettlebells toward your waist, squeezing your shoulder blades.","Lower slowly until arms are straight, never rounding your back."]],"Underhand_Cable_Pulldowns":[["اقعد قدام الجهاز وامسك البار بقبضة سفلية وكفك ناحيتك بعرض الكتف","اسحب البار لتحت ناحية صدرك وشد لوحي الكتف","ارجع لفوق ببطء لحد ما يتفرد دراعك"],["Sit at the pulldown and grip the bar underhand, shoulder-width, palms facing you.","Pull the bar down to your upper chest, squeezing your shoulder blades.","Return up slowly until your arms are straight."]],"Upper_Back-Leg_Grab":[["اقعد على الأرض وامسك رجلك بإيديك من ورا أو قدام","اسحب رجلك ناحيتك وقوّس ضهرك العلوي بلطف","ثبّت 20-30 ثانية وبعدين بدّل الجنب"],["Sit on the floor and grab one leg with both hands.","Pull it toward you and gently round your upper back.","Hold 20-30 seconds, then switch sides."]],"Upper_Back_Stretch":[["وقف أو اقعد وامسك إيدك قدامك وكفك لبرة","ادفع إيدك لقدام وقوّس ضهرك العلوي ودقنك لصدرك","ثبّت 20-30 ثانية وتنفس بهدوء"],["Stand or sit and clasp your hands in front of you, palms out.","Push your hands forward and round your upper back, chin toward chest.","Hold 20-30 seconds, breathing calmly."]],"Upright_Cable_Row":[["وقف قدام الكابل السفلي وامسك البار بقبضة بعرض الكتف","اسحب البار لفوق ناحية دقنك ومرفقك أعلى من إيدك","نزّله ببطء لحد ما تتفرد دراعك"],["Stand facing the low cable and grip the bar shoulder-width.","Pull it up toward your chin, elbows leading above hands.","Lower slowly until your arms are straight."]],"Upright_Row_-_With_Bands":[["اقف على الباند وامسكه بإيديك قدام فخدك بقبضة ضيقة","اسحب الباند لفوق ناحية دقنك ومرفقك أعلى من إيدك","نزّله ببطء لحد ما تتفرد دراعك"],["Stand on the band and hold it in front of your thighs, narrow grip.","Pull it up toward your chin, elbows leading above hands.","Lower slowly until your arms are straight."]],"Upward_Stretch":[["وقف عدل وقدميك بعرض الكتف وشبك إيدك","ارفع دراعك فوق راسك وكفك لأعلى وامط جسمك","ثبّت 20-30 ثانية وتنفس بهدوء"],["Stand tall, feet shoulder-width, and interlace your fingers.","Raise your arms overhead, palms up, and reach upward.","Hold 20-30 seconds, breathing calmly."]],"V-Bar_Pullup":[["امسك المقبض المثلث المعلق وعلّق جسمك ودراعك مفرودة","اسحب نفسك لفوق لحد ما دقنك يعدي المقبض","نزّل ببطء لحد ما تتفرد دراعك وماتتأرجحش"],["Grip the hanging V-bar and hang with arms straight.","Pull yourself up until your chin clears the handles.","Lower slowly until your arms are straight, without swinging."]],"Vertical_Swing":[["وقف بوقفة واسعة وامسك دامبل بإيديك الاتنين قدام ركبتك وضهرك مفرود","اندفع بالحوض واطلع بالدامبل لفوق لحد مستوى الصدر","نزّل الدامبل بتحكم بين رجليك وانحني من الورك"],["Stand wide, holding a dumbbell with both hands, back flat.","Drive your hips forward and swing the dumbbell up to chest height.","Let it swing back between your legs, hinging at the hips."]],"Weighted_Ball_Hyperextension":[["اقعد على الكورة السويسرية وإيدك على صدرك أو ماسكة ثقل","انزل بجذعك لقدام ببطء وضهرك مفرود","ارفع جذعك لحد ما يبقى في خط مستقيم وماتقوّسش ضهرك"],["Lie face-down on the stability ball, holding a weight at your chest.","Lower your torso slowly with a flat back.","Raise until your body is in a straight line, no overarching."]],"Weighted_Ball_Side_Bend":[["وقف جنب الكورة السويسرية وامسك ثقل بإيد ورجلك ثابتة","اثني جذعك للجنب ببطء ناحية الثقل","ارجع لفوق بشد الجنب وبطنك مشدودة"],["Stand tall with a weight in one hand, feet planted.","Bend sideways slowly toward the weighted side.","Return upright by squeezing your side abs, core braced."]],"Weighted_Bench_Dip":[["اقعد على حرف بنش وإيدك جنبك وحط ثقل على فخدك ورجلك مفرودة","انزل بجسمك لتحت بثني المرفق لحد 90 درجة","ادفع لفوق لحد ما تفرد دراعك من غير قفل المرفق"],["Sit on a bench edge, hands beside you, weight on your lap, legs extended.","Lower your body by bending elbows to 90 degrees.","Press up until arms are straight without locking the elbows."]],"Weighted_Crunches":[["ارقد على ضهرك وركبك مثنية وامسك كورة ميديسن على صدرك","ارفع كتافك لفوق بشد البطن","نزّل ببطء وماتشدش رقبتك"],["Lie on your back, knees bent, medicine ball held at your chest.","Lift your shoulders off the floor by contracting your abs.","Lower slowly, without pulling on your neck."]],"Weighted_Jump_Squat":[["وقف بقدميك بعرض الكتف وامسك ثقل خفيف عند الصدر أو على الكتف","انزل في سكوات ربع واقفز لفوق بقوة","انزل بنعومة بركب مثنية وكرر"],["Stand feet shoulder-width holding a light weight at your chest or shoulders.","Squat down a quarter and jump up explosively.","Land softly with bent knees and repeat."]],"Weighted_Pull_Ups":[["علّق نفسك على البار بقبضة أوسع من الكتف وثقل مربوط في وسطك","اسحب نفسك لفوق لحد ما دقنك يعدي البار","نزّل ببطء لحد ما تتفرد دراعك وماتتأرجحش"],["Hang from the bar with a grip wider than shoulders, weight belted at your waist.","Pull up until your chin clears the bar.","Lower slowly until arms are straight, without swinging."]],"Weighted_Sit-Ups_-_With_Bands":[["ارقد على ضهرك وركبك مثنية وامسك الباند والثقل على صدرك","اطلع بجذعك لفوق لحد ما تقعد بتحكم","نزّل ببطء وبطنك مشدودة وماتشدش رقبتك"],["Lie on your back, knees bent, band anchored, weight held at your chest.","Sit up to a seated position with control.","Lower slowly with abs tight, without pulling on your neck."]],"Weighted_Squat":[["شيل الثقل على كتافك أو قدام صدرك ووقف بعرض الكتف","انزل في سكوات لحد ما فخدك توازي الأرض وضهرك مفرود","اندفع لفوق بكعبك من غير قفل الركبة"],["Hold the weight on your shoulders or at your chest, feet shoulder-width.","Squat until thighs are parallel to the floor, back flat.","Drive up through your heels without locking your knees."]],"Wide-Grip_Barbell_Bench_Press":[["ارقد على البنش وامسك البار بقبضة أعرض من الكتف","فك البار ونزّله ببطء لحد وسط الصدر","ادفعه لفوق لحد ما تفرد دراعك من غير قفل المرفق"],["Lie on the bench and grip the bar wider than shoulders.","Unrack and lower the bar slowly to mid-chest.","Press up until arms are straight without locking the elbows."]],"Wide-Grip_Decline_Barbell_Bench_Press":[["اضبط البنش منخفض وارقد وامسك البار بقبضة أعرض من الكتف","فك البار ونزّله ببطء لحد أسفل الصدر","ادفعه لفوق لحد ما تفرد دراعك من غير قفل المرفق"],["Set the bench to decline, lie back, grip the bar wider than shoulders.","Unrack and lower the bar slowly to your lower chest.","Press up until arms are straight without locking the elbows."]],"Wide-Grip_Decline_Barbell_Pullover":[["اضبط بنش منخفض وارقد وامسك البار بقبضة واسعة ودراعك مفرودة فوق صدرك","نزّل البار ورا راسك بدراع شبه مفرودة وانت بتحس بشد","ارجع بالبار فوق صدرك بتحكم وبطنك مشدودة"],["Lie on a decline bench, grip the bar wide, arms over your chest.","Lower the bar back behind your head with nearly straight arms.","Return it over your chest with control, core braced."]],"Wide-Grip_Pulldown_Behind_The_Neck":[["اقعد قدام الجهاز وامسك البار بقبضة واسعة وجسمك مستقيم","اسحب البار لتحت ناحية مؤخرة الرقبة ببطء وبتحكم","ارجع لفوق ببطء لحد ما يتفرد دراعك وماتحركش راسك بعنف"],["Sit at the pulldown and grip the bar wide, body upright.","Pull the bar down slowly behind your neck, with control.","Return up slowly until arms are straight; avoid jerking your head."]],"Wide-Grip_Rear_Pull-Up":[["علّق نفسك على البار بقبضة واسعة ودراعك مفرودة","اسحب نفسك لفوق لحد ما مؤخرة راسك تقرب البار","نزّل ببطء لحد ما تتفرد دراعك وماتتأرجحش"],["Hang from the bar with a wide grip, arms straight.","Pull up until the back of your head nears the bar.","Lower slowly until arms are straight, without swinging."]],"Wide-Grip_Standing_Barbell_Curl":[["وقف وامسك البار بقبضة أوسع من الكتف وكفك لقدام ودراعك مفرودة","اثني دراعك لفوق ناحية كتفك وانت ثابت المرفق","نزّله ببطء لحد ما يتفرد دراعك وماتتأرجحش"],["Stand holding the bar with a grip wider than shoulders, palms forward, arms straight.","Curl the bar toward your shoulders, elbows still.","Lower slowly until arms are straight, without swinging."]],"Wide_Stance_Barbell_Squat":[["شيل البار على ضهرك ووقف بوقفة أوسع من الكتف ورجلك للخارج","انزل في سكوات لحد ما فخدك توازي الأرض وضهرك مفرود","اندفع لفوق بكعبك وركبك مع اتجاه صوابعك"],["Rest the bar on your upper back, stance wider than shoulders, toes out.","Squat until thighs are parallel to the floor, back flat.","Drive up through your heels, knees tracking over toes."]],"Wide_Stance_Stiff_Legs":[["وقف بوقفة واسعة وامسك البار قدام فخدك وركبك مثنية شوية","انحني من الورك ونزّل البار على رجلك وضهرك مفرود","اطلع بشد الحوض لقدام وماتدورش ضهرك"],["Stand wide holding the bar in front of your thighs, knees slightly bent.","Hinge at the hips, sliding the bar down your legs, back flat.","Drive your hips forward to stand, never rounding your back."]],"Wind_Sprints":[["وقف في وضع الاستعداد وركبك مثنية شوية","اجري بأقصى سرعة لمسافة قصيرة وإيدك بتتحرك مع الجري","وقف وارتاح وتنفس وكرر"],["Get into a ready stance, knees slightly bent.","Sprint at top speed for a short distance, arms driving.","Slow to a stop, rest and breathe, then repeat."]],"Windmills":[["وقف بوقفة واسعة وارفع دراعك على الجنب","انحني ولف جذعك ولمس رجلك المعاكسة بإيدك والإيد التانية لفوق","ارجع لوقفة عدل وبدّل الجنب بتحكم وركبك مفرودة شوية"],["Stand wide and raise your arms out to the sides.","Bend and rotate, reaching one hand to the opposite foot, other arm up.","Return upright and switch sides with control, knees slightly soft."]],"Worlds_Greatest_Stretch":[["خد وضع لانج عميق برجل قدام وإيدك على الأرض جنبها","لف جذعك وارفع دراع ناحية السقف وانت بتبص عليه","ارجع بإيدك وبدّل الجنب وثبّت 20-30 ثانية"],["Step into a deep lunge, hands on the floor beside your front foot.","Rotate your torso and reach one arm up toward the ceiling.","Return, switch sides, and hold 20-30 seconds."]],"Wrist_Circles":[["وقف أو اقعد وافرد دراعك قدامك وإيدك مسترخية","لف رسغك في دايرة بطيئة في اتجاه","اعمل الدايرة في الاتجاه التاني وكرر"],["Stand or sit with your arms extended in front, hands relaxed.","Rotate your wrists in slow circles in one direction.","Repeat in the opposite direction."]],"Wrist_Roller":[["وقف وامسك العصا بإيديك الاتنين ودراعك مفرودة قدامك والوزن متدلي","لف العصا بإيديك لتلف الحبل ورفع الوزن لفوق","نزّل الوزن ببطء بتحكم وبنفس الحركة المعاكسة"],["Stand holding the roller with both hands, arms extended, weight hanging.","Twist the bar to wind the rope and raise the weight.","Lower the weight slowly by unwinding with control."]],"Wrist_Rotations_with_Straight_Bar":[["اقعد وساعدك مسنود على فخدك وماسك البار بكفك لأسفل","لف البار بالرسغ لفوق وتحت بتحكم","كرر الحركة بتحكم وخلي ساعدك ثابت"],["Sit with your forearms on your thighs, holding the bar palms down.","Rotate the bar with your wrists, up and down, with control.","Repeat smoothly, keeping your forearms still."]],"Yoke_Walk":[["ادخل تحت النير وخلي الحمل على كتافك وضهرك مفرود","اشيل النير وامشي بخطوات قصيرة ومتحكمة","حافظ على بطنك مشدودة وصدرك مفتوح لحد ما توصل وانزل الحمل بحذر"],["Step under the yoke, load on your upper back, spine neutral.","Lift it and walk with short, controlled steps.","Keep abs tight and chest up, then lower carefully at the end."]],"Zercher_Squats":[["شيل البار في ثنية دراعك قدام بطنك ووقف بعرض الكتف","انزل في سكوات لحد ما فخدك توازي الأرض وضهرك مفرود","اندفع لفوق بكعبك وركبك مع اتجاه صوابعك"],["Cradle the bar in the crooks of your elbows in front of your torso, feet shoulder-width.","Squat until thighs are parallel to the floor, back flat.","Drive up through your heels, knees tracking over toes."]],"Zottman_Curl":[["وقف وامسك دامبل في كل إيد وكفك لقدام ومرفقك جنبك","اثني دراعك لفوق بكف لفوق وبعدين لف الكف لتحت عند القمة","نزّل ببطء وكفك لتحت لحد ما يتفرد دراعك"],["Stand holding dumbbells, palms forward, elbows tucked.","Curl up with palms up, then rotate palms down at the top.","Lower slowly with palms down until arms are straight."]],"Zottman_Preacher_Curl":[["اقعد على بنش بريتشر وامسك دامبل في كل إيد ودراعك على الوسادة","اثني دراعك لفوق بكف لفوق وبعدين لف الكف لتحت عند القمة","نزّل ببطء وكفك لتحت لحد ما يتفرد دراعك"],["Sit at a preacher bench holding dumbbells, arms on the pad.","Curl up with palms up, then rotate palms down at the top.","Lower slowly with palms down until arms are straight."]]};
